function getWorldMetaForRoute(routeId, index) {
  if (routeId === 'ruta_2') return A2_WORLD_META[index] || WORLD_META[index] || { id: `world_${index + 1}`, emoji: '🛣️', title: `M${index + 1} · A2`, subtitle: 'Mundo A2.' };
  if (routeId === 'ruta_3') return B1_WORLD_META[index] || WORLD_META[index] || { id: `world_${index + 1}`, emoji: '🧭', title: `M${index + 1} · B1`, subtitle: 'Mundo B1.' };
  if (routeId === 'ruta_4') return B2_WORLD_META[index] || WORLD_META[index] || { id: `world_${index + 1}`, emoji: '🚀', title: `M${index + 1} · B2`, subtitle: 'Mundo B2.' };
  return WORLD_META[index] || { id: `world_${index + 1}`, emoji: '🌍', title: `M${index + 1}`, subtitle: 'Mundo de práctica.' };
}

