function getDeepIntegratorKey(worldId) {
  const n = getWorldNumberFromId(worldId);
  return n ? `M${n}` : '';
}

function isDeepIntegratorWorld(worldId, routeId = state.progress.currentRouteId) {
  const n = getWorldNumberFromId(worldId);
  if (routeId === 'ruta_4') return n >= 1 && n <= 30;
  if (routeId === 'ruta_1') return n >= 11 && n <= 30;
  return false;
}

function getDeepIntegratorDialogue(worldId, routeId = state.progress.currentRouteId) {
  const key = getDeepIntegratorKey(worldId);
  if (!key) return null;
  if (routeId === 'ruta_4') return deepIntegratorDialogues.find(item => item.id === `B2-${key}` && item.routeId === 'ruta_4') || null;
  if (routeId === 'ruta_1') return deepIntegratorDialogues.find(item => item.id === key && (item.routeId === 'ruta_1' || !item.routeId)) || null;
  return null;
}

function getDeepIntegratorProgress() {
  try {
    return JSON.parse(localStorage.getItem('deepIntegratorProgress') || '{}') || {};
  } catch (error) {
    return {};
  }
}

function saveDeepIntegratorProgress(worldKey, patch = {}) {
  const progress = getDeepIntegratorProgress();
  progress[worldKey] = { ...(progress[worldKey] || {}), ...patch };
  localStorage.setItem('deepIntegratorProgress', JSON.stringify(progress));
}

function getDeepCharacter(dialogue, speakerId) {
  return (dialogue.characters || []).find(character => character.id === speakerId) || { id: speakerId, name: speakerId || 'Speaker', avatar: '🧑' };
}

function buildDeepSceneLines(dialogue, responses = [], stepIndex = 0, includeCurrentPrompt = true) {
  const lines = [];
  const currentAnswered = Boolean(responses[stepIndex]?.correct);
  const max = Math.min(stepIndex + (currentAnswered ? 1 : 0), dialogue.steps.length);
  for (let i = 0; i < max; i += 1) {
    lines.push({ type: 'prompt', ...dialogue.steps[i].prompt });
    if (responses[i]?.correct) lines.push({ type: 'reply', ...responses[i] });
    else lines.push({ type: 'reply', ...dialogue.steps[i].correctReply });
  }
  if (includeCurrentPrompt && !currentAnswered && stepIndex < dialogue.steps.length) {
    lines.push({ type: 'prompt', ...dialogue.steps[stepIndex].prompt, active: true });
  }
  return lines;
}

function renderDeepSceneLines(dialogue, lines = []) {
  return lines.map((line, index) => {
    const character = getDeepCharacter(dialogue, line.speaker);
    return `<div class="deep-line ${line.type === 'reply' ? 'reply' : 'prompt'} ${line.active ? 'active' : ''}" id="${line.active ? 'deep-active-line' : ''}">
      <div class="deep-avatar">${escapeHtml(character.avatar || '🧑')}</div>
      <div class="deep-bubble">
        <strong>${escapeHtml(character.name || line.speaker)}</strong>
        <p class="deep-en">${escapeHtml(line.en || '')}</p>
        <p class="deep-es">${escapeHtml(line.es || '')}</p>
      </div>
    </div>`;
  }).join('');
}

function renderDeepOptionButtons(step, response) {
  return (step.options || []).map((option, index) => {
    let cls = 'conversation-option deep-option';
    if (response) {
      if (option.correct) cls += ' is-correct';
      if (response.selectedIndex === index && !response.correct) cls += ' is-wrong';
      if (response.selectedIndex === index) cls += ' is-selected';
    }
    return `<button class="${cls}" data-deep-option-index="${index}" ${response?.correct ? 'disabled' : ''}>
      <span>${escapeHtml(option.en || '')}</span>
      <small>${escapeHtml(option.es || '')}</small>
      ${response && option.correct ? '<b class="ok-check">✓</b>' : ''}
    </button>`;
  }).join('');
}


function getWorldReinforcementStatus(world, lessonId) {
  const lessonIds = Array.isArray(world?.lessonIds) ? world.lessonIds : [lessonId].filter(Boolean);
  const pronAttempts = Array.isArray(state.progress?.pronunciationAttempts) ? state.progress.pronunciationAttempts : [];
  const pronunciationDone = pronAttempts.some(item => lessonIds.includes(item?.lessonId));
  const rewards = state.progress?.gameRewards;
  const completedGameKeys = Array.isArray(rewards?.completedKeys) ? rewards.completedKeys : [];
  const gameDone = lessonIds.some(id => completedGameKeys.some(key => String(key || '').endsWith(`::${id}`)));
  const videosAvailable = world?.id ? getVideosByWorld(world.id).length : 0;
  const musicAvailable = world?.id ? getMusicVideosByWorld(world.id, world.routeId || state.progress.currentRouteId).length : 0;
  return { pronunciationDone, gameDone, videosAvailable, musicAvailable };
}

function renderWorldCompletionCard({ title, subtitle, conversationId, world, lastLessonId, navContext, nextWorldLabel, pending = [], deep = false }) {
  const status = getWorldReinforcementStatus(world, lastLessonId);
  const nextLabel = nextWorldLabel || 'Siguiente mundo';
  return `
    <section class="conversation-shell view-grid conversation-finish world-complete-shell">
      <article class="status-card world-complete-card">
        <div class="world-complete-badge" aria-hidden="true">🎉</div>
        <span class="section-kicker">${deep ? 'Diálogo profundo terminado' : 'Diálogo integrador terminado'}</span>
        <h2>${escapeHtml(title)}</h2>
        <p class="muted world-complete-short">${escapeHtml(subtitle || 'Refuerza antes de avanzar.')}</p>
        <div class="world-complete-mini-status">
          ${pending.length ? `<span class="tiny-pill is-warning">🧠 ${pending.length} por reforzar</span>` : '<span class="tiny-pill is-ok">✅ diálogo listo</span>'}
          <span class="tiny-pill ${status.pronunciationDone ? 'is-ok' : 'is-pending'}">🎙️ ${status.pronunciationDone ? 'practicado' : 'pendiente'}</span>
          <span class="tiny-pill ${status.gameDone ? 'is-ok' : 'is-pending'}">🎮 ${status.gameDone ? 'jugado' : 'disponible'}</span>
        </div>
        <div class="reinforcement-grid" aria-label="Refuerzos disponibles">
          ${pending.length ? `<button type="button" class="reinforcement-action is-pending" id="conversation-reinforce-now"><span>🧠</span><strong>Reforzar</strong><small>respuestas</small></button>` : ''}
          <button type="button" class="reinforcement-action ${status.pronunciationDone ? 'is-done' : 'is-pending'}" id="conversation-go-pronunciation"><span>🎙️</span><strong>Pronunciación</strong><small>${status.pronunciationDone ? 'hecha' : 'practicar'}</small></button>
          ${status.videosAvailable ? `<button type="button" class="reinforcement-action is-pending" id="conversation-go-video"><span>🎥</span><strong>Video</strong><small>ver apoyo</small></button>` : ''}
          ${status.musicAvailable ? `<button type="button" class="reinforcement-action is-pending" id="conversation-go-music"><span>${getMusicVideoIcon()}</span><strong>Canción</strong><small>subtitulada</small></button>` : ''}
          <button type="button" class="reinforcement-action ${status.gameDone ? 'is-done' : 'is-pending'}" id="conversation-go-game"><span>🎮</span><strong>Juego</strong><small>${status.gameDone ? 'hecho' : 'jugar'}</small></button>
        </div>
        <div class="world-complete-actions">
          ${deep ? `<button class="btn btn-soft" id="conversation-repeat-deep">🔁 Repetir diálogo</button>` : ''}
          <button class="btn btn-primary world-next-btn" id="conversation-next-world">🚌 ${escapeHtml(nextLabel)}</button>
          <button class="btn btn-soft route-main-btn" id="conversation-go-route"><span class="game-nav-icon" aria-hidden="true">🛣️</span><span class="game-nav-text">Ruta</span></button>
        </div>
      </article>
    </section>`;
}

function bindWorldCompletionActions({ conversation, world, lastLessonId, pending = [] }) {
  document.getElementById('conversation-reinforce-now')?.addEventListener('click', () => startConversationReinforcement(conversation.worldId, conversation.id));
  document.getElementById('conversation-go-pronunciation')?.addEventListener('click', () => {
    if (lastLessonId) openPronunciationPractice(lastLessonId);
  });
  document.getElementById('conversation-go-video')?.addEventListener('click', () => {
    if (world?.id) openWorldVideoModal(world.id);
  });
  document.getElementById('conversation-go-music')?.addEventListener('click', () => {
    if (world?.id) openWorldMusicVideoModal(world.id, world.routeId || conversation.routeId || state.progress.currentRouteId);
  });
  maybePromptExperienceRating('world_complete', { worldId: world?.id || conversation.worldId, routeId: world?.routeId || conversation.routeId || state.progress.currentRouteId });
  document.getElementById('conversation-go-game')?.addEventListener('click', () => {
    const lessonId = lastLessonId || world?.lessonIds?.[0];
    if (lessonId) setView('game', { lessonId, worldId: world?.id || conversation.worldId, routeId: conversation.routeId || state.progress.currentRouteId || 'ruta_1' });
  });
  document.getElementById('conversation-repeat-deep')?.addEventListener('click', () => {
    const dialogue = getDeepIntegratorDialogue(conversation.worldId, conversation.routeId || state.progress.currentRouteId);
    if (dialogue) saveDeepIntegratorProgress(dialogue.id, { currentStep: 0, completed: false, completedAt: null });
    setView('conversation', { conversationId: conversation.id, routeId: conversation.routeId || state.progress.currentRouteId, worldId: conversation.worldId, lessonId: lastLessonId || conversation.lessonId, deepStep: 0, deepResponses: [] });
  });
  document.getElementById('conversation-next-world')?.addEventListener('click', () => goToNextWorldFirstLesson(world));
  document.getElementById('conversation-go-route')?.addEventListener('click', () => goToVisibleRoutePoint(conversation.worldId));
}

function renderDeepIntegratorConversation(conversation, world, navContext, nextWorldLabel, pending) {
  const dialogue = getDeepIntegratorDialogue(conversation.worldId, conversation.routeId || state.progress.currentRouteId);
  if (!dialogue) return false;
  const responses = Array.isArray(ui.payload.deepResponses) ? ui.payload.deepResponses : [];
  const stepIndex = Math.min(Number(ui.payload.deepStep || 0), Math.max(0, dialogue.steps.length - 1));
  const finished = Boolean(ui.payload.finished);
  if (finished) {
    $main.innerHTML = renderWorldCompletionCard({
      title: `💬 ${dialogue.world} · ${dialogue.title}`,
      subtitle: 'Refuerza antes de avanzar.',
      conversationId: conversation.id,
      world,
      lastLessonId: world?.lessonIds?.[world.lessonIds.length - 1] || conversation.lessonId,
      navContext,
      nextWorldLabel,
      pending,
      deep: true
    });
    bindWorldCompletionActions({
      conversation,
      world,
      lastLessonId: world?.lessonIds?.[world.lessonIds.length - 1] || conversation.lessonId,
      pending
    });
    return true;
  }
  const step = dialogue.steps[stepIndex];
  const response = responses[stepIndex];
  const progressPercent = Math.round(((stepIndex + (response?.correct ? 1 : 0)) / dialogue.steps.length) * 100);
  const sceneLines = buildDeepSceneLines(dialogue, responses, stepIndex, true);
  $main.innerHTML = `
    <section class="conversation-shell view-grid deep-integrator-shell guided-deep-shell scene-active">
      <article class="status-card conversation-hero">
        <div class="conversation-topline">
          <span class="section-kicker">Diálogo integrador profundo · M${getWorldNumberFromId(conversation.worldId)}</span>
          <span class="pill">${stepIndex + 1}/${dialogue.steps.length}</span>
        </div>
        <div class="compact-inline-head">
          <h2>💬 ${escapeHtml(dialogue.title)}</h2>
        </div>
        <p class="conversation-visible-instruction">Escucha la línea activa. Luego elige la respuesta que continúa mejor la escena.</p>
        <div class="progress-bar spacer-top"><div class="progress-fill" style="width:${progressPercent}%"></div></div>
      </article>
      <section class="deep-stage guided-deep-stage">
        <article class="deep-scene-panel conversation-focus-card" id="deep-scene-panel">
          <span class="section-kicker">Escena acumulada</span>
          <div class="deep-scene">${renderDeepSceneLines(dialogue, sceneLines)}</div>
          <button class="btn btn-soft btn-small conversation-speak-pulse deep-speak-focus-btn" id="deep-speak-line">🔊 Escuchar línea</button>
        </article>
        <article class="conversation-answer-card deep-options-panel conversation-focus-card" id="deep-answer-panel">
          <span class="section-kicker">Elige la mejor respuesta</span>
          <div class="deep-audio-mode-row" role="group" aria-label="Modo de escucha del diálogo">
            <span>Audio</span>
            <button type="button" class="deep-audio-mode ${getDeepAudioMode() === 'en' ? 'active' : ''}" data-deep-audio-mode="en">🔊 Inglés</button>
            <button type="button" class="deep-audio-mode ${getDeepAudioMode() !== 'en' ? 'active' : ''}" data-deep-audio-mode="en-es">EN–ES</button>
          </div>
          <div class="conversation-options">${renderDeepOptionButtons(step, response)}</div>
        </article>
      </section>
      <nav class="conversation-action-row conversation-action-row-standard" aria-label="Acciones del diálogo profundo">
        <button class="conversation-nav-btn" id="deep-back-lesson" title="Volver" aria-label="Volver">←</button>
        <button class="conversation-nav-btn route-icon-btn" id="conversation-back-route" title="Ruta" aria-label="Ruta">🛣️</button>
        <button class="conversation-nav-btn conversation-next ${response?.correct ? 'is-functional conversation-continue-ready' : ''}" id="deep-continue-btn" title="${response?.correct ? (stepIndex + 1 >= dialogue.steps.length ? 'Completar diálogo' : 'Continuar escena') : 'Elige la respuesta correcta para avanzar'}" aria-label="Continuar" ${response?.correct ? '' : 'disabled'}>${response?.correct ? 'Continuar →' : '→'}</button>
      </nav>
    </section>`;
  const deepShell = document.querySelector('.guided-deep-shell');
  const deepScenePanel = document.getElementById('deep-scene-panel');
  const deepAnswerPanel = document.getElementById('deep-answer-panel');
  const focusDeepAnswer = () => {
    deepShell?.classList.remove('scene-active');
    deepShell?.classList.add('answer-active');
    deepAnswerPanel?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  };
  const focusDeepScene = () => {
    deepShell?.classList.remove('answer-active');
    deepShell?.classList.add('scene-active');
    document.getElementById('deep-active-line')?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  };
  document.querySelectorAll('[data-deep-option-index]').forEach(btn => btn.addEventListener('click', () => handleDeepIntegratorAnswer(conversation.id, stepIndex, Number(btn.dataset.deepOptionIndex))));
  document.getElementById('deep-continue-btn')?.addEventListener('click', () => {
    if (!response?.correct) return;
    advanceDeepIntegrator(conversation.id);
  });
  document.getElementById('deep-back-lesson')?.addEventListener('click', () => setView('lesson', { lessonId: lastLessonId || state.progress.lastLessonId || getCurrentLesson()?.id }));
  document.getElementById('conversation-back-route')?.addEventListener('click', () => setView('route', { routeId: state.progress.currentRouteId, scrollTo: conversation.worldId, showAllSections: true }));
  document.querySelectorAll('[data-deep-audio-mode]').forEach(btn => btn.addEventListener('click', () => { setDeepAudioMode(btn.dataset.deepAudioMode); renderApp(); }));
  const playDeepLine = () => {
    speakDeepIntegratorLine(step.prompt.en, step.prompt.es);
    window.setTimeout(focusDeepAnswer, 260);
  };
  document.getElementById('deep-speak-line')?.addEventListener('click', (event) => {
    event.stopPropagation();
    playDeepLine();
  });
  deepScenePanel?.addEventListener('click', (event) => {
    if (event.target.closest('button')) return;
    playDeepLine();
  });
  window.setTimeout(focusDeepScene, 90);
  return true;
}

function handleDeepIntegratorAnswer(conversationId, stepIndex, selectedIndex) {
  const conversation = getConversationById(conversationId);
  const dialogue = getDeepIntegratorDialogue(conversation?.worldId, conversation?.routeId || state.progress.currentRouteId);
  if (!conversation || !dialogue) return;
  const step = dialogue.steps[stepIndex];
  const selectedOption = step.options[selectedIndex];
  if (!selectedOption) return;
  const correctOption = step.options.find(option => option.correct) || step.correctReply;
  const responses = Array.isArray(ui.payload.deepResponses) ? ui.payload.deepResponses.slice() : [];
  const correct = Boolean(selectedOption.correct);
  responses[stepIndex] = {
    selectedIndex,
    correct,
    en: correct ? step.correctReply.en : selectedOption.en,
    es: correct ? step.correctReply.es : selectedOption.es,
    speaker: step.correctReply.speaker,
    feedback: correct
      ? 'Correcto. Esta respuesta continúa la conversación de forma natural.'
      : 'Esta opción no sigue bien el hilo del diálogo. Busca una respuesta que conecte con lo que la otra persona acaba de decir.'
  };
  const reinforcementTurn = { id: `deep_step_${stepIndex + 1}`, left: step.prompt.en, leftEs: step.prompt.es, options: step.options.map(option => ({ text: option.en, es: option.es, correct: Boolean(option.correct), feedback: '' })) };
  if (!correct) {
    registerConversationMistake(
      conversation,
      reinforcementTurn,
      { text: selectedOption.en, es: selectedOption.es, feedback: responses[stepIndex].feedback },
      { text: correctOption.en || step.correctReply.en, es: correctOption.es || step.correctReply.es, feedback: 'Respuesta natural.' }
    );
  } else {
    resolveConversationReinforcementForTurn(conversation, reinforcementTurn, 'deep_conversation_correct');
  }
  saveDeepIntegratorProgress(dialogue.id, { currentStep: stepIndex, completed: false });
  setView('conversation', { ...ui.payload, conversationId, worldId: conversation.worldId, deepStep: stepIndex, deepResponses: responses });
  if (correct) {
    // Pausa pedagógica real: no avanza automáticamente.
    // Lee la opción que el usuario eligió para que pueda verla y escucharla.
    speakEnglishSpanish(selectedOption.en || step.correctReply?.en || '', selectedOption.es || step.correctReply?.es || '', { gap: 650 });
  }
}

function retryDeepIntegratorStep(conversationId, stepIndex) {
  const responses = Array.isArray(ui.payload.deepResponses) ? ui.payload.deepResponses.slice() : [];
  responses[stepIndex] = null;
  setView('conversation', { ...ui.payload, conversationId, deepStep: stepIndex, deepResponses: responses });
}

function advanceDeepIntegrator(conversationId) {
  const conversation = getConversationById(conversationId);
  const dialogue = getDeepIntegratorDialogue(conversation?.worldId, conversation?.routeId || state.progress.currentRouteId);
  if (!conversation || !dialogue) return;
  const responses = Array.isArray(ui.payload.deepResponses) ? ui.payload.deepResponses.slice() : [];
  const stepIndex = Number(ui.payload.deepStep || 0);
  if (stepIndex + 1 >= dialogue.steps.length) {
    saveDeepIntegratorProgress(dialogue.id, { currentStep: dialogue.steps.length, completed: true });
    completeConversation(conversationId, responses);
    setView('conversation', { conversationId, worldId: conversation.worldId, deepStep: stepIndex, deepResponses: responses, finished: true });
    return;
  }
  const nextStep = stepIndex + 1;
  saveDeepIntegratorProgress(dialogue.id, { currentStep: nextStep, completed: false });
  setView('conversation', { ...ui.payload, conversationId, worldId: conversation.worldId, deepStep: nextStep, deepResponses: responses });
}

function renderConversation() {
  const conversation = getConversationById(ui.payload.conversationId, ui.payload.routeId || state.progress.currentRouteId) || getConversationByWorldId(ui.payload.worldId, ui.payload.routeId || state.progress.currentRouteId);
  if (!conversation) {
    $main.innerHTML = `<section class="card empty-state"><h2>Conversación no disponible</h2><p class="muted">Este mundo todavía no tiene diálogo integrador.</p><button class="btn btn-primary" id="conversation-back-dashboard">Carretera</button></section>`;
    document.getElementById('conversation-back-dashboard')?.addEventListener('click', () => goToRoadHome());
    return;
  }
  const world = getBasicWorldById(state.progress.currentRouteId, conversation.worldId) || getBasicWorldForLesson((conversation.lessonIds || [conversation.lessonId])[0]);
  const lastLessonId = world?.lessonIds?.[world.lessonIds.length - 1] || (conversation.lessonIds || [conversation.lessonId]).filter(Boolean).slice(-1)[0];
  const navContext = getNavigationContextForWorld(world);
  const nextWorldLabel = navContext.nextWorldLesson ? `Ir a M${(world?.index ?? 0) + 2} · lección 1` : 'Seguir ruta';
  const responses = Array.isArray(ui.payload.responses) ? ui.payload.responses : [];
  const pending = getPendingConversationReinforcement(conversation.worldId, state.progress.currentRouteId, conversation.id);
  if (isDeepIntegratorWorld(conversation.worldId) && renderDeepIntegratorConversation(conversation, world, navContext, nextWorldLabel, pending)) return;
  if (ui.payload.finished) {
    $main.innerHTML = renderWorldCompletionCard({
      title: `💬 ${conversation.title}`,
      subtitle: 'Refuerza antes de avanzar.',
      conversationId: conversation.id,
      world,
      lastLessonId,
      navContext,
      nextWorldLabel,
      pending
    });
    bindWorldCompletionActions({ conversation, world, lastLessonId, pending });
    return;
  }
  const turnIndex = Math.min(Number(ui.payload.turnIndex || 0), Math.max(0, (conversation.turns || []).length - 1));
  const turn = conversation.turns[turnIndex];
  const response = responses[turnIndex];
  const progressPercent = conversation.turns?.length ? Math.round(((turnIndex + (response ? 1 : 0)) / conversation.turns.length) * 100) : 0;
  const conversationFocusClass = response?.correct ? 'speaker-active' : 'speaker-active';
  $main.innerHTML = `
    <section class="conversation-shell view-grid guided-conversation-shell ${conversationFocusClass}">
      <article class="status-card conversation-hero guided-conversation-hero">
        <div class="conversation-topline">
          <span class="section-kicker">Diálogo integrador · ${escapeHtml(conversation.level || 'A1-base')}</span>
          <span class="pill">${turnIndex + 1}/${conversation.turns.length}</span>
        </div>
        <div class="compact-inline-head conversation-headline-row">
          <h2>💬 ${escapeHtml(conversation.title)}</h2>
        </div>
        <p class="conversation-visible-instruction">Escucha primero. Luego toca tu respuesta. El diálogo avanzará paso a paso.</p>
        <div class="progress-bar spacer-top"><div class="progress-fill" style="width:${progressPercent}%"></div></div>
      </article>
      <section class="conversation-stage guided-conversation-stage">
        <article class="conversation-speaker-card conversation-focus-card" id="conversation-speaker-card">
          <span class="section-kicker">La otra persona dice</span>
          <div class="conversation-line">${escapeHtml(turn.left)}</div>
          ${turn.leftEs ? `<p class="muted">${escapeHtml(turn.leftEs)}</p>` : ''}
          <button class="btn btn-soft btn-small conversation-speak-pulse" id="conversation-speak-line">🔊 Escuchar</button>
        </article>
        <article class="conversation-answer-card conversation-focus-card" id="conversation-answer-card">
          <span class="section-kicker">Tu posible respuesta</span>
          <div class="conversation-options">${renderConversationOptionButtons(turn, response, conversation.id, turnIndex)}</div>
        </article>
      </section>
      <nav class="conversation-action-row conversation-action-row-standard" aria-label="Acciones del diálogo">
        <button class="conversation-nav-btn" id="conversation-back-lesson" title="Volver" aria-label="Volver">←</button>
        <button class="conversation-nav-btn route-icon-btn" id="conversation-back-route" title="Ruta" aria-label="Ruta">🛣️</button>
        <button class="conversation-nav-btn conversation-next ${response?.correct ? 'is-functional conversation-continue-ready' : ''}" id="conversation-continue-btn" title="${response?.correct ? (turnIndex + 1 >= conversation.turns.length ? 'Cerrar diálogo' : 'Continuar') : 'Elige una respuesta correcta para avanzar'}" aria-label="Continuar" ${response?.correct ? '' : 'disabled'}>${response?.correct ? 'Continuar →' : '→'}</button>
      </nav>
    </section>`;
  const conversationShell = document.querySelector('.guided-conversation-shell');
  const speakerCard = document.getElementById('conversation-speaker-card');
  const answerCard = document.getElementById('conversation-answer-card');
  const focusAnswer = () => {
    conversationShell?.classList.remove('speaker-active');
    conversationShell?.classList.add('answer-active');
    answerCard?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  };
  const focusSpeaker = () => {
    conversationShell?.classList.remove('answer-active');
    conversationShell?.classList.add('speaker-active');
    speakerCard?.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
  };
  speakerCard?.addEventListener('click', (event) => {
    if (event.target.closest('button')) return;
    focusAnswer();
  });
  document.querySelectorAll('.conversation-option').forEach(btn => btn.addEventListener('click', () => handleConversationAnswer(conversation.id, turnIndex, Number(btn.dataset.optionIndex))));
  document.getElementById('conversation-continue-btn')?.addEventListener('click', () => {
    if (!response?.correct) return;
    advanceConversation(conversation.id);
  });
  document.getElementById('conversation-back-lesson')?.addEventListener('click', () => setView('lesson', { lessonId: state.progress.lastLessonId || getCurrentLesson()?.id }));
  document.getElementById('conversation-back-route')?.addEventListener('click', () => setView('route', { routeId: state.progress.currentRouteId, scrollTo: conversation.worldId, showAllSections: true }));
  document.getElementById('conversation-speak-line')?.addEventListener('click', () => {
    speakEnglish(turn.left);
    window.setTimeout(focusAnswer, 260);
  });
}
function renderConversationReinforcement() {
  const scope = ui.payload.scope || ui.payload.worldId || ui.payload.lessonId || null;
  const routeId = ui.payload.routeId || state.progress.currentRouteId || 'ruta_1';
  const pending = getPendingConversationReinforcement(scope, routeId, ui.payload.conversationId || null);
  const index = Math.min(Number(ui.payload.index || 0), Math.max(0, pending.length - 1));
  const item = pending[index];
  if (!item) {
    setView('dashboard');
    return;
  }
  const feedback = ui.payload.lastFeedback;
  const world = item.worldId ? getBasicWorldById(state.progress.currentRouteId, item.worldId) : null;
  $main.innerHTML = `
    <section class="conversation-shell view-grid">
      <article class="status-card conversation-hero">
        <span class="section-kicker">Refuerzo de conversación</span>
        <h2>🧠 Reforcemos ${index + 1}/${pending.length}</h2>
        <p class="muted">${world ? escapeHtml(world.title) : 'Estas respuestas vienen de tus conversaciones recientes.'}</p>
      </article>
      <section class="conversation-stage">
        <article class="conversation-speaker-card">
          <span class="section-kicker">La otra persona dice</span>
          <div class="conversation-line">${escapeHtml(item.left)}</div>
          ${item.leftEs ? `<p class="muted">${escapeHtml(item.leftEs)}</p>` : ''}
          <p class="muted">Elegiste: <strong>${escapeHtml(item.selectedText)}</strong></p>
        </article>
        <article class="conversation-answer-card">
          <span class="section-kicker">Tu mejor respuesta</span>
          <div class="conversation-options">
            ${(item.options || []).map((option, optionIndex) => {
              let cls = 'conversation-option';
              if (feedback) {
                if (option.correct) cls += ' is-correct';
                if (feedback.optionIndex === optionIndex && !feedback.correct) cls += ' is-wrong';
                if (feedback.optionIndex === optionIndex) cls += ' is-selected';
              }
              return `<button class="${cls}" data-reinforce-option="${optionIndex}" ${feedback ? 'disabled' : ''}><span>${escapeHtml(option.text)}</span>${option.es ? `<small>${escapeHtml(option.es)}</small>` : ''}${feedback && option.correct ? '<b>✓</b>' : ''}</button>`;
            }).join('')}
          </div>
          ${feedback ? `<div class="conversation-feedback ${feedback.correct ? 'ok' : 'warn'}"><strong>${feedback.correct ? 'Listo.' : 'Todavía falta ajustar.'}</strong><span>${escapeHtml(feedback.message || item.feedback || '')}</span></div>` : ''}
          <div class="button-row spacer-top conversation-actions-grid">
            ${feedback ? `<button class="btn btn-primary" id="reinforcement-continue-btn">${index + 1 >= pending.length ? 'Terminar refuerzo' : 'Continuar'}</button>` : ''}
            <button class="btn btn-secondary" id="reinforcement-exit-btn">Salir</button>
          </div>
        </article>
      </section>
    </section>`;
  document.querySelectorAll('[data-reinforce-option]').forEach(btn => btn.addEventListener('click', () => handleConversationReinforcementAnswer(item.queueId, Number(btn.dataset.reinforceOption))));
  document.getElementById('reinforcement-continue-btn')?.addEventListener('click', advanceConversationReinforcement);
  document.getElementById('reinforcement-exit-btn')?.addEventListener('click', () => setView('route', { routeId: state.progress.currentRouteId, scrollTo: item.worldId || undefined }));
}
