function getVisibleLessonPhrases(lesson, intensity = getIntensity()) {
  const basePhrases = getPhraseBlocksForLesson(lesson);
  const seen = new Set();
  const result = [];
  const stopWords = new Set(['i','i’ll','ill','will','would','the','a','an','and','or','to','with','by','for','in','on','at','of','from','it','is','are','be','this','that','my','your','you','me','we','our','as','about','before','after','during','while','into','out','up','down','today','tonight','tomorrow']);
  const significantTokens = (text = '') => normalizeText(text)
    .replace(/\bi ll\b/g, 'ill')
    .split(/\s+/)
    .filter(token => token && token.length > 2 && !stopWords.has(token));
  const nearDuplicate = (a = '', b = '') => {
    const A = new Set(significantTokens(a));
    const B = new Set(significantTokens(b));
    if (A.size < 3 || B.size < 3) return false;
    let shared = 0;
    A.forEach(token => { if (B.has(token)) shared += 1; });
    return shared / Math.min(A.size, B.size) >= 0.86;
  };
  const addPhrase = (block) => {
    if (!block?.en) return;
    const en = normalizeSpeechSentence(block.en);
    const es = normalizeSpeechSentence(block.es || '');
    if (!en || !isUsableSpanishText(es)) return;
    const key = normalizeText(en);
    if (!key || seen.has(key)) return;
    if (result.some(existing => nearDuplicate(existing.en, en))) return;
    seen.add(key);
    result.push({ ...block, en, es, derived: false });
  };
  basePhrases.forEach(addPhrase);

  // v5.0.37: B1/B2 usan frases más largas y a veces el filtro anti-repetición
  // dejaba solo una frase visible, aunque la lección tenía más variantes útiles.
  // Se mantiene la limpieza anti-duplicados, pero se garantiza un mínimo de 2
  // frases visibles para no empobrecer la experiencia en niveles altos.
  if (['ruta_3', 'ruta_4'].includes(lesson?.routeId) && result.length < 2) {
    const existingKeys = new Set(result.map(item => normalizeText(item.en || '')));
    basePhrases.forEach(block => {
      if (result.length >= 2) return;
      if (!block?.en) return;
      const en = normalizeSpeechSentence(block.en);
      const es = normalizeSpeechSentence(block.es || '');
      const key = normalizeText(en);
      if (!en || !isUsableSpanishText(es) || !key || existingKeys.has(key)) return;
      existingKeys.add(key);
      result.push({ ...block, en, es, derived: false, variantSupport: true });
    });
  }

  return result;
}

function normalizeContentForExperience(content) {
  if (!content?.appMeta) return content;
  if (!Array.isArray(content.conversations)) content.conversations = [];

  // IPD v4.3 · Normalización bilingüe de conversaciones.
  // A2/B1/B2 venían con esquema prompt/translation; el motor y la auditoría
  // esperan left/leftEs/es. Se normaliza en memoria para evitar falsos errores
  // y para que funcione igual desde file:/// usando FALLBACK_CONTENT.
  content.conversations = content.conversations.map(conversation => ({
    ...conversation,
    turns: (conversation.turns || []).map((turn, index) => {
      const normalizedOptions = (turn.options || []).map((option) => ({
        ...option,
        text: option.text || option.en || '',
        es: option.es || option.translation || option.textEs || '',
        translation: option.translation || option.es || option.textEs || '',
        correct: Boolean(option.correct)
      }));
      let correctIndex = Number.isInteger(turn.correctIndex) ? turn.correctIndex : normalizedOptions.findIndex(option => option.correct);
      if (correctIndex < 0 && normalizedOptions.length) correctIndex = 0;
      normalizedOptions.forEach((option, optionIndex) => { option.correct = optionIndex === correctIndex; });
      return {
        ...turn,
        id: turn.id || `turn_${index + 1}`,
        left: turn.left || turn.prompt || turn.text || '',
        leftEs: turn.leftEs || turn.translation || turn.promptEs || '',
        options: normalizedOptions,
        correctIndex
      };
    })
  }));

  content.appMeta.version = APP_VERSION;
  const levels = content.appMeta.intensityLevels || {};
  if (levels.ligero) levels.ligero.description = 'Ritmo breve para estudiar pocos minutos al día. Ideal para avanzar sin presión.';
  if (levels.constante) levels.constante.description = 'Ritmo equilibrado para practicar con regularidad y mantener continuidad.';
  if (levels.intensivo) levels.intensivo.description = 'Ritmo más exigente para dedicar más tiempo, repasar más y consolidar mejor.';
  (content.lessons || []).forEach(lesson => {
    const pool = getExercisePoolForLesson(lesson);
    lesson.exerciseSets = {
      ligero: pool.slice(0, Math.min(INTENSITY_EXERCISE_TARGETS.ligero, pool.length)),
      constante: pool.slice(0, Math.min(INTENSITY_EXERCISE_TARGETS.constante, pool.length)),
      intensivo: pool.slice(0, Math.min(INTENSITY_EXERCISE_TARGETS.intensivo, pool.length))
    };
    lesson.practiceProfile = {
      ligero: { phrases: INTENSITY_PHRASE_TARGETS.ligero, exercises: lesson.exerciseSets.ligero.length },
      constante: { phrases: INTENSITY_PHRASE_TARGETS.constante, exercises: lesson.exerciseSets.constante.length },
      intensivo: { phrases: INTENSITY_PHRASE_TARGETS.intensivo, exercises: lesson.exerciseSets.intensivo.length }
    };
  });
  return content;
}

function getReminderScheduler() {
  const scheduler = state.preferences?.reminderScheduler || {};
  return {
    enabled: Boolean(scheduler.enabled),
    times: Array.isArray(scheduler.times) ? scheduler.times.filter(Boolean).slice(0, 3) : ['07:00', '18:00'],
    lastShown: scheduler.lastShown && typeof scheduler.lastShown === 'object' ? scheduler.lastShown : {}
  };
}

function saveReminderScheduler(nextScheduler) {
  state.preferences.reminderScheduler = { ...getReminderScheduler(), ...(nextScheduler || {}) };
  saveState();
}

function notificationsSupported() {
  return typeof window !== 'undefined' && 'Notification' in window;
}

function getNotificationPermissionState() {
  return notificationsSupported() ? Notification.permission : 'unsupported';
}

async function requestReminderPermission() {
  if (!notificationsSupported()) {
    showToast('Este navegador no soporta notificaciones del sistema. Los avisos seguirán dentro de la app.', 'neutral');
    return 'unsupported';
  }
  try {
    const result = await Notification.requestPermission();
    if (result === 'granted') showToast('Avisos del navegador activados.', 'success');
    else if (result === 'denied') showToast('El navegador bloqueó los avisos. Puedes activarlos desde los permisos del sitio.', 'warning');
    else showToast('Solicitud de avisos pendiente o cancelada.', 'neutral');
    return result;
  } catch (error) {
    console.warn('No se pudo solicitar permiso de notificaciones', error);
    showToast('No fue posible activar avisos del navegador en este momento.', 'warning');
    return 'error';
  }
}

function triggerLessonReminderNotice(time, source = 'schedule') {
  const message = source === 'test'
    ? `Prueba de recordatorio: a las ${time} verás un aviso como este.`
    : `Hora de tu clase: ${time}. Puedes retomar tu ruta ahora.`;
  let systemNotice = false;
  if (notificationsSupported() && Notification.permission === 'granted') {
    try {
      new Notification('Tu clase de inglés', {
        body: message,
        tag: `lesson-reminder-${time}`,
        icon: 'assets/icons/app-icon.svg',
        badge: 'assets/icons/app-icon.svg'
      });
      systemNotice = true;
    } catch (error) {
      console.warn('No se pudo lanzar la notificación del sistema', error);
    }
  }
  showToast(message, systemNotice ? 'success' : 'neutral');
}

function formatReminderTimeReadable(time = '07:00') {
  const [rawHour = '07', rawMinute = '00'] = String(time || '07:00').split(':');
  let hour = Number(rawHour || 7);
  const minute = Number(rawMinute || 0);
  const suffix = hour >= 12 ? 'p. m.' : 'a. m.';
  hour = hour % 12 || 12;
  return `${hour}:${String(minute).padStart(2, '0')} ${suffix}`;
}

function getReminderTimeForScope(prefix = 'settings') {
  const scoped = Array.from(document.querySelectorAll(`[data-reminder-scope="${prefix}"]`)).map(input => input.value || '').filter(Boolean);
  if (scoped.length) return scoped[0];
  return getReminderScheduler().times[0] || '07:00';
}

function getNextReminderWindow(time = '07:00', durationMinutes = 60) {
  const now = new Date();
  const [hour = '07', minute = '00'] = String(time || '07:00').split(':');
  const start = new Date(now);
  start.setHours(Number(hour || 7), Number(minute || 0), 0, 0);
  if (start <= now) start.setDate(start.getDate() + 1);
  const end = new Date(start.getTime() + durationMinutes * 60 * 1000);
  return { start, end };
}

function formatGoogleCalendarDate(date) {
  const yyyy = date.getFullYear();
  const mm = String(date.getMonth() + 1).padStart(2, '0');
  const dd = String(date.getDate()).padStart(2, '0');
  const hh = String(date.getHours()).padStart(2, '0');
  const mi = String(date.getMinutes()).padStart(2, '0');
  const ss = String(date.getSeconds()).padStart(2, '0');
  return `${yyyy}${mm}${dd}T${hh}${mi}${ss}`;
}

function buildGoogleCalendarQuickAccessUrl(time = '07:00') {
  const { start, end } = getNextReminderWindow(time, 60);
  const readable = formatReminderTimeReadable(time);
  const title = `Easy English Go: Clase de inglés · ${getActiveUserName()}`;
  const details = [
    'Invitación creada desde Easy English Go.',
    `Clase sugerida para: ${getActiveUserName()}.`,
    `Hora sugerida: ${readable}.`,
    `Intensidad actual: ${getIntensityMeta().label}.`,
    'Objetivo: completar tu clase, retomar tu ruta o reforzar un foco pendiente.'
  ].join('\n');
  const params = new URLSearchParams({
    action: 'TEMPLATE',
    text: title,
    details,
    dates: `${formatGoogleCalendarDate(start)}/${formatGoogleCalendarDate(end)}`
  });
  return `https://calendar.google.com/calendar/render?${params.toString()}`;
}

function openGoogleCalendarQuickAccess(prefix = 'settings') {
  const time = getReminderTimeForScope(prefix);
  const url = buildGoogleCalendarQuickAccessUrl(time);
  const opened = window.open(url, '_blank', 'noopener');
  if (!opened) window.location.href = url;
  showToast(`Se abrió Google Calendar con título, hora y descripción de la clase de las ${formatReminderTimeReadable(time)}.`, 'neutral');
}

function getReminderPermissionLabel() {
  const permission = getNotificationPermissionState();
  if (permission === 'granted') return 'Avisos permitidos';
  if (permission === 'denied') return 'Avisos bloqueados';
  if (permission === 'unsupported') return 'Solo aviso interno';
  return 'Avisos del navegador';
}

function renderReminderControls(prefix = 'drawer') {
  const scheduler = getReminderScheduler();
  return `
    <div class="drawer-toggle-row compact-row">
      <div><strong>Activar recordatorios</strong><p class="muted">Aviso en pantalla y, si lo autorizas, también aviso del navegador.</p></div>
      <label class="switch"><input id="${prefix}-reminder-enabled" type="checkbox" ${scheduler.enabled ? 'checked' : ''}><span class="switch-slider"></span></label>
    </div>
    <div class="chip-row compact-chip-row" style="margin-top:8px;">
      <span class="chip" id="${prefix}-reminder-permission-state">🔔 ${getReminderPermissionLabel()}</span>
    </div>
    <div class="drawer-reminder-grid">
      ${scheduler.times.map((time, index) => `<label class="field drawer-time-field"><span>Horario ${index + 1}</span><input class="input drawer-time-input" type="time" data-reminder-scope="${prefix}" data-reminder-time-index="${index}" value="${escapeHtml(time)}"></label>`).join('')}
    </div>
    <div class="button-row reminder-action-row" style="margin-top:10px;flex-wrap:wrap;">
      <button class="btn btn-secondary btn-small" id="${prefix}-reminder-save">Guardar horarios</button>
      <button class="btn btn-soft btn-small" id="${prefix}-reminder-test">Probar aviso</button>
      <button class="btn btn-soft btn-small" id="${prefix}-reminder-permission">Activar avisos</button>
      <button class="btn btn-soft btn-small" id="${prefix}-reminder-google">Google Calendar</button>
    </div>
    <p class="muted tiny-note" style="margin-top:8px;">Google Calendar se abre como acceso rápido manual. La sincronización automática vendrá después.</p>`;
}

function bindReminderControls(prefix = 'drawer') {
  document.getElementById(`${prefix}-reminder-save`)?.addEventListener('click', () => {
    const times = Array.from(document.querySelectorAll(`[data-reminder-scope="${prefix}"]`)).map(input => input.value || '').filter(Boolean).slice(0, 3);
    saveReminderScheduler({ enabled: document.getElementById(`${prefix}-reminder-enabled`)?.checked, times: times.length ? times : ['07:00'], lastShown: getReminderScheduler().lastShown });
    showToast('Recordatorios guardados.', 'success');
  });
  document.getElementById(`${prefix}-reminder-test`)?.addEventListener('click', () => {
    const firstTime = document.querySelector(`[data-reminder-scope="${prefix}"]`)?.value || getReminderScheduler().times[0] || '07:00';
    triggerLessonReminderNotice(firstTime, 'test');
  });
  document.getElementById(`${prefix}-reminder-permission`)?.addEventListener('click', async () => {
    await requestReminderPermission();
    document.getElementById(`${prefix}-reminder-permission-state`)?.replaceChildren(document.createTextNode(`🔔 ${getReminderPermissionLabel()}`));
  });
  document.getElementById(`${prefix}-reminder-google`)?.addEventListener('click', () => openGoogleCalendarQuickAccess(prefix));
}

function openSettingsSection(section = 'appearance') {
  closeDrawer();
  setView('settings', { section });
}

function getReminderKey(date, time) {
  return `${date}_${time}`;
}

function checkLessonReminders(force = false) {
  const scheduler = getReminderScheduler();
  if (!scheduler.enabled || !scheduler.times.length) return;
  const now = new Date();
  const hh = String(now.getHours()).padStart(2, '0');
  const mm = String(now.getMinutes()).padStart(2, '0');
  const current = `${hh}:${mm}`;
  const dateKey = now.toISOString().slice(0, 10);
  const due = scheduler.times.filter(time => force ? time === current : time === current);
  if (!due.length) return;
  let changed = false;
  due.forEach(time => {
    const key = getReminderKey(dateKey, time);
    if (scheduler.lastShown[key]) return;
    scheduler.lastShown[key] = new Date().toISOString();
    changed = true;
    triggerLessonReminderNotice(time, 'schedule');
  });
  if (changed) saveReminderScheduler(scheduler);
}

let reminderIntervalId = null;

function ensureReminderWatcher() {
  if (reminderIntervalId) clearInterval(reminderIntervalId);
  reminderIntervalId = setInterval(() => checkLessonReminders(false), LESSON_REMINDER_CHECK_MS);
  setTimeout(() => checkLessonReminders(false), 600);
}
function getLessonsForRoute(routeId) { const route = getRouteById(routeId); return route ? route.lessonIds.map(getLessonById).filter(Boolean) : []; }

function getRouteWorlds(routeId) {
  const lessons = getLessonsForRoute(routeId);
  const next = getNextAction();
  const worldMeta = routeId === 'ruta_2' ? A2_WORLD_META : routeId === 'ruta_3' ? B1_WORLD_META : routeId === 'ruta_4' ? B2_WORLD_META : WORLD_META;
  return worldMeta.map((meta, index) => {
    const startIndex = index * WORLD_SIZE;
    const worldLessons = lessons.slice(startIndex, startIndex + WORLD_SIZE);
    if (!worldLessons.length) return null;
    const completedCount = worldLessons.filter(lesson => isLessonCompleted(lesson)).length;
    const viewedCount = worldLessons.filter(lesson => isLessonViewed(lesson.id)).length;
    const baseWorld = {
      ...meta,
      routeId,
      index,
      startIndex,
      lessons: worldLessons,
      lessonIds: worldLessons.map(lesson => lesson.id),
      completedCount,
      viewedCount,
      total: worldLessons.length,
      isCurrent: next.type !== 'done' && (
        worldLessons.some(lesson => lesson.id === next.lessonId) ||
        (next.type === 'conversation' && next.worldId === meta.id)
      )
    };
    const conversationStatus = getConversationStatusForWorld(baseWorld);
    return {
      ...baseWorld,
      conversation: conversationStatus.conversation,
      conversationUnlocked: conversationStatus.unlocked,
      conversationCompleted: conversationStatus.completed,
      conversationPending: conversationStatus.pending,
      isConsolidated: conversationStatus.consolidated,
      consolidatedPercent: Math.round(((completedCount + (conversationStatus.completed || !conversationStatus.conversation ? 1 : 0)) / (worldLessons.length + (conversationStatus.conversation ? 1 : 0))) * 100)
    };
  }).filter(Boolean).map((world, index, worlds) => {
    const previous = worlds[index - 1];
    const unlocked = index === 0 || (previous && previous.completedCount === previous.total);
    let status = 'locked';
    if (world.isConsolidated) status = 'completed';
    else if (world.conversationPending || world.isCurrent) status = 'current';
    else if (unlocked) status = 'unlocked';
    return { ...world, unlocked, status };
  });
}

function getCurrentWorld(routeId = state.progress.currentRouteId) {
  const worlds = getRouteWorlds(routeId);
  return worlds.find(world => world.status === 'current') || worlds.find(world => world.status === 'unlocked') || worlds[0] || null;
}

