function getAssessmentPromptForWorld(world) {
  if (!world || !world.isConsolidated) return null;
  const worldNumber = (world.index || 0) + 1;
  if (worldNumber % ASSESSMENT_WORLD_INTERVAL !== 0) return null;
  const pending = getPendingAssessments().filter(item => item.milestone <= worldNumber);
  if (!pending.length) return null;
  return {
    worldNumber,
    pending,
    latestMilestone: worldNumber,
    text: pending.length === 1
      ? `Ya puedes abrir la evaluación M${pending[0].startWorld}–M${pending[0].endWorld}.`
      : `Tienes ${pending.length} evaluaciones opcionales pendientes.`
  };
}


function getWorldStatusLabel(status) {
  return ({ completed: 'Completado', current: 'Activo', unlocked: 'Disponible', locked: 'Bloqueado' })[status] || 'Disponible';
}
function getWorldStatusHelp(status) {
  return ({ completed: 'Mundo completado', current: 'Mundo activo ahora', unlocked: 'Disponible para abrir', locked: 'Se abrirá al cerrar el mundo anterior' })[status] || 'Disponible';
}
function getWorldStatusLabelCompact(status) {
  return ({ completed: 'Completado', current: 'Activo', unlocked: 'Disponible', locked: 'Bloqueado' })[status] || 'Disponible';
}
function getExerciseIdsForLesson(lesson, intensity = getIntensity()) {
  if (!lesson) return [];
  const target = INTENSITY_EXERCISE_TARGETS[intensity] || INTENSITY_EXERCISE_TARGETS.ligero;
  const configured = Array.isArray(lesson.exerciseSets?.[intensity]) ? lesson.exerciseSets[intensity].slice(0, target) : [];
  if (configured.length >= Math.min(target, 1)) return configured;
  const pool = getExercisePoolForLesson(lesson);
  return pool.slice(0, Math.min(target, pool.length));
}
function isLessonViewed(lessonId) { return state.progress.completedLessons.includes(lessonId); }
function areAllExercisesDone(lesson, targetState = state, intensity = getIntensity()) {
  const ids = getExerciseIdsForLesson(lesson, intensity);
  return ids.length > 0 && ids.every(id => targetState.progress.completedExercises.includes(id));
}
function isLessonCompleted(lesson, targetState = state) { return isLessonViewed(lesson.id) && areAllExercisesDone(lesson, targetState); }
function markLessonViewed(lessonId) {
  const isNew = !state.progress.completedLessons.includes(lessonId);
  if (isNew) {
    state.progress.completedLessons.push(lessonId);
    awardLessonViewedXP(); // M2: +10 XP por lección vista
  }
  state.progress.lastLessonId = lessonId;
  updateProgress();
}
function markExerciseComplete(exerciseId, isCorrect) {
  const exercise = getExerciseById(exerciseId);
  const lesson = exercise ? getLessonById(exercise.lessonId) : null;
  const lessonWasComplete = lesson ? isLessonCompleted(lesson) : false;
  const badgesBefore = new Set(state.progress.badgesEarned || []);
  if (!state.progress.completedExercises.includes(exerciseId)) state.progress.completedExercises.push(exerciseId);
  const previousResult = state.progress.exerciseResults[exerciseId] || {};
  state.progress.exerciseResults[exerciseId] = {
    ...previousResult,
    correct: Boolean(isCorrect),
    attempts: Number(previousResult.attempts || 0) + 1,
    wrongCount: Number(previousResult.wrongCount || 0) + (isCorrect ? 0 : 1),
    updatedAt: new Date().toISOString()
  };
  state.progress.lastExerciseId = exerciseId;
  if (isCorrect) {
    state.progress.correctStreak = (state.progress.correctStreak || 0) + 1;
    state.progress.bestCorrectStreak = Math.max(state.progress.bestCorrectStreak || 0, state.progress.correctStreak || 0);
    playSfx('correct');
  } else {
    state.progress.correctStreak = 0;
    playSfx('wrong');
  }
  updateProgress();
  if (isCorrect && [2, 3, 5, 8, 12].includes(state.progress.correctStreak)) {
    showMicroFeedback('streak', state.progress.correctStreak);
    playSfx('streak');
  }
  if (lesson) {
    const lessonNowComplete = isLessonCompleted(lesson);
    if (!lessonWasComplete && lessonNowComplete) {
      awardExercisesDoneXP(); // M2: +15 XP ejercicios completos (con multiplicador racha)

      // M2: detectar si el mundo quedó completo con esta lección, sin duplicar bonos
      const xpWorld = getRouteWorlds(lesson.routeId).find(world => world.lessonIds.includes(lesson.id));
      if (xpWorld) {
        const xpWorldLessons = Array.isArray(xpWorld.lessons) ? xpWorld.lessons : [];
        const worldNowDone = xpWorldLessons.length > 0 && xpWorldLessons.every(wl => isLessonCompleted(wl));
        const prevWorldDone = (state.progress.xp?.completedWorldIds || []).includes(xpWorld.id);
        if (worldNowDone && !prevWorldDone) {
          if (!state.progress.xp) state.progress.xp = { total: 0, streakDays: 0, lastActivityDate: null, worldsCompleted: 0, lessonsToday: 0, lastLessonDate: null, completedWorldIds: [] };
          state.progress.xp.completedWorldIds = [...(state.progress.xp.completedWorldIds || []), xpWorld.id];
          awardWorldCompleteXP(); // M2: +50 XP bonus mundo completo
        }
      }

      const lessonScore = getLessonScore(lesson);
      const lessonWorld = getRouteWorlds(lesson.routeId).find(world => world.lessonIds.includes(lesson.id));
      showSpotlight('Misión cerrada', lesson.title, {
        icon: lesson.emoji || '🏅',
        tone: 'success',
        meta: [`${lessonScore.correct}/${lessonScore.total} correctas`, lessonWorld ? `M${lessonWorld.index + 1}` : '', getIntensityMeta().label.replace(/^\S+\s*/, '')]
      });
      showMicroFeedback('close');
      playSfx('lesson');
      const newBadges = (state.progress.badgesEarned || []).filter(id => !badgesBefore.has(id));
      if (newBadges.length) {
        const badge = getEarnedBadges(lesson.routeId).find(item => item.id === newBadges[0]);
        window.setTimeout(() => showSpotlight('Nueva insignia', badge?.title || 'Insignia desbloqueada', {
          icon: '🏅',
          tone: 'reward',
          meta: [badge?.note || 'Mundo completado']
        }), 420);
        showMicroFeedback('close');
        playSfx('badge');
      }
    } else {
      if (isCorrect) {
        if (![2, 3, 5, 8, 12].includes(state.progress.correctStreak)) showMicroFeedback('correct');
      } else {
        showMicroFeedback('error');
      }
    }
  }
}
// ══════════════════════════════════════════════════════════════════════════════
// M2 — SISTEMA DE PUNTOS DE EXPERIENCIA (XP)
// Filosofía: acumulativo tranquilo · nada resta · racha es bonus, no penalización
// ══════════════════════════════════════════════════════════════════════════════

const XP_CONFIG = {
  lessonViewed:      10,
  exercisesDone:     15,
  worldComplete:     50,
  examPassed:       200,
  reviewSession:      8,
  gamePlay:          12,
  gameCoins:          0,
  streakDay:          5,
  streakMultiplier: [
    { days:  0, mult: 1.0 },
    { days:  3, mult: 1.1 },
    { days:  7, mult: 1.2 },
    { days: 14, mult: 1.3 },
    { days: 30, mult: 1.5 },
  ]
};

const XP_MEDALS = [
  { id: 'first_step',   emoji: '🌱', label: 'Primer paso',    check: (p) => p.completedLessons.length >= 1 },
  { id: 'streak_7',     emoji: '🔥', label: 'Racha 7 días',   check: (p) => (p.xp?.streakDays || 0) >= 7 },
  { id: 'world_done',   emoji: '🌍', label: 'Mundo completo', check: (p) => (p.xp?.worldsCompleted || 0) >= 1 },
  { id: 'route_a1',     emoji: '🥉', label: 'Ruta A1',        check: (p, s) => !!(s.finalExamResults?.['examen_final_a1']?.passed || s.finalExamResults?.['final_a1_base']?.passed || Object.values(s.finalExamResults || {}).some(r => r.passed && r.unlocked === 'ruta_2')) },
  { id: 'route_a2',     emoji: '🥈', label: 'Ruta A2',        check: (p, s) => !!(Object.values(s.finalExamResults || {}).some(r => r.passed && r.unlocked === 'ruta_3')) },
  { id: 'route_b1',     emoji: '🥇', label: 'Ruta B1',        check: (p, s) => !!(Object.values(s.finalExamResults || {}).some(r => r.passed && r.unlocked === 'ruta_4')) },
  { id: 'route_b2',     emoji: '🏅', label: 'Ruta B2',        check: (p, s) => !!(s.progress?.b2FinalExamPassed) },
  { id: 'intensive_7',  emoji: '⚡', label: 'Intensivo',      check: (p) => (p.xp?.lessonsToday || 0) >= 7 },
  { id: 'streak_30',    emoji: '📅', label: 'Constancia',     check: (p) => (p.xp?.streakDays || 0) >= 30 },
  { id: 'master',       emoji: '🏆', label: 'Maestro',        check: (p, s) => !!(s.progress?.b2FinalExamPassed) },
];

function getStreakMultiplier(streakDays) {
  const tiers = [...XP_CONFIG.streakMultiplier].reverse();
  for (const tier of tiers) {
    if (streakDays >= tier.days) return tier.mult;
  }
  return 1.0;
}

function getStreakDays() {
  const last = state.progress.xp?.lastActivityDate;
  if (!last) return 0;
  const today = new Date().toDateString();
  const lastDate = new Date(last).toDateString();
  if (today === lastDate) return state.progress.xp?.streakDays || 0;
  const diff = Math.floor((new Date(today) - new Date(lastDate)) / 86400000);
  if (diff === 1) return state.progress.xp?.streakDays || 0; // yesterday — still active
  return 0; // broken
}

function addXP(baseAmount, applyMultiplier = true) {
  if (!state.progress.xp) state.progress.xp = { total: 0, streakDays: 0, lastActivityDate: null, worldsCompleted: 0, lessonsToday: 0, lastLessonDate: null };
  const today = new Date().toDateString();
  // Update streak days
  const last = state.progress.xp.lastActivityDate;
  if (!last) {
    state.progress.xp.streakDays = 1;
  } else {
    const lastDate = new Date(last).toDateString();
    if (today !== lastDate) {
      const diff = Math.floor((new Date(today) - new Date(lastDate)) / 86400000);
      state.progress.xp.streakDays = diff === 1
        ? (state.progress.xp.streakDays || 0) + 1
        : 1;
      // Streak day bonus
      state.progress.xp.total = (state.progress.xp.total || 0) + XP_CONFIG.streakDay;
    }
  }
  state.progress.xp.lastActivityDate = new Date().toISOString();
  // Track lessons today for ⚡ medal
  if (state.progress.xp.lastLessonDate !== today) {
    state.progress.xp.lessonsToday = 0;
    state.progress.xp.lastLessonDate = today;
  }
  // Apply multiplier only to lesson/exercise XP
  const mult = applyMultiplier ? getStreakMultiplier(state.progress.xp.streakDays || 0) : 1.0;
  const earned = Math.round(baseAmount * mult);
  state.progress.xp.total = (state.progress.xp.total || 0) + earned;
  return earned;
}

function awardLessonViewedXP() {
  return addXP(XP_CONFIG.lessonViewed, true);
}

function awardExercisesDoneXP() {
  if (!state.progress.xp) state.progress.xp = { total: 0, streakDays: 0, lastActivityDate: null, worldsCompleted: 0, lessonsToday: 0, lastLessonDate: null };
  state.progress.xp.lessonsToday = (state.progress.xp.lessonsToday || 0) + 1;
  return addXP(XP_CONFIG.exercisesDone, true);
}

function awardWorldCompleteXP() {
  if (!state.progress.xp) state.progress.xp = { total: 0, streakDays: 0, lastActivityDate: null, worldsCompleted: 0, lessonsToday: 0, lastLessonDate: null };
  state.progress.xp.worldsCompleted = (state.progress.xp.worldsCompleted || 0) + 1;
  return addXP(XP_CONFIG.worldComplete, false); // bonus: sin multiplicador
}

function awardExamPassedXP() {
  return addXP(XP_CONFIG.examPassed, false); // examen: sin multiplicador
}

function awardReviewXP() {
  if (!state.progress.xp) state.progress.xp = { total: 0, streakDays: 0, lastActivityDate: null, worldsCompleted: 0, lessonsToday: 0, lastLessonDate: null };
  const now = Date.now();
  const last = Number(state.progress.xp.lastReviewAwardAt || 0);
  // Evita que el usuario sume XP infinitos solo entrando y saliendo de Repaso.
  if (last && now - last < 10 * 60 * 1000) return 0;
  state.progress.xp.lastReviewAwardAt = now;
  return addXP(XP_CONFIG.reviewSession, true);
}

function getTotalXP() {
  return state.progress.xp?.total || 0;
}

function getXPMedals() {
  return XP_MEDALS.filter(m => m.check(state.progress, state));
}

function getXPStreakDays() {
  return state.progress.xp?.streakDays || 0;
}

function syncXPMedals() {
  const earned = getXPMedals().map(m => m.id);
  const prev = state.progress.xp?.medals || [];
  const newOnes = earned.filter(id => !prev.includes(id));
  if (!state.progress.xp) state.progress.xp = { total: 0, streakDays: 0, lastActivityDate: null, worldsCompleted: 0, lessonsToday: 0, lastLessonDate: null };
  state.progress.xp.medals = earned;
  return newOnes; // returns newly earned medal ids
}

// ══════════════════════════════════════════════════════════════════════════════
// /M2
// ══════════════════════════════════════════════════════════════════════════════

function updateProgress() { state.progress.percent = calculateProgress(CONTENT, state); syncEarnedBadges(); syncXPMedals(); saveState(); }
function calculateProgress(content, targetState) {
  const lessons = content.lessons || [];
  if (!lessons.length) return 0;
  const intensity = targetState.profile?.intensity || 'ligero';
  let accumulated = 0;
  lessons.forEach(lesson => {
    const ids = getExerciseIdsForLesson(lesson, intensity);
    const viewed = targetState.progress.completedLessons.includes(lesson.id);
    const allExercisesDone = ids.length ? ids.every(id => targetState.progress.completedExercises.includes(id)) : false;
    if (viewed) accumulated += 0.4;
    if (allExercisesDone) accumulated += 0.6;
  });
  const route = content.routes?.find(item => item.id === targetState.progress?.currentRouteId) || content.routes?.[0];
  const routeLessonIds = route?.lessonIds || lessons.map(lesson => lesson.id);
  const totalWorlds = Math.ceil(routeLessonIds.length / WORLD_SIZE);
  let conversationUnits = 0;
  for (let i = 0; i < totalWorlds; i += 1) {
    const conversation = (content.conversations || []).find(item => item.worldId === `world_${i + 1}`);
    if (!conversation) continue;
    const completed = Boolean(targetState.progress?.conversationResults?.[conversation.id]?.completed);
    if (completed) conversationUnits += 1;
  }
  return Math.round(((accumulated + conversationUnits) / (lessons.length + totalWorlds)) * 100);
}

function getCurrentLesson() {
  const lessons = getLessonsForRoute(state.progress.currentRouteId);
  for (const lesson of lessons) {
    if (!isLessonViewed(lesson.id) || !areAllExercisesDone(lesson)) return lesson;
  }
  return lessons[lessons.length - 1] || null;
}

function getNextAction() {
  const lessons = getLessonsForRoute(state.progress.currentRouteId);
  const totalWorlds = Math.ceil(lessons.length / WORLD_SIZE);
  for (let worldIndex = 0; worldIndex < totalWorlds; worldIndex += 1) {
    const worldLessons = lessons.slice(worldIndex * WORLD_SIZE, (worldIndex + 1) * WORLD_SIZE);
    for (const lesson of worldLessons) {
      if (!isLessonViewed(lesson.id)) return { type: 'lesson', lessonId: lesson.id };
      const pending = getExerciseIdsForLesson(lesson).find(id => !state.progress.completedExercises.includes(id));
      if (pending) return { type: 'exercise', lessonId: lesson.id, exerciseId: pending };
    }
    const worldId = `world_${worldIndex + 1}`;
    const conversation = getConversationByWorldId(worldId);
    if (conversation && !isConversationCompleted(conversation.id)) {
      return { type: 'conversation', worldId, conversationId: conversation.id, lessonId: worldLessons[worldLessons.length - 1]?.id || null };
    }
  }
  return { type: 'done' };
}

function goToNextLessonAfterWorld(world) {
  const lessons = getLessonsForRoute(state.progress.currentRouteId);
  const start = Number.isFinite(world?.startIndex) ? world.startIndex + WORLD_SIZE : 0;
  const nextLesson = lessons.slice(start).find(lesson => !isLessonViewed(lesson.id) || !areAllExercisesDone(lesson));
  if (nextLesson) {
    if (!isLessonViewed(nextLesson.id)) return setView('lesson', { lessonId: nextLesson.id });
    const pending = getExerciseIdsForLesson(nextLesson).find(id => !state.progress.completedExercises.includes(id));
    if (pending) return setView('exercise', { lessonId: nextLesson.id, exerciseIndex: Math.max(0, getExerciseIdsForLesson(nextLesson).indexOf(pending)) });
    return setView('lesson', { lessonId: nextLesson.id });
  }
  return goToRoadHome();
}

function getNextWorldFirstLesson(world) {
  const lessons = getLessonsForRoute(state.progress.currentRouteId);
  const start = Number.isFinite(world?.startIndex) ? world.startIndex + WORLD_SIZE : 0;
  return lessons[start] || null;
}
function goToNextWorldFirstLesson(world) {
  const nextLesson = getNextWorldFirstLesson(world);
  if (nextLesson) return setView('lesson', { lessonId: nextLesson.id });
  return goToNextLessonAfterWorld(world);
}
function goToRouteMain(worldId = null) {
  return goToVisibleRoutePoint(worldId);
}

function goToVisibleRoutePoint(worldId = null) {
  // Botón "Volver a la ruta": debe volver al mapa, no saltar automáticamente
  // al siguiente ejercicio/lección. El foco queda en el mundo actual o visible.
  const targetWorldId = worldId || getCurrentWorld()?.id || getNextAction()?.worldId || undefined;
  return setView('route', { routeId: state.progress.currentRouteId, scrollTo: targetWorldId, showAllSections: true });
}
function getNavigationContextForWorld(world) {
  const next = getNextAction();
  const nextWorldLesson = getNextWorldFirstLesson(world);
  const currentLesson = getCurrentLesson();
  let resumeLabel = 'Continuar donde iba';
  if (next.type === 'lesson') {
    const lesson = getLessonById(next.lessonId);
    resumeLabel = lesson ? `Continuar: ${lesson.title}` : 'Continuar lección';
  } else if (next.type === 'exercise') {
    const lesson = getLessonById(next.lessonId);
    resumeLabel = lesson ? `Retomar práctica: ${lesson.title}` : 'Retomar práctica';
  } else if (next.type === 'conversation') {
    const w = getBasicWorldById(state.progress.currentRouteId, next.worldId);
    resumeLabel = w ? `Ir a conversación pendiente: ${w.title}` : 'Ir a conversación pendiente';
  }
  return { next, nextWorldLesson, currentLesson, resumeLabel };
}

function getLessonScore(lesson) {
  const ids = getExerciseIdsForLesson(lesson);
  const total = ids.length;
  const correct = ids.filter(id => state.progress.exerciseResults[id]?.correct).length;
  const completed = ids.filter(id => state.progress.completedExercises.includes(id)).length;
  const percent = total ? Math.round((correct / total) * 100) : 0;
  return { total, correct, completed, percent };
}

function scoreBadge(percent) {
  if (percent === 100) return '🔥 Dominio completo';
  if (percent >= 75) return '💪 Muy buen cierre';
  if (percent >= 50) return '🌱 Base en crecimiento';
  return '🔁 Conviene repasar';
}

function goToNextAction() {
  const next = getNextAction();
  if (next.type === 'lesson') return setView('lesson', { lessonId: next.lessonId });
  if (next.type === 'conversation') return setView('conversation', { conversationId: next.conversationId, worldId: next.worldId, lessonId: next.lessonId, turnIndex: 0, responses: [] });
  if (next.type === 'exercise') {
    const lesson = getLessonById(next.lessonId);
    const ids = getExerciseIdsForLesson(lesson);
    const idx = ids.indexOf(next.exerciseId);
    return setView('exercise', { lessonId: next.lessonId, exerciseIndex: Math.max(0, idx) });
  }
  goToRoadHome();
}

function isLessonUnlocked(lessonIndex, lessons) { if (lessonIndex === 0) return true; return isLessonCompleted(lessons[lessonIndex - 1]); }
function getLessonState(lesson, lessonIndex, lessons) {
  if (isLessonCompleted(lesson)) return 'completed';
  const next = getNextAction();
  if ((next.type === 'lesson' || next.type === 'exercise') && next.lessonId === lesson.id) return 'current';
  if (isLessonUnlocked(lessonIndex, lessons)) return 'pending';
  return 'locked';
}
function getLessonStatusLabel(stateName) { return ({ completed:'Completada', current:'Tu paso actual', locked:'Se activa luego', pending:'Pendiente' })[stateName] || 'Pendiente'; }
function getContinueLabel() { const next = getNextAction(); return next.type === 'done' ? 'Revisar ruta' : next.type === 'conversation' ? 'Iniciar conversación' : 'Seguir'; }
function resumeJourney() { return getNextAction().type === 'done' ? goToRoadHome() : goToNextAction(); }

function getReturnTargetFallback() {
  if (ui.view && !['dictionary','library','knowledge'].includes(ui.view)) {
    return { view: ui.view, payload: { ...(ui.payload || {}) } };
  }
  return { view: 'route', payload: { showAllSections: true, showAdvanceLogic: true } };
}

function getNavSnapshot() {
  return { view: ui.view, payload: { ...(ui.payload || {}) } };
}
function applyNavSnapshot(snapshot) {
  if (!snapshot?.view) return;
  navHistory.suppress = true;
  setView(snapshot.view, snapshot.payload || {});
  navHistory.suppress = false;
}
function goNavBack() {
  const previous = navHistory.back.pop();
  if (!previous) return showToast('No hay pantalla anterior.', 'neutral');
  navHistory.forward.push(getNavSnapshot());
  applyNavSnapshot(previous);
}
function goNavForward() {
  const next = navHistory.forward.pop();
  if (!next) return showToast('No hay pantalla siguiente.', 'neutral');
  navHistory.back.push(getNavSnapshot());
  applyNavSnapshot(next);
}
function setView(viewName, payload = {}) {
  if (activeContextTour) clearContextTour();
  // ── M2: XP de repaso al salir de la vista de repaso ──────────────────────
  if (ui.view === 'review' && viewName !== 'review') {
    awardReviewXP(); // +8 XP por sesión de repaso completada
    updateProgress();
  }
  // ──────────────────────────────────────────────────────────────────────────
  if (!navHistory.suppress && ui.view && ui.view !== viewName) {
    navHistory.back.push(getNavSnapshot());
    if (navHistory.back.length > navHistory.max) navHistory.back.shift();
    navHistory.forward = [];
  }
  if ((viewName === 'dictionary' || viewName === 'library' || viewName === 'knowledge') && !payload.returnTo) {
    payload = { ...payload, returnTo: getReturnTargetFallback() };
  }
  if ((viewName === 'dictionary' || viewName === 'knowledge') && payload.q && typeof dictionaryState !== 'undefined') {
    dictionaryState.query = String(payload.q || '').trim();
    dictionaryState.draftQuery = dictionaryState.query;
    dictionaryState.selectedWord = null;
  }
  ui.view = viewName;
  ui.payload = payload;
  state.progress.lastSeenView = viewName;
  if (payload.lessonId) state.progress.lastLessonId = payload.lessonId;
  if (payload.exerciseId) state.progress.lastExerciseId = payload.exerciseId;
  saveState();
  renderApp();
}


/* v4.20.10 · Delegación defensiva para botones de ruta/lección */
if (!window.__ipdRouteDelegation4204) {
  window.__ipdRouteDelegation4204 = true;
  document.addEventListener('click', (event) => {
    const routeMainBtn = event.target?.closest?.('[data-route-main-button]');
    if (routeMainBtn) {
      event.preventDefault();
      event.stopPropagation();
      goToRouteMain(routeMainBtn.dataset?.scrollTo || null);
      return;
    }
    const lessonBtn = event.target?.closest?.('.open-lesson-btn');
    if (lessonBtn && lessonBtn.dataset?.lessonId && !lessonBtn.disabled) {
      event.preventDefault();
      event.stopPropagation();
      openLessonFromStation(lessonBtn);
      return;
    }
    const backRoadBtn = event.target?.closest?.('#bus-back-to-road');
    if (backRoadBtn) {
      event.preventDefault();
      event.stopPropagation();
      setView('route', { routeId: state.progress.currentRouteId || 'ruta_1' });
    }
  }, true);
}

function goBackFromSupport(defaultPayload = {}) {
  const target = ui.payload?.returnTo;
  if (target && target.view && target.view !== ui.view) {
    setView(target.view, target.payload || {});
    return;
  }
  setView('route', { showAllSections: true, showAdvanceLogic: true, ...defaultPayload });
}

function compactToastMessage(message = '') {
  const text = String(message || '').trim();
  if (!text) return '';
  if (text.length <= 64) return text;
  return text
    .replace('Puedes abrirlo de nuevo desde el menú.', '')
    .replace('Puedes empezar de nuevo cuando quieras.', '')
    .slice(0, 61).trim() + '…';
}
function showToast(message, kind = 'neutral') {
  const id = `${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  ui.toasts = [{ id, message: compactToastMessage(message), kind }];
  renderToasts();
  window.clearTimeout(toastTimer);
  toastTimer = setTimeout(() => { ui.toasts = ui.toasts.filter(t => t.id !== id); renderToasts(); }, 1800);
}
function renderToasts() { $toastLayer.innerHTML = ui.toasts.slice(-1).map(t => `<div class="toast toast-compact ${t.kind ? `toast-${t.kind}` : ''}">${escapeHtml(t.message)}</div>`).join(''); }

function showMicroFeedback(type, value) {
  const existing = document.querySelector('.micro-feedback');
  if (existing) existing.remove();
  const el = document.createElement('div');
  el.className = 'micro-feedback';
  el.setAttribute('aria-hidden', 'true');
  if (type === 'correct') {
    el.textContent = '👌🏻';
    el.classList.add('ok');
    el.style.animationName = 'microWiggleFade';
    el.style.animationDuration = '1s';
  } else if (type === 'exact') {
    el.textContent = '👏🏻';
    el.classList.add('exact');
    el.style.animationDuration = '1.15s';
  } else if (type === 'close') {
    el.textContent = '👊🏻';
    el.classList.add('close-hit');
    el.style.animationDuration = '1.25s';
  } else if (type === 'streak') {
    el.textContent = `🔥x${value || 1}`;
    el.classList.add('streak');
    el.style.animationDuration = '1.5s';
  } else if (type === 'error') {
    el.textContent = '❌↻';
    el.classList.add('error');
    el.style.animationName = 'microSpinFade';
    el.style.animationDuration = '0.9s';
  } else {
    el.textContent = '👌🏻';
    el.classList.add('ok');
  }
  document.body.appendChild(el);
  const duration = type === 'streak' ? 1500 : type === 'error' ? 900 : type === 'close' ? 1250 : 1200;
  window.setTimeout(() => el.remove(), duration);
}

function openModal(modal) { ui.modal = modal; renderModal(); }
function closeModal() { if (typeof stopAnimatedDialoguePlayback === 'function') stopAnimatedDialoguePlayback(); if (typeof stopRealListeningPlayback === 'function') stopRealListeningPlayback(); ui.modal = null; renderModal(); }
function renderModal() {
  if (!ui.modal) { $modalLayer.innerHTML = ''; return; }
  const m = ui.modal;
  /* Soporte para customRender (e.g. modal de timer) */
  if (typeof m.customRender === 'function') {
    $modalLayer.innerHTML = `<div class="modal-overlay" role="dialog" aria-modal="true">${m.customRender()}</div>`;
    $modalLayer.querySelector('.modal-overlay').addEventListener('click', e => { if (e.target.classList.contains('modal-overlay')) closeModal(); });
    if (typeof m.afterRender === 'function') m.afterRender();
    return;
  }
  $modalLayer.innerHTML = `
    <div class="modal-overlay" role="dialog" aria-modal="true" aria-labelledby="modal-title">
      <div class="modal">
        <h2 id="modal-title">${escapeHtml(m.title||'')}</h2>
        <p class="muted">${escapeHtml(m.message||'')}</p>
        <div class="button-row spacer-top">
          <button class="btn btn-danger" id="modal-confirm">${escapeHtml(m.confirmText || 'Confirmar')}</button>
          <button class="btn btn-secondary" id="modal-cancel">${escapeHtml(m.cancelText || 'Cancelar')}</button>
        </div>
      </div>
    </div>`;
  document.getElementById('modal-confirm').onclick = m.onConfirm || closeModal;
  document.getElementById('modal-cancel').onclick = m.onCancel || closeModal;
  $modalLayer.querySelector('.modal-overlay').addEventListener('click', e => { if (e.target.classList.contains('modal-overlay')) closeModal(); });
}

function showSpotlight(title, subtitle = '', options = {}) {
  if (!$spotlightLayer) return;
  window.clearTimeout(spotlightTimer);
  const tone = options.tone || 'success';
  const icon = options.icon || '✨';
  const meta = Array.isArray(options.meta) ? options.meta.filter(Boolean) : [];
  $spotlightLayer.innerHTML = `
    <div class="spotlight-banner spotlight-${tone}">
      <div class="spotlight-icon" aria-hidden="true">${icon}</div>
      <div class="spotlight-copy">
        <strong>${escapeHtml(title)}</strong>
        ${subtitle ? `<span>${escapeHtml(subtitle)}</span>` : ''}
        ${meta.length ? `<div class="spotlight-meta-row">${meta.map(item => `<span class="spotlight-pill">${escapeHtml(String(item))}</span>`).join('')}</div>` : ''}
      </div>
    </div>`;
  const banner = $spotlightLayer.firstElementChild;
  window.requestAnimationFrame(() => banner?.classList.add('on'));
  spotlightTimer = window.setTimeout(() => {
    banner?.classList.remove('on');
    window.setTimeout(() => { if ($spotlightLayer.contains(banner)) $spotlightLayer.innerHTML = ''; }, 220);
  }, Number(options.duration || 2500));
}

function resetState() {
  const previousProfile = structuredCloneSafe(state.profile || {});
  const previousPreferences = structuredCloneSafe(state.preferences || {});
  const previousRouteId = state.progress?.currentRouteId || 'ruta_1';
  const activeId = storageEnvelope?.activeUserId;
  const fresh = createFreshState();
  fresh.profile = {
    ...fresh.profile,
    ...previousProfile,
    onboarded: true,
    startedAt: previousProfile.startedAt || new Date().toISOString()
  };
  fresh.preferences = { ...fresh.preferences, ...previousPreferences };
  fresh.progress.currentRouteId = previousRouteId;
  fresh.progress.lastSeenView = 'route';
  state = migrateState(fresh);
  updateProgress();
  if (!storageEnvelope) storageEnvelope = loadStorageEnvelope();
  if (activeId && storageEnvelope.users?.[activeId]) {
    storageEnvelope.activeUserId = activeId;
    storageEnvelope.users[activeId].state = structuredCloneSafe(state);
    storageEnvelope.users[activeId].lastActiveAt = new Date().toISOString();
  }
  ui.view = 'route';
  ui.payload = buildRouteHomePayload(false);
  saveState();
  applyPreferences();
  closeModal();
  showToast('Progreso reiniciado. El usuario activo se conserva y la app sigue funcional.', 'success');
  renderApp();
}

function resetAppToZero() {
  const replacement = createUserRecord('');
  storageEnvelope = {
    version: APP_VERSION,
    activeUserId: replacement.id,
    users: { [replacement.id]: replacement }
  };
  state = migrateState(replacement.state);
  ui.view = 'onboarding';
  ui.payload = { fromLogout: true, forceUserSelector: true, emptyDevice: true };
  try {
    localStorage.removeItem(STORAGE_KEY);
    localStorage.setItem(STORAGE_ENVELOPE_KEY, JSON.stringify(storageEnvelope));
  } catch (error) {
    console.error('No se pudo reiniciar almacenamiento local.', error);
  }
  applyPreferences();
  closeModal();
  showToast('App reiniciada en cero. Crea o carga un usuario para empezar.', 'neutral');
  renderApp();
}


