/* ── Timer de sesión ─────────────────────────────────────────── */
const sessionTimer = { active: false, totalSecs: 0, remainSecs: 0, interval: null };

function openSessionModal() {
  openModal({
    customRender: () => `
      <div class="session-modal-card">
        <div style="font-size:2rem">⏱</div>
        <h2 style="margin:0;font-size:1.15rem">¿Cuánto tiempo tienes hoy?</h2>
        <p class="muted" style="margin:0;font-size:.9rem">Te avisamos cuando se acerque el final para que puedas terminar tranquilamente.</p>
        <div class="session-time-grid">
          <button class="session-time-btn" data-mins="5">5 min</button>
          <button class="session-time-btn" data-mins="10">10 min</button>
          <button class="session-time-btn" data-mins="15">15 min</button>
          <button class="session-time-btn" data-mins="20">20 min</button>
        </div>
        <button class="btn btn-secondary" id="session-skip-btn" style="width:100%;margin-top:4px;">Sin límite de tiempo</button>
      </div>`,
    afterRender: () => {
      document.querySelectorAll('.session-time-btn').forEach(btn => {
        btn.addEventListener('click', () => {
          closeModal();
          startSessionTimer(Number(btn.dataset.mins));
        });
      });
      document.getElementById('session-skip-btn')?.addEventListener('click', closeModal);
    }
  });
}

function startSessionTimer(minutes) {
  clearInterval(sessionTimer.interval);
  sessionTimer.active    = true;
  sessionTimer.totalSecs = minutes * 60;
  sessionTimer.remainSecs = minutes * 60;
  renderTimerBadge();
  sessionTimer.interval = setInterval(() => {
    sessionTimer.remainSecs--;
    renderTimerBadge();
    if (sessionTimer.remainSecs <= 0) {
      clearInterval(sessionTimer.interval);
      sessionTimer.active = false;
      const el = document.getElementById('session-timer');
      if (el) { el.textContent = '✅ ¡Sesión completa!'; el.className = 'timer-expired'; }
      showToast('⏱ ¡Sesión completada! Buen trabajo hoy.', 'success');
    } else if (sessionTimer.remainSecs === 60) {
      showToast('⏱ Queda 1 minuto. Ve terminando.', 'neutral');
    }
  }, 1000);
  showToast(`⏱ Sesión iniciada: ${minutes} minutos.`, 'success');
}

function renderTimerBadge() {
  if (!sessionTimer.active) { document.getElementById('session-timer')?.remove(); return; }
  let el = document.getElementById('session-timer');
  if (!el) {
    el = document.createElement('div');
    el.id = 'session-timer';
    el.title = 'Toca para ver opciones';
    el.onclick = () => {
      if (!sessionTimer.active) return;
      if (el.dataset.justDragged === '1') { el.dataset.justDragged = '0'; return; }
      openModal({
        title: 'Tiempo de sesión',
        message: `Te quedan ${formatTime(sessionTimer.remainSecs)} de estudio. ¿Quieres continuar o detener el contador?`,
        confirmText: 'Seguir estudiando',
        cancelText: 'Detener contador',
        onConfirm: closeModal,
        onCancel: () => { clearInterval(sessionTimer.interval); sessionTimer.active = false; el?.remove(); closeModal(); }
      });
    };
    const shell = document.getElementById('app-shell');
    if (shell) shell.appendChild(el);
    let dragState = null;
    const resetTransform = () => { if (!dragState?.moved) return; el.style.left = `${dragState.x}px`; el.style.top = `${dragState.y}px`; el.style.right = 'auto'; };
    const onMove = evt => { if (!dragState) return; const p = evt.touches ? evt.touches[0] : evt; dragState.x = Math.max(8, Math.min(window.innerWidth - el.offsetWidth - 8, p.clientX - dragState.offsetX)); dragState.y = Math.max(68, Math.min(window.innerHeight - el.offsetHeight - 12, p.clientY - dragState.offsetY)); dragState.moved = true; resetTransform(); };
    const endDrag = () => { if (!dragState) return; if (dragState.moved) el.dataset.justDragged = '1'; document.removeEventListener('mousemove', onMove); document.removeEventListener('mouseup', endDrag); document.removeEventListener('touchmove', onMove); document.removeEventListener('touchend', endDrag); setTimeout(() => { dragState = null; }, 0); };
    const startDrag = evt => { const p = evt.touches ? evt.touches[0] : evt; dragState = { offsetX: p.clientX - el.getBoundingClientRect().left, offsetY: p.clientY - el.getBoundingClientRect().top, x: el.getBoundingClientRect().left, y: el.getBoundingClientRect().top, moved: false }; document.addEventListener('mousemove', onMove, { passive: false }); document.addEventListener('mouseup', endDrag); document.addEventListener('touchmove', onMove, { passive: false }); document.addEventListener('touchend', endDrag); };
    el.addEventListener('mousedown', startDrag);
    el.addEventListener('touchstart', startDrag, { passive: true });
  }
  const r = sessionTimer.remainSecs;
  el.textContent = `⏱ ${formatTime(r)}`;
  el.className = r < 60 ? 'timer-expired' : r < 120 ? 'timer-warning' : '';
}

function formatTime(secs) {
  const m = Math.floor(secs / 60);
  const s = secs % 60;
  return `${m}:${String(s).padStart(2,'0')}`;
}

function showTimerBadge() { renderTimerBadge(); }
/* ── /Timer ──────────────────────────────────────────────────── */


