const INFO_SHEETS = {
  progress: {
    title: 'Avance total',
    body: 'Mide cuánto has recorrido dentro de tu ruta actual. Aumenta al cerrar microlecciones, mundos y evaluaciones.'
  },
  streak: {
    title: 'Racha',
    body: 'Cuenta tu continuidad reciente. No certifica nivel, pero sí te ayuda a sostener hábito y memoria activa.'
  },
  badges: {
    title: 'Insignias',
    body: 'Son logros internos por constancia, cierre de mundos, evaluaciones y dominio. Funcionan como memoria visual de tu progreso.'
  },
  a1base: {
    title: 'A1-base',
    body: 'Es un indicador interno de preparación. No equivale a certificación, pero te muestra qué tan cerca estás de la consolidación final A1-base.'
  },
  savedPoint: {
    title: 'Punto guardado',
    body: 'Guarda aquí tu lugar para volver luego. Puedes cargarlo cuando quieras y retomar sin perder el hilo de la lección o del ejercicio.'
  },
  pronunciation: {
    title: 'Práctica de pronunciación',
    body: 'Escucha una frase, repítela con el micrófono y revisa la transcripción. El navegador intenta reconocer en inglés; si no lo soporta, la app mantiene la práctica como escucha y repetición manual.'
  }
};

function openInfoModal(infoId) {
  const info = INFO_SHEETS[infoId];
  if (!info) return;
  openModal({
    customRender: () => `
      <div class="modal-overlay on" role="dialog" aria-modal="true" aria-labelledby="info-sheet-title">
        <div class="modal info-sheet-modal">
          <div class="modal-h">
            <strong id="info-sheet-title">${escapeHtml(info.title)}</strong>
            <button class="btn btn-soft btn-small" id="info-sheet-close">Cerrar</button>
          </div>
          <div class="modal-b">
            <p class="muted">${escapeHtml(info.body)}</p>
          </div>
          <div class="modal-f">
            <button class="btn btn-primary" id="info-sheet-ok">Entendido</button>
          </div>
        </div>
      </div>`,
    afterRender: () => {
      document.getElementById('info-sheet-close')?.addEventListener('click', closeModal);
      document.getElementById('info-sheet-ok')?.addEventListener('click', closeModal);
    }
  });
}

