const MANUAL_HTML_DOC = "<!DOCTYPE html>\n<html lang=\"es\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Manual de usuario · Easy English Go</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Nunito:wght@400;500;600;700;800;900&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bg:#f4f6fb;--surface:#fff;--surface-2:#eef2ff;--text:#20243f;--muted:#64708c;--line:#dce3f2;\n  --primary:#5b5bd6;--accent:#18b58d;--danger:#d95668;--warning:#d79e1d;--shadow:0 18px 38px rgba(34,45,93,.12);\n  --radius:22px;--font:\"Nunito\",ui-rounded,\"SF Pro Rounded\",Inter,system-ui,-apple-system,\"Segoe UI\",sans-serif;\n}\nbody.dark{--bg:#10131d;--surface:#171d2b;--surface-2:#222a3d;--text:#eef2ff;--muted:#a8b0c9;--line:#2f3950;--primary:#8a89ff;--accent:#22c89a;--shadow:0 18px 42px rgba(0,0,0,.3)}\n*{box-sizing:border-box} html{scroll-behavior:smooth} body{margin:0;font-family:var(--font);color:var(--text);background:radial-gradient(circle at top right,rgba(91,91,214,.12),transparent 25%),radial-gradient(circle at bottom left,rgba(24,181,141,.12),transparent 22%),var(--bg);line-height:1.58}\n.manual-shell{max-width:1180px;margin:0 auto;padding:0 18px 110px}.skip-link{position:absolute;left:-999px;top:0;background:var(--primary);color:#fff;padding:10px 16px;border-radius:0 0 14px 0;z-index:100}.skip-link:focus{left:0}\n.m-header{position:sticky;top:0;z-index:60;display:flex;align-items:center;gap:12px;padding:14px 20px;margin:0 -18px;background:rgba(255,255,255,.86);backdrop-filter:blur(14px);border-bottom:1px solid var(--line)}body.dark .m-header{background:rgba(18,22,34,.9)}\n.logo-dot{width:42px;height:42px;border-radius:14px;display:grid;place-items:center;background:linear-gradient(135deg,var(--primary),var(--accent));color:#fff;font-weight:1000;box-shadow:var(--shadow)}.ht{display:flex;flex-direction:column;line-height:1.12}.ht strong{font-weight:1000}.ht span{font-size:.78rem;color:var(--muted);font-weight:800}.spacer{flex:1}\n.theme-toggle{display:flex;gap:6px;background:var(--surface);border:1px solid var(--line);border-radius:999px;padding:4px}.theme-toggle button{border:0;background:transparent;width:34px;height:34px;border-radius:999px;cursor:pointer;font-size:1rem;color:var(--muted)}.theme-toggle button.active{background:var(--primary);color:#fff}\n.hero{margin-top:26px;display:grid;grid-template-columns:1.25fr .75fr;gap:20px;align-items:center;padding:30px;border:1px solid var(--line);border-radius:28px;background:linear-gradient(135deg,rgba(91,91,214,.10),rgba(24,181,141,.08));box-shadow:var(--shadow)}.hero h1{margin:.2em 0;font-size:clamp(2rem,5vw,3.4rem);line-height:.95;font-weight:1000;letter-spacing:-.04em}.hero p{color:var(--muted);font-weight:750;max-width:58ch}.kicker{display:inline-flex;padding:5px 11px;border-radius:999px;background:var(--surface);border:1px solid var(--line);font-size:.72rem;text-transform:uppercase;letter-spacing:1.1px;color:var(--primary);font-weight:1000}.ver{display:inline-flex;gap:8px;align-items:center;color:var(--accent);font-weight:950;font-size:.82rem}.ver .dot{width:8px;height:8px;border-radius:50%;background:var(--accent)}.hero-icon{font-size:5rem;text-align:center;filter:drop-shadow(0 18px 24px rgba(34,45,93,.18))}\n.layout{display:grid;grid-template-columns:250px 1fr;gap:34px;margin-top:34px;align-items:start}.toc{position:sticky;top:80px}.toc nav{background:var(--surface);border:1px solid var(--line);border-radius:22px;padding:14px;box-shadow:var(--shadow)}.toc h4{margin:6px 8px 10px;font-size:.72rem;color:var(--muted);letter-spacing:1.2px;text-transform:uppercase}.toc button{display:block;width:100%;border:0;background:transparent;text-align:left;padding:8px 10px;border-radius:12px;color:var(--text);font:inherit;font-size:.86rem;font-weight:900;cursor:pointer}.toc button:hover{background:var(--surface-2)}.toc button.active{background:var(--primary);color:#fff}\nsection.block{scroll-margin-top:92px;margin-bottom:46px}.block>h2{display:flex;align-items:center;gap:12px;margin:0 0 4px;font-size:1.45rem;font-weight:1000}.num{display:inline-grid;place-items:center;width:34px;height:34px;border-radius:12px;background:var(--primary);color:#fff;font-size:.95rem}.lead{margin:0 0 18px;color:var(--muted);font-weight:750}.card{background:var(--surface);border:1px solid var(--line);border-radius:22px;padding:20px;box-shadow:var(--shadow);margin-bottom:16px}.card h3{margin:0 0 8px;font-size:1.08rem;font-weight:1000}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}\n.icon-row{display:flex;gap:13px;align-items:flex-start;padding:12px;border:1px solid var(--line);border-radius:16px;background:var(--surface-2)}.icon-row+.icon-row{margin-top:10px}.glyph{flex:0 0 auto;width:44px;height:44px;border-radius:14px;display:grid;place-items:center;background:var(--surface);border:1px solid var(--line);font-size:1.25rem;font-weight:1000}.icon-row strong{display:block;font-weight:1000}.icon-row span{display:block;color:var(--muted);font-size:.86rem;font-weight:750}.steps{counter-reset:s;display:grid;gap:10px}.step{display:flex;gap:12px;padding:12px 14px;border:1px solid var(--line);border-radius:16px;background:var(--surface-2)}.step:before{counter-increment:s;content:counter(s);flex:0 0 auto;width:26px;height:26px;border-radius:50%;display:grid;place-items:center;background:var(--primary);color:#fff;font-weight:1000;font-size:.82rem}.note{border-left:4px solid var(--accent);background:rgba(24,181,141,.09);border-radius:0 14px 14px 0;padding:12px 16px;font-size:.9rem;font-weight:750}.note.warn{border-left-color:var(--warning);background:rgba(215,158,29,.12)}.note.info{border-left-color:var(--primary);background:rgba(91,91,214,.10)}\n.dock-demo{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;background:var(--surface-2);border:1px solid var(--line);border-radius:20px;padding:12px}.dock-btn{position:relative;width:50px;height:50px;border-radius:15px;display:grid;place-items:center;background:var(--surface);border:1px solid var(--line);font-size:1.2rem;font-weight:1000}.dock-btn.active{background:var(--primary);color:#fff}.dot-badge{position:absolute;right:-5px;top:-5px;min-width:18px;height:18px;border-radius:999px;background:var(--danger);color:#fff;font-size:.62rem;display:grid;place-items:center;padding:0 5px;font-weight:1000}\n.levels{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.lvl-card{text-align:center;border:1px solid var(--line);border-radius:18px;background:var(--surface);padding:14px}.lvl-card .code{font-size:1.5rem;font-weight:1000;color:var(--primary)}.lvl-card .nm{font-weight:1000}.lvl-card .sub{color:var(--muted);font-size:.8rem;font-weight:750}\n.acc{border:1px solid var(--line);border-radius:18px;overflow:hidden;background:var(--surface);margin-bottom:10px}.acc summary{cursor:pointer;padding:14px 16px;font-weight:1000;list-style:none;display:flex;gap:8px;align-items:center}.acc summary::-webkit-details-marker{display:none}.acc summary span:last-child{margin-left:auto;color:var(--muted)}.world-list{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;padding:0 16px 16px}.world-item{padding:10px 12px;border-radius:14px;background:var(--surface-2);border:1px solid var(--line);font-size:.86rem}.world-item b{display:block}.world-item span{color:var(--muted);font-weight:700}\n.search-row{display:flex;gap:10px;margin-bottom:14px}.search-row input{flex:1;border:1px solid var(--line);border-radius:14px;background:var(--surface);color:var(--text);font:inherit;font-weight:800;padding:11px 14px}.hidden{display:none!important}.tag{display:inline-flex;padding:3px 8px;border:1px solid var(--line);border-radius:999px;background:var(--surface-2);font-size:.68rem;font-weight:1000;color:var(--muted);text-transform:uppercase;letter-spacing:.5px}footer{text-align:center;color:var(--muted);font-size:.82rem;font-weight:750;padding:30px 0;border-top:1px solid var(--line)}\n@media(max-width:900px){.layout{grid-template-columns:1fr}.toc{position:static}.toc nav{display:flex;gap:6px;overflow:auto}.toc h4{display:none}.toc button{white-space:nowrap;width:auto}.hero{grid-template-columns:1fr;text-align:center}.hero p{margin-left:auto;margin-right:auto}.grid2,.grid3,.levels,.world-list{grid-template-columns:1fr}.hero-icon{font-size:3.4rem}}\n</style>\n</head>\n<body>\n<a class=\"skip-link\" href=\"#contenido\">Saltar al contenido</a>\n<header class=\"m-header\">\n  <div class=\"logo-dot\">EN</div>\n  <div class=\"ht\"><strong>Manual de usuario</strong><span>Easy English Go · Inglés para la vida real</span></div>\n  <div class=\"spacer\"></div>\n  <div class=\"theme-toggle\" role=\"group\" aria-label=\"Tema del manual\"><button id=\"t-light\" class=\"active\" title=\"Modo claro\">☀</button><button id=\"t-dark\" title=\"Modo oscuro\">☾</button></div>\n</header>\n<main class=\"manual-shell\" id=\"contenido\">\n  <section class=\"hero\">\n    <div><span class=\"kicker\">Guía actualizada</span><h1>Aprender inglés en rutas, mundos y refuerzos.</h1><p>Este manual explica cómo usar la app actual: carretera, mundos, Centro de refuerzo, juegos, audio, video, canciones subtituladas, traducción, evaluaciones y backup. Ya no incluye identidad visual ni elección inicial de intensidad o tiempo de sesión, porque esas pantallas fueron retiradas.</p><div class=\"ver\"><span class=\"dot\"></span> Versión 5.0.55 · manual corregido</div></div>\n    <div class=\"hero-icon\" aria-hidden=\"true\">🚌🔁</div>\n  </section>\n  <div class=\"layout\">\n    <aside class=\"toc\"><nav aria-label=\"Índice del manual\"><h4>Contenido</h4>\n      <button type=\"button\" class=\"active\" data-target=\"intro\">1 · Qué es la app</button>\n      <button type=\"button\" data-target=\"acceso\">2 · Acceso y usuarios</button>\n      <button type=\"button\" data-target=\"dock\">3 · Menú inferior</button>\n      <button type=\"button\" data-target=\"menu\">4 · Menú hamburguesa</button>\n      <button type=\"button\" data-target=\"carretera\">5 · Carretera y mundos</button>\n      <button type=\"button\" data-target=\"centro-refuerzo\">6 · Centro de refuerzo</button>\n      <button type=\"button\" data-target=\"niveles\">7 · Niveles y mundos</button>\n      <button type=\"button\" data-target=\"leccion\">8 · Lección y capas</button>\n      <button type=\"button\" data-target=\"ejercicios\">9 · Ejercicios</button>\n      <button type=\"button\" data-target=\"juegos\">10 · Juegos rápidos</button>\n      <button type=\"button\" data-target=\"recursos\">11 · Recursos audiovisuales</button>\n      <button type=\"button\" data-target=\"traduccion\">12 · Traducción</button>\n      <button type=\"button\" data-target=\"dicc\">13 · Diccionario y biblioteca</button>\n      <button type=\"button\" data-target=\"eval\">14 · Evaluación y diplomas</button>\n      <button type=\"button\" data-target=\"ajustes\">15 · Ajustes y backup</button>\n      <button type=\"button\" data-target=\"iconos\">16 · Glosario de íconos</button>\n    </nav></aside>\n    <div class=\"content\">\n      <section class=\"block\" id=\"intro\"><h2><span class=\"num\">1</span> ¿Qué es Easy English Go?</h2><p class=\"lead\">Una PWA para aprender inglés útil desde situaciones reales.</p><div class=\"card\"><h3>La idea central</h3><p>Recorres una <b>carretera de mundos</b>. Cada mundo agrupa microlecciones, práctica, diálogo integrador y recursos de afianzamiento. Avanzas en A1, A2, B1 y B2, y puedes volver a reforzar cualquier mundo.</p><div class=\"grid3\"><div class=\"note info\"><b>4 niveles:</b> A1, A2, B1 y B2.</div><div class=\"note\"><b>120 mundos:</b> 30 por nivel.</div><div class=\"note warn\"><b>Avance local:</b> exportable como backup JSON.</div></div></div><div class=\"card\"><h3>Cómo se estudia ahora</h3><p>La app ya no pregunta intensidad ni tiempo de estudio al inicio. Entras con tu usuario, continúas la siguiente acción pendiente o abres la carretera para elegir el mundo disponible. La duración la define tu propio ritmo.</p></div></section>\n      <section class=\"block\" id=\"acceso\"><h2><span class=\"num\">2</span> Acceso y usuarios</h2><p class=\"lead\">Cada usuario conserva su progreso en el mismo dispositivo.</p><div class=\"grid2\"><div class=\"card\"><h3>Pantalla de bienvenida</h3><div class=\"icon-row\"><div class=\"glyph\">▶️</div><div><strong>Continuar</strong><span>Abre tu siguiente acción pendiente.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🛣️</div><div><strong>Ver carretera</strong><span>Abre el mapa de la ruta actual.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">📘</div><div><strong>Manual rápido</strong><span>Consulta esta guía sin alterar tu avance.</span></div></div></div><div class=\"card\"><h3>Usuarios y backup</h3><div class=\"steps\"><div class=\"step\"><div><b>Nickname:</b> crea o elige un usuario.</div></div><div class=\"step\"><div><b>Usuarios recientes:</b> aparecen como fichas con tu avance.</div></div><div class=\"step\"><div><b>Cargar backup:</b> restaura progreso desde JSON.</div></div></div></div></div></section>\n      <section class=\"block\" id=\"dock\"><h2><span class=\"num\">3</span> Menú inferior</h2><p class=\"lead\">Es la navegación principal de la app.</p><div class=\"card\"><div class=\"dock-demo\"><div class=\"dock-btn active\">🏠</div><div class=\"dock-btn\">🚌</div><div class=\"dock-btn\">🔁<span class=\"dot-badge\">3</span></div><div class=\"dock-btn\">🎧</div><div class=\"dock-btn\">Aa</div><div class=\"dock-btn\">🎓</div><div class=\"dock-btn\">A1</div><div class=\"dock-btn\">🚪</div><div class=\"dock-btn\">☰</div></div></div><div class=\"card\"><h3>Qué hace cada botón</h3><div class=\"icon-row\"><div class=\"glyph\">🏠</div><div><strong>Inicio</strong><span>Carretera principal.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🚌</div><div><strong>Mundo en curso</strong><span>Parada seleccionada o mundo actual.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🔁</div><div><strong>Centro de refuerzo</strong><span>Recursos del mundo y numerito de pendientes.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🎧</div><div><strong>Escuchar y repasar</strong><span>Práctica auditiva rápida.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">Aa</div><div><strong>Diccionario y biblioteca</strong><span>Palabras, frases y material de consulta.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🎓</div><div><strong>Diplomas</strong><span>Constancias internas de avance.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">A1</div><div><strong>Niveles</strong><span>Cambio entre A1, A2, B1 y B2.</span></div></div></div></section>\n      <section class=\"block\" id=\"menu\"><h2><span class=\"num\">4</span> Menú hamburguesa</h2><p class=\"lead\">Reúne herramientas, accesos y configuración.</p><div class=\"card\"><div class=\"grid2\"><div class=\"icon-row\"><div class=\"glyph\">📘</div><div><strong>Manual</strong><span>Abre esta guía.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🧪</div><div><strong>Evaluación</strong><span>Pruebas disponibles y pendientes.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">📊</div><div><strong>Ruta MCER</strong><span>Resumen de avance por nivel.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🎮</div><div><strong>Juegos rápidos</strong><span>Atajo a los juegos del mundo.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🗓️</div><div><strong>Agenda</strong><span>Recordatorios de estudio.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">💾</div><div><strong>Backup</strong><span>Exportar o cargar JSON.</span></div></div></div></div></section>\n      <section class=\"block\" id=\"carretera\"><h2><span class=\"num\">5</span> Carretera y mundos</h2><p class=\"lead\">Cada parada de la carretera es un mundo.</p><div class=\"grid2\"><div class=\"card\"><h3>Estados</h3><div class=\"icon-row\"><div class=\"glyph\">▶</div><div><strong>En curso</strong><span>Mundo actual.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🔓</div><div><strong>Desbloqueado</strong><span>Disponible para empezar.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">✅</div><div><strong>Completado</strong><span>Lecciones y diálogo consolidados.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🔒</div><div><strong>Bloqueado</strong><span>Se abre al completar el anterior.</span></div></div></div><div class=\"card\"><h3>Afianza este mundo</h3><p>Al completar un mundo aparece una tarjeta de afianzamiento. Si hay pendientes muestra <b>Afianza este mundo</b>; si no hay pendientes muestra <b>Explora recursos del mundo</b>. Ambos abren el Centro de refuerzo en la ruta y mundo actual.</p></div></div></section>\n      <section class=\"block\" id=\"centro-refuerzo\"><h2><span class=\"num\">6</span> Centro de refuerzo</h2><p class=\"lead\">Concentra todos los recursos de práctica de cada mundo.</p><div class=\"card\"><h3>Recursos disponibles por mundo</h3><div class=\"grid2\"><div class=\"icon-row\"><div class=\"glyph\">🔁</div><div><strong>Refuerzo guiado</strong><span>Corrige pendientes detectados.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🎬</div><div><strong>Diálogo animado</strong><span>Escena con controles compactos.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🗣️</div><div><strong>Inglés real</strong><span>Expresiones naturales en contexto.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🎧</div><div><strong>Escucha real</strong><span>Elige la idea principal y recibe feedback visual.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🎥</div><div><strong>Video de apoyo</strong><span>Enlace externo de refuerzo.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">▣♪</div><div><strong>Canción subtitulada</strong><span>Video musical con subtítulos como apoyo.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">📝</div><div><strong>Traducción</strong><span>Práctica progresiva ES–EN.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🎮</div><div><strong>Juegos rápidos</strong><span>Sopa, parejas, memoria, ordenar y Ruta de letras.</span></div></div></div></div><div class=\"grid2\"><div class=\"card\"><h3>En computador</h3><p>La pantalla se divide en dos: a la izquierda los 30 mundos de la ruta, a la derecha los recursos del mundo seleccionado.</p></div><div class=\"card\"><h3>En celular</h3><p>Primero aparecen los recursos del mundo actual. La lista de 30 mundos queda plegada bajo <b>Cambiar mundo</b> y se recoge automáticamente al seleccionar un mundo.</p></div></div><div class=\"note info\"><b>Navegación contextual:</b> los módulos abiertos desde el Centro de refuerzo integran X para cerrar, volver a Centro de refuerzo, volver a Parada seleccionada y volver a Carretera principal.</div></section>\n      <section class=\"block\" id=\"niveles\"><h2><span class=\"num\">7</span> Niveles y mundos</h2><p class=\"lead\">La app organiza el recorrido en cuatro niveles MCER, cada uno con 30 mundos.</p><div class=\"levels\"><div class=\"lvl-card\"><div class=\"code\">A1</div><div class=\"nm\">Inicial</div><div class=\"sub\">Base cotidiana</div></div><div class=\"lvl-card\"><div class=\"code\">A2</div><div class=\"nm\">Acceso</div><div class=\"sub\">Autonomía simple</div></div><div class=\"lvl-card\"><div class=\"code\">B1</div><div class=\"nm\">Umbral</div><div class=\"sub\">Narrar y explicar</div></div><div class=\"lvl-card\"><div class=\"code\">B2</div><div class=\"nm\">Avanzado</div><div class=\"sub\">Matices y argumentación</div></div></div><div class=\"card\"><h3>Vista resumida de mundos</h3><details class=\"acc\"><summary>A1 · Inicial <span>›</span></summary><div class=\"world-list\"><div class=\"world-item\"><b>M1–M10</b><span>Saludos, preguntas, casa, ciudad y viaje básico.</span></div><div class=\"world-item\"><b>M11–M20</b><span>Vida digital, salud, ocio, opinión y autonomía.</span></div><div class=\"world-item\"><b>M21–M30</b><span>Aula, trabajo, comunidad, vínculos, proyectos e integración.</span></div></div></details><details class=\"acc\"><summary>A2 · Acceso <span>›</span></summary><div class=\"world-list\"><div class=\"world-item\"><b>M1–M10</b><span>Rutinas, compras, servicios y entregas.</span></div><div class=\"world-item\"><b>M11–M20</b><span>Transporte, viajes, experiencias recientes y vida social.</span></div><div class=\"world-item\"><b>M21–M30</b><span>Estudio, trabajo simple, trámites, comunicación y cierre A2.</span></div></div></details><details class=\"acc\"><summary>B1 · Umbral <span>›</span></summary><div class=\"world-list\"><div class=\"world-item\"><b>M1–M10</b><span>Experiencias, problemas, reuniones y acuerdos.</span></div><div class=\"world-item\"><b>M11–M20</b><span>Viajes, trámites, opiniones, comparación y argumentación simple.</span></div><div class=\"world-item\"><b>M21–M30</b><span>Relaciones, proyectos, lectura, escucha, síntesis y cierre B1.</span></div></div></details><details class=\"acc\"><summary>B2 · Avanzado <span>›</span></summary><div class=\"world-list\"><div class=\"world-item\"><b>M1–M10</b><span>Narración compleja y argumentación con matices.</span></div><div class=\"world-item\"><b>M11–M20</b><span>Proyectos, trabajo, evidencias, síntesis y explicación textual.</span></div><div class=\"world-item\"><b>M21–M30</b><span>Expectativas, límites, cultura, conversación larga y autonomía avanzada.</span></div></div></details></div></section>\n      <section class=\"block\" id=\"leccion\"><h2><span class=\"num\">8</span> Lección y capas</h2><p class=\"lead\">Cada microlección avanza por capas breves.</p><div class=\"grid2\"><div class=\"icon-row\"><div class=\"glyph\">🔎</div><div><strong>Descubre</strong><span>Reconoce señales, palabras y sentido general.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🏷️</div><div><strong>Nombra</strong><span>Identifica y nombra elementos concretos.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🗣️</div><div><strong>Usa</strong><span>Aplica frases en situaciones reales.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🧠</div><div><strong>Explica</strong><span>Amplía, justifica y conecta ideas.</span></div></div></div></section>\n      <section class=\"block\" id=\"ejercicios\"><h2><span class=\"num\">9</span> Ejercicios</h2><p class=\"lead\">La práctica combina comprensión, elección, escritura y audio.</p><div class=\"grid2\"><div class=\"icon-row\"><div class=\"glyph\">🧩</div><div><strong>Opción / Parejas</strong><span>Relaciona frases, ideas o traducciones.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">✔️</div><div><strong>Verdadero/Falso</strong><span>Decide si una idea corresponde al contexto.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">✍️</div><div><strong>Completar</strong><span>Escribe palabras o frases faltantes.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🔊</div><div><strong>Audio</strong><span>Escucha, repite y reconoce sentido.</span></div></div></div></section>\n      <section class=\"block\" id=\"juegos\"><h2><span class=\"num\">10</span> Juegos rápidos</h2><p class=\"lead\">Refuerzan vocabulario y comprensión con sesiones breves.</p><div class=\"card\"><div class=\"grid2\"><div class=\"icon-row\"><div class=\"glyph\">🔎</div><div><strong>Sopa de letras</strong><span>Busca palabras clave del mundo.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🧠</div><div><strong>Memoria visual</strong><span>Une imagen/emoji con palabra o frase.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🔀</div><div><strong>Ordenar palabras</strong><span>Reconstruye una frase.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🚌</div><div><strong>Ruta de letras</strong><span>Guía el bus por las letras correctas sin revelar la siguiente letra.</span></div></div></div></div><div class=\"note info\">Desde juegos rápidos puedes volver a Centro de refuerzo, Parada seleccionada o Carretera principal, conservando el mundo actual.</div></section>\n      <section class=\"block\" id=\"recursos\"><h2><span class=\"num\">11</span> Recursos audiovisuales</h2><p class=\"lead\">Apoyan escucha, pronunciación, comprensión y exposición al inglés real.</p><div class=\"grid2\"><div class=\"card\"><h3>Diálogo animado</h3><p>Los controles se muestran compactos como iconos con tooltip: ▶, ⏸, 🔊, EN–ES, 🔇, Normal/🐢, ↺, ⏮ y ⏭.</p></div><div class=\"card\"><h3>Escucha real</h3><p>El módulo indica: “Escucha, elige la idea principal y recibe respuesta al instante”. Al acertar usa microfeedback visual en lugar de texto largo.</p></div><div class=\"card\"><h3>Video de apoyo</h3><p>Abre un recurso externo relacionado con el mundo. La app enlaza, no aloja el video.</p></div><div class=\"card\"><h3>Canción subtitulada ▣♪</h3><p>Abre un video musical con subtítulos como apoyo lingüístico. La app no reproduce ni almacena letras completas, audio o video.</p></div></div></section>\n      <section class=\"block\" id=\"traduccion\"><h2><span class=\"num\">12</span> Traducción progresiva</h2><p class=\"lead\">Entrena el paso entre español e inglés con ayudas y revisión.</p><div class=\"card\"><p>El módulo incluye ayuda de traducción, X para cerrar y navegación contextual hacia Centro de refuerzo, Parada seleccionada y Carretera principal. El botón redundante de “Volver a la ruta” fue retirado.</p></div></section>\n      <section class=\"block\" id=\"dicc\"><h2><span class=\"num\">13</span> Diccionario y biblioteca</h2><p class=\"lead\">Consulta palabras, frases y materiales sin abandonar tu recorrido.</p><div class=\"grid2\"><div class=\"card\"><h3>Diccionario</h3><p>Busca palabras por texto, Enter o botón de búsqueda. Útil para repasar términos vistos en las rutas.</p></div><div class=\"card\"><h3>Biblioteca</h3><p>Reúne materiales internos de consulta y apoyo.</p></div></div></section>\n      <section class=\"block\" id=\"eval\"><h2><span class=\"num\">14</span> Evaluación y diplomas</h2><p class=\"lead\">La app registra consolidación por mundos, bloques y niveles.</p><div class=\"grid2\"><div class=\"card\"><h3>Evaluaciones</h3><p>Se activan por tramos y ayudan a revisar comprensión, vocabulario, traducción y escucha.</p></div><div class=\"card\"><h3>Diplomas</h3><p>Son constancias internas de avance. Sirven como memoria de progreso dentro de la app.</p></div></div></section>\n      <section class=\"block\" id=\"ajustes\"><h2><span class=\"num\">15</span> Ajustes, agenda y backup</h2><p class=\"lead\">Controla preferencias y protege tu progreso.</p><div class=\"grid2\"><div class=\"card\"><h3>Ajustes</h3><p>Incluye audio, voz, movimiento, apariencia, recordatorios y herramientas de datos.</p></div><div class=\"card\"><h3>Backup JSON</h3><p>Exporta tu avance para conservarlo o cargarlo en otro navegador/dispositivo.</p></div></div><div class=\"note warn\"><b>Recomendación:</b> exporta un backup periódicamente. Los datos se guardan localmente en el navegador.</div></section>\n      <section class=\"block\" id=\"iconos\"><h2><span class=\"num\">16</span> Glosario de íconos</h2><p class=\"lead\">Busca rápidamente qué representa cada ícono.</p><div class=\"search-row\"><input id=\"icon-filter\" type=\"text\" placeholder=\"Filtrar íconos… ej.: refuerzo, audio, backup\" aria-label=\"Filtrar íconos\"></div><div class=\"card\" id=\"icon-list\">\n        <div class=\"icon-row\"><div class=\"glyph\">🏠</div><div><strong>Inicio</strong><span>Carretera principal.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🚌</div><div><strong>Mundo / bus</strong><span>Parada actual o Ruta de letras.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🔁</div><div><strong>Centro de refuerzo</strong><span>Recursos y pendientes.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🎬</div><div><strong>Diálogo animado</strong><span>Escena practicable.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🗣️</div><div><strong>Inglés real</strong><span>Expresiones naturales.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🎧</div><div><strong>Escucha real</strong><span>Comprensión auditiva.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🎥</div><div><strong>Video de apoyo</strong><span>Recurso externo.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">▣♪</div><div><strong>Canción subtitulada</strong><span>Video musical con subtítulos.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">📝</div><div><strong>Traducción</strong><span>Práctica ES–EN.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🎮</div><div><strong>Juegos rápidos</strong><span>Minijuegos de refuerzo.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">🎓</div><div><strong>Diplomas</strong><span>Constancias internas.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">💾</div><div><strong>Exportar backup</strong><span>Guardar avance.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">📥</div><div><strong>Cargar backup</strong><span>Restaurar avance.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">✕</div><div><strong>Cerrar</strong><span>Cierra ventana o módulo.</span></div></div><div class=\"icon-row\"><div class=\"glyph\">☰</div><div><strong>Menú</strong><span>Herramientas y configuración.</span></div></div>\n      </div></section>\n    </div>\n  </div>\n  <footer>Easy English Go · Inglés para la vida real — Manual de usuario · v5.0.55.<br>Aplicación web instalable (PWA). Tus avances se guardan localmente en tu dispositivo.</footer>\n</main>\n<script>\n(function(){\n  var body=document.body, light=document.getElementById('t-light'), dark=document.getElementById('t-dark');\n  function setTheme(isDark){body.classList.toggle('dark',isDark);light.classList.toggle('active',!isDark);dark.classList.toggle('active',isDark);try{localStorage.setItem('eeg-manual-theme',isDark?'dark':'light')}catch(e){}}\n  light.addEventListener('click',function(){setTheme(false)});dark.addEventListener('click',function(){setTheme(true)});\n  try{if(localStorage.getItem('eeg-manual-theme')==='dark')setTheme(true)}catch(e){}\n  var buttons=[].slice.call(document.querySelectorAll('.toc button[data-target]'));\n  var sections=buttons.map(function(btn){return document.getElementById(btn.dataset.target)}).filter(Boolean);\n  buttons.forEach(function(btn){btn.addEventListener('click',function(ev){ev.preventDefault();ev.stopPropagation();var target=document.getElementById(btn.dataset.target);if(!target)return;target.scrollIntoView({behavior:'smooth',block:'start'});try{history.replaceState(null,'','#'+btn.dataset.target)}catch(e){} buttons.forEach(function(b){b.classList.toggle('active',b===btn)});});});\n  var obs=new IntersectionObserver(function(entries){entries.forEach(function(en){if(en.isIntersecting){buttons.forEach(function(btn){btn.classList.toggle('active',btn.dataset.target===en.target.id)});}});},{rootMargin:'-38% 0px -56% 0px'});sections.forEach(function(sec){obs.observe(sec)});\n  var inp=document.getElementById('icon-filter');if(inp){inp.addEventListener('input',function(){var q=inp.value.trim().toLowerCase();document.querySelectorAll('#icon-list .icon-row').forEach(function(row){row.classList.toggle('hidden',q && row.textContent.toLowerCase().indexOf(q)<0);});});}\n})();\n</script>\n</body>\n</html>\n";

function openManualModal() {
  const manualSrcdoc = escapeHtml(MANUAL_HTML_DOC);
  openModal({
    customRender: () => `
      <div class="modal-overlay on" role="dialog" aria-modal="true" aria-labelledby="manual-title">
        <div class="modal manual-modal-shell manual-html-shell">
          <div class="modal-h">
            <strong id="manual-title">Manual de usuario · Easy English Go</strong>
            <div class="button-row">
              <button class="btn btn-secondary btn-small" id="manual-open-tab">Abrir en pestaña</button>
              <button class="btn btn-soft btn-small" id="manual-close-btn">Cerrar</button>
            </div>
          </div>
          <div class="modal-b manual-html-body">
            <iframe class="manual-html-frame" srcdoc="${manualSrcdoc}" title="Manual de usuario Easy English Go"></iframe>
          </div>
          <div class="modal-f">
            <button class="btn btn-primary" id="manual-ok-btn">Entendido</button>
          </div>
        </div>
      </div>`,
    afterRender: () => {
      document.getElementById('manual-close-btn')?.addEventListener('click', closeModal);
      document.getElementById('manual-ok-btn')?.addEventListener('click', closeModal);
      document.getElementById('manual-open-tab')?.addEventListener('click', () => {
        const blob = new Blob([MANUAL_HTML_DOC], { type: 'text/html;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        window.open(url, '_blank', 'noopener');
        setTimeout(() => URL.revokeObjectURL(url), 20000);
      });
    }
  });
}

function getTourStepsForView(view = ui.view) {
  return TOUR_STEPS[view] || [];
}

function clearContextTour() {
  document.querySelectorAll('.tour-target-active').forEach(el => el.classList.remove('tour-target-active'));
  const layer = document.getElementById('app-context-tour');
  if (layer) layer.remove();
  if (contextTourResizeBound) {
    window.removeEventListener('resize', contextTourResizeBound);
    window.removeEventListener('scroll', contextTourResizeBound, true);
    contextTourResizeBound = null;
  }
  if (contextTourKeyBound) {
    window.removeEventListener('keydown', contextTourKeyBound);
    contextTourKeyBound = null;
  }
  activeContextTour = null;
}

function completeTour() {
  state.meta.tourDone = true;
  state.meta.tourDismissedAt = new Date().toISOString();
  saveState();
  clearContextTour();
}

function dismissContextTour(options = {}) {
  const remember = options.remember !== false;
  if (remember) {
    state.meta.tourDone = true;
    state.meta.tourDismissedAt = new Date().toISOString();
    saveState();
  }
  clearContextTour();
  if (options.toast) showToast(options.toast, options.kind || 'neutral');
}

function goToSuggestedFocusFromTour() {
  const savedPoint = getSavedPoint();
  completeTour();
  if (savedPoint && getLessonById(savedPoint.lessonId)) {
    if (Number.isInteger(savedPoint.exerciseIndex)) {
      setView('exercise', { lessonId: savedPoint.lessonId, exerciseIndex: savedPoint.exerciseIndex });
    } else {
      setView('lesson', { lessonId: savedPoint.lessonId });
    }
    return;
  }
  const lesson = getCurrentLesson() || getLessonById('lesson_1') || CONTENT.lessons?.[0];
  if (lesson) setView('lesson', { lessonId: lesson.id });
  else setView('dashboard');
}

function handleContextTourAction(action) {
  if (action === 'suggestedFocus') return goToSuggestedFocusFromTour();
  dismissContextTour({ remember: true });
}

function startContextTour(options = {}) {
  if (activeContextTour && !options.force) return;
  if (activeContextTour && options.force) clearContextTour();
  const supportedView = options.view || ui.view;
  const steps = getTourStepsForView(supportedView);
  if (!steps.length) {
    if (!options.silent) showToast('No hay tour contextual disponible en esta pantalla.', 'neutral');
    return;
  }
  activeContextTour = { view: supportedView, steps, index: 0 };
  contextTourKeyBound = (event) => {
    if (event.key === 'Escape' && activeContextTour) {
      event.preventDefault();
      dismissContextTour({ remember: true, toast: 'Tour cerrado. Puedes abrirlo de nuevo desde el menú.', kind: 'neutral' });
    }
  };
  window.addEventListener('keydown', contextTourKeyBound);
  renderContextTour();
}

function moveContextTour(delta) {
  if (!activeContextTour) return;
  const nextIndex = activeContextTour.index + delta;
  if (nextIndex < 0) return;
  if (nextIndex >= activeContextTour.steps.length) { completeTour(); return; }
  activeContextTour.index = nextIndex;
  renderContextTour();
}

function renderContextTour() {
  if (!activeContextTour) return;
  const step = activeContextTour.steps[activeContextTour.index];
  const target = document.querySelector(step.target);
  if (!target) {
    moveContextTour(1);
    return;
  }
  target.scrollIntoView({ block: 'center', behavior: 'smooth' });
  window.setTimeout(() => {
    if (!activeContextTour) return;
    const rect = target.getBoundingClientRect();
    document.querySelectorAll('.tour-target-active').forEach(el => el.classList.remove('tour-target-active'));
    target.classList.add('tour-target-active');
    let layer = document.getElementById('app-context-tour');
    if (!layer) {
      layer = document.createElement('div');
      layer.id = 'app-context-tour';
      document.body.appendChild(layer);
    }
    const cardWidth = Math.min(360, window.innerWidth - 24);
    const estimatedHeight = step.action ? 250 : 220;
    let top = rect.bottom + 14;
    if (top + estimatedHeight > window.innerHeight - 12) top = Math.max(12, rect.top - estimatedHeight - 14);
    let left = rect.left;
    if (left + cardWidth > window.innerWidth - 12) left = window.innerWidth - cardWidth - 12;
    if (left < 12) left = 12;
    const pointerLeft = Math.min(Math.max(rect.left + rect.width / 2 - left - 9, 16), cardWidth - 24);
    const isLast = activeContextTour.index === activeContextTour.steps.length - 1;
    const actionButton = step.action ? `<button class="btn btn-primary btn-small context-tour-action-btn" id="context-tour-action">${escapeHtml(step.cta || 'Ir ahora')}</button>` : '';
    layer.innerHTML = `
      <div class="context-tour-backdrop" id="context-tour-backdrop" title="Cerrar tour"></div>
      <div class="context-tour-highlight" style="top:${Math.max(8, rect.top - 6)}px;left:${Math.max(8, rect.left - 6)}px;width:${rect.width + 12}px;height:${rect.height + 12}px"></div>
      <div class="context-tour-card" role="dialog" aria-modal="true" aria-label="Tour guiado" style="top:${top}px;left:${left}px;width:${cardWidth}px">
        <button class="context-tour-close" id="context-tour-close" aria-label="Cerrar tour" title="Cerrar tour">×</button>
        <div class="context-tour-pointer" style="left:${pointerLeft}px"></div>
        <div class="context-tour-topline">
          <span class="context-tour-emoji">${step.emoji || '🧭'}</span>
          <div>
            <strong>${escapeHtml(step.title)}</strong>
            <p>${escapeHtml(step.body)}</p>
          </div>
        </div>
        <div class="context-tour-progress" aria-label="Progreso del tour">${activeContextTour.steps.map((_, idx) => `<span class="context-tour-dot ${idx === activeContextTour.index ? 'active' : ''}"></span>`).join('')}</div>
        <div class="context-tour-actions ${step.action ? 'context-tour-actions-with-cta' : ''}">
          <button class="btn btn-soft btn-small" id="context-tour-skip">Omitir tour</button>
          <div class="context-tour-main-actions">
            ${activeContextTour.index ? '<button class="btn btn-secondary btn-small" id="context-tour-prev">Anterior</button>' : ''}
            ${actionButton}
            <button class="btn btn-primary btn-small" id="context-tour-next">${isLast ? 'Listo' : 'Siguiente'}</button>
          </div>
        </div>
      </div>`;
    layer.querySelector('#context-tour-close')?.addEventListener('click', () => dismissContextTour({ remember: true, toast: 'Tour cerrado. Puedes abrirlo de nuevo desde el menú.', kind: 'neutral' }));
    layer.querySelector('#context-tour-backdrop')?.addEventListener('click', () => dismissContextTour({ remember: true, toast: 'Tour cerrado. Puedes abrirlo de nuevo desde el menú.', kind: 'neutral' }));
    layer.querySelector('#context-tour-skip')?.addEventListener('click', () => dismissContextTour({ remember: true, toast: 'Tour omitido. Puedes abrirlo luego desde el menú.', kind: 'neutral' }));
    layer.querySelector('#context-tour-prev')?.addEventListener('click', () => moveContextTour(-1));
    layer.querySelector('#context-tour-next')?.addEventListener('click', () => moveContextTour(1));
    layer.querySelector('#context-tour-action')?.addEventListener('click', () => handleContextTourAction(step.action));
    if (!contextTourResizeBound) {
      contextTourResizeBound = () => { if (activeContextTour) renderContextTour(); };
      window.addEventListener('resize', contextTourResizeBound);
      window.addEventListener('scroll', contextTourResizeBound, true);
    }
  }, 120);
}

/* ── Biblioteca de repaso (videos BBC) y Diccionario A-Z ─────── */

function getVideosByWorld(worldId, routeId = state.progress.currentRouteId) {
  if (!CONTENT || !CONTENT.reviewLibrary) return [];
  return CONTENT.reviewLibrary.filter(v => {
    const itemRoute = v.routeId || 'ruta_1';
    return v.worldId === worldId && itemRoute === routeId;
  });
}

function getDictionaryEntries() {
  if (!CONTENT || !CONTENT.dictionary) return [];
  return CONTENT.dictionary;
}

function searchDictionary(query) {
  const q = normalizeText(query);
  if (!q) return getDictionaryEntries();
  return getDictionaryEntries().filter(e => {
    const haystack = [
      e.word, e.es, e.example, e.exampleEs, e.use, e.type, e.lessonTitle,
      e.worldId, e.lessonId
    ].map(value => normalizeText(value || '')).join(' ');
    return haystack.includes(q);
  });
}

function getDictionaryTypes() {
  const types = new Set(getDictionaryEntries().map(e => e.type));
  return Array.from(types).sort();
}

function openVideoLink(url) {
  if (!url) { showToast('Enlace no disponible aún.', 'warn'); return; }
  window.open(url, '_blank', 'noopener');
}


