function getAnimatedDialogueKey(worldId) {
  const raw = String(worldId || '').trim();
  if (!raw) return null;
  if (/^M\d+$/i.test(raw)) return raw.toUpperCase();
  if (/^world_\d+$/i.test(raw)) return `M${Number(raw.replace(/\D/g, ''))}`;
  if (/^lesson_\d+$/i.test(raw)) {
    const world = getBasicWorldForLesson(raw);
    return world ? getAnimatedDialogueKey(world.id) : null;
  }
  if (/^\d+$/.test(raw)) return `M${Number(raw)}`;
  const m = raw.match(/(\d+)$/);
  return m ? `M${Number(m[1])}` : null;
}

function getAnimatedDialogue(worldId, routeId = state.progress.currentRouteId) {
  const key = getAnimatedDialogueKey(worldId);
  if (!key || !Array.isArray(animatedDialogues)) return null;
  const activeRouteId = routeId || state.progress.currentRouteId || 'ruta_1';
  const levelCode = getRouteShortCode(activeRouteId);
  const routeSpecificId = `${levelCode}-${key}`;
  return animatedDialogues.find(dialogue => dialogue.id === routeSpecificId && dialogue.routeId === activeRouteId)
    || animatedDialogues.find(dialogue => dialogue.id === key && dialogue.routeId === activeRouteId)
    || (activeRouteId === 'ruta_1' ? animatedDialogues.find(dialogue => dialogue.id === key && !dialogue.routeId) : null)
    || null;
}

function getAnimatedDialogueProgress() {
  try {
    return JSON.parse(localStorage.getItem('animatedDialogueProgress') || '{}') || {};
  } catch (error) {
    return {};
  }
}

function saveAnimatedDialogueProgress(worldKey, patch = {}) {
  const progress = getAnimatedDialogueProgress();
  progress[worldKey] = { ...(progress[worldKey] || {}), ...patch };
  localStorage.setItem('animatedDialogueProgress', JSON.stringify(progress));
}

function getAnimatedDialogueLine(dialogue) {
  return dialogue?.lines?.[animatedDialogueRuntime.lineIndex] || dialogue?.lines?.[0] || null;
}

function setDialogueVoiceStatus(status = '') {
  animatedDialogueRuntime.status = status;
  const el = document.getElementById('adm-voice-status');
  if (el) el.textContent = status || 'Listo';
}

function stopAnimatedDialoguePlayback() {
  animatedDialogueRuntime.playing = false;
  animatedDialogueRuntime.token += 1;
  window.clearTimeout(animatedDialogueRuntime.timer);
  animatedDialogueRuntime.timer = null;
  if (typeof cancelSpeechSequence === 'function') cancelSpeechSequence();
  if ('speechSynthesis' in window) window.speechSynthesis.cancel();
  if (animatedDialogueRuntime.worldKey) {
    saveAnimatedDialogueProgress(animatedDialogueRuntime.worldKey, { lastLine: animatedDialogueRuntime.lineIndex });
  }
}

function pickDialogueVoice(langPrefix) {
  if (!('speechSynthesis' in window)) return null;
  const voices = window.speechSynthesis.getVoices() || [];
  if (langPrefix === 'es') {
    return voices.find(v => /^es-CO/i.test(v.lang))
      || voices.find(v => /^es-ES/i.test(v.lang))
      || voices.find(v => /^es(-|_|$)/i.test(v.lang))
      || null;
  }
  return voices.find(v => /^en(-|_|$)/i.test(v.lang)) || null;
}


function scrollActiveDialogueLineIntoView() {
  const activeLine =
    document.querySelector('.adm-bubble.active') ||
    document.querySelector('.animated-dialogue-line.is-active') ||
    document.querySelector('.dialogue-line.active');

  if (!activeLine) return;

  const container =
    activeLine.closest('.adm-chat') ||
    activeLine.closest('.animated-dialogue-left') ||
    activeLine.closest('.animated-dialogue-scroll') ||
    activeLine.closest('.dialogue-lines-panel') ||
    activeLine.closest('.dialogue-chat-panel');

  if (!container) return;

  const containerRect = container.getBoundingClientRect();
  const lineRect = activeLine.getBoundingClientRect();

  const safeOffset = Math.max(90, Math.round(container.clientHeight * 0.28));
  const targetTop =
    container.scrollTop +
    (lineRect.top - containerRect.top) -
    safeOffset;

  container.scrollTo({
    top: Math.max(0, targetTop),
    behavior: 'smooth'
  });
}

function afterDialogueLineRenderScroll() {
  requestAnimationFrame(() => {
    window.setTimeout(scrollActiveDialogueLineIntoView, 90);
  });
}


function speakTextAsPromise(text, lang, rate = 0.9) {
  return new Promise(resolve => {
    const phrase = String(text || '').trim();
    if (!('speechSynthesis' in window) || !phrase) {
      resolve();
      return;
    }
    try {
      const utterance = new SpeechSynthesisUtterance(phrase);
      utterance.lang = lang;
      utterance.rate = rate;
      utterance.pitch = 1;
      const voice = pickDialogueVoice(lang.startsWith('es') ? 'es' : 'en');
      if (voice) utterance.voice = voice;
      utterance.onend = resolve;
      utterance.onerror = resolve;
      window.speechSynthesis.speak(utterance);
    } catch (error) {
      console.warn('Animated dialogue voice error', error);
      resolve();
    }
  });
}

async function speakAnimatedEnglishLine(line, token) {
  if (!line?.en) return;
  if (!('speechSynthesis' in window)) {
    setDialogueVoiceStatus('Voz no disponible en este navegador');
    await new Promise(resolve => { animatedDialogueRuntime.timer = window.setTimeout(resolve, getAnimatedSilentDelay(line)); });
    return;
  }
  window.speechSynthesis.cancel();
  const rate = animatedDialogueRuntime.voiceSpeed === 'slow' ? 0.72 : 0.9;
  setDialogueVoiceStatus('Escuchando en inglés');
  await speakTextAsPromise(line.en, 'en-US', rate);
  if (token === animatedDialogueRuntime.token) setDialogueVoiceStatus('');
}

async function speakAnimatedEnglishSpanishLine(line, token) {
  if (!line?.en || !line?.es) return;
  if (!('speechSynthesis' in window)) {
    setDialogueVoiceStatus('Voz no disponible en este navegador');
    await new Promise(resolve => { animatedDialogueRuntime.timer = window.setTimeout(resolve, getAnimatedSilentDelay(line)); });
    return;
  }
  window.speechSynthesis.cancel();
  const rate = animatedDialogueRuntime.voiceSpeed === 'slow' ? 0.72 : 0.9;
  setDialogueVoiceStatus('Escuchando EN–ES');
  await speakTextAsPromise(line.en, 'en-US', rate);
  await new Promise(resolve => setTimeout(resolve, 420));
  if (token !== animatedDialogueRuntime.token) return;
  await speakTextAsPromise(line.es, 'es-ES', Math.min(1, rate + 0.05));
  if (token === animatedDialogueRuntime.token) setDialogueVoiceStatus('');
}

function getAnimatedSilentDelay(line) {
  const baseDelay = animatedDialogueRuntime.voiceSpeed === 'slow' ? 4200 : 3000;
  return Math.max(baseDelay, String(line?.en || '').length * 70);
}

async function speakCurrentAnimatedDialogueLine(line, token = animatedDialogueRuntime.token) {
  if (animatedDialogueRuntime.voiceMode === 'off') {
    setDialogueVoiceStatus('Sin voz');
    await new Promise(resolve => {
      animatedDialogueRuntime.timer = window.setTimeout(resolve, getAnimatedSilentDelay(line));
    });
    return;
  }
  if (animatedDialogueRuntime.voiceMode === 'en-es') {
    await speakAnimatedEnglishSpanishLine(line, token);
    return;
  }
  await speakAnimatedEnglishLine(line, token);
}

function renderAnimatedDialogueModalBody(dialogue) {
  if (!dialogue) return '';
  const characters = Object.fromEntries((dialogue.characters || []).map(character => [character.id, character]));
  const progress = getAnimatedDialogueProgress()[dialogue.id] || {};
  const current = animatedDialogueRuntime.lineIndex;
  const total = dialogue.lines.length;
  const activeLine = dialogue.lines[current] || dialogue.lines[0];
  return `
    <div class="adm-modal">
      ${renderSupportModuleNav(inferModuleWorldId(dialogue), inferModuleRouteId('', dialogue), { mode: 'modal' })}
      <div class="adm-head">
        <div>
          <div class="section-kicker">${escapeHtml(dialogue.kicker || '🎬 Diálogo animado')}</div>
          <h2>${escapeHtml(dialogue.world)} · ${escapeHtml(dialogue.title)}</h2>
          <p class="muted">${escapeHtml(dialogue.scene)}</p>
        </div>
        <button class="btn btn-secondary btn-icon" id="adm-close-btn" aria-label="Cerrar diálogo animado" title="Cerrar">✕</button>
      </div>

      <div class="adm-meta-row">
        <span class="chip">Línea ${current + 1} de ${total}</span>
        <span class="chip">${progress.completed ? '✅ Completado' : '🧭 En práctica'}</span>
        <span class="chip" id="adm-voice-status">${escapeHtml(animatedDialogueRuntime.status || 'Listo')}</span>
      </div>

      <div class="adm-layout">
        <div class="adm-chat" aria-live="polite">
          ${dialogue.lines.map((line, index) => {
            const character = characters[line.speaker] || { name: line.speaker, avatar: '🧑' };
            return `
              <div class="adm-bubble ${index === current ? 'active' : ''} ${index < current ? 'seen' : ''}" data-adm-line="${index}">
                <div class="adm-avatar">${escapeHtml(character.avatar || '🧑')}</div>
                <div class="adm-bubble-body">
                  <strong>${escapeHtml(character.name || line.speaker)}</strong>
                  <p class="adm-en">${escapeHtml(line.en)}</p>
                  <p class="adm-es">${escapeHtml(line.es)}</p>
                </div>
              </div>`;
          }).join('')}
        </div>

        <aside class="adm-side">
          <div class="adm-active-card">
            <span class="section-kicker">Línea activa</span>
            <h3>${escapeHtml((characters[activeLine?.speaker] || {}).name || activeLine?.speaker || '')}</h3>
            <p class="adm-en big">${escapeHtml(activeLine?.en || '')}</p>
            <p class="adm-es">${escapeHtml(activeLine?.es || '')}</p>
          </div>
          <div class="adm-keyphrases">
            <strong>Frases clave</strong>
            ${(dialogue.keyPhrases || []).map(item => `<div class="adm-keyphrase"><span>${escapeHtml(item.en)}</span><small>${escapeHtml(item.es)}</small></div>`).join('')}
          </div>
          ${dialogue.realExpression ? `
            <div class="adm-real-expression">
              <strong>${escapeHtml(dialogue.realExpression.label || '💬 Así se dice')}</strong>
              <div class="adm-real-phrase">${escapeHtml(dialogue.realExpression.phrase || '')}</div>
              <small><b>Real:</b> ${escapeHtml(dialogue.realExpression.meaning || '')}</small>
              <small><b>No literal:</b> ${escapeHtml(dialogue.realExpression.literal || '')}</small>
              <small><b>Uso:</b> ${escapeHtml(dialogue.realExpression.use || '')}</small>
              <div class="adm-real-question">${escapeHtml(dialogue.realExpression.question || '¿Qué quiso decir?')}</div>
              <div class="adm-real-options">
                ${(dialogue.realExpression.options || []).map((option, idx) => `<button type="button" class="adm-real-option" data-real-expression-option="${idx}" data-real-expression-correct="${idx === dialogue.realExpression.correctIndex ? 'true' : 'false'}">${escapeHtml(option)}</button>`).join('')}
              </div>
              <div class="adm-real-feedback" id="adm-real-feedback" aria-live="polite"></div>
            </div>` : ''}
        </aside>
      </div>

      <div class="adm-controls adm-controls-icon-only" aria-label="Controles del diálogo animado">
        <button class="btn btn-primary btn-sm adm-icon-control" id="adm-play-btn" title="Play" aria-label="Play">▶</button>
        <button class="btn btn-secondary btn-sm adm-icon-control" id="adm-pause-btn" title="Pausa" aria-label="Pausa">⏸</button>
        <button class="btn btn-soft btn-sm adm-icon-control ${animatedDialogueRuntime.voiceMode === 'en' ? 'active' : ''}" data-adm-voice="en" title="Inglés" aria-label="Inglés">🔊</button>
        <button class="btn btn-soft btn-sm adm-icon-control ${animatedDialogueRuntime.voiceMode === 'en-es' ? 'active' : ''}" data-adm-voice="en-es" title="EN–ES" aria-label="EN–ES">EN–ES</button>
        <button class="btn btn-soft btn-sm adm-icon-control ${animatedDialogueRuntime.voiceMode === 'off' ? 'active' : ''}" data-adm-voice="off" title="Sin voz" aria-label="Sin voz">🔇</button>
        <button class="btn btn-soft btn-sm adm-icon-control" id="adm-speed-btn" title="${animatedDialogueRuntime.voiceSpeed === 'slow' ? 'Lento' : 'Normal'}" aria-label="${animatedDialogueRuntime.voiceSpeed === 'slow' ? 'Lento' : 'Normal'}">${animatedDialogueRuntime.voiceSpeed === 'slow' ? '🐢' : 'Normal'}</button>
        <button class="btn btn-secondary btn-sm adm-icon-control" id="adm-repeat-btn" title="Repetir frase" aria-label="Repetir frase">↺</button>
        <button class="btn btn-secondary btn-sm adm-icon-control" id="adm-prev-btn" title="Anterior" aria-label="Anterior">⏮</button>
        <button class="btn btn-secondary btn-sm adm-icon-control" id="adm-next-btn" title="Siguiente" aria-label="Siguiente">⏭</button>
      </div>
    </div>`;
}

function attachAnimatedDialogueEvents(dialogue) {
  const admWorldId = inferModuleWorldId(dialogue);
  const admRouteId = inferModuleRouteId('', dialogue);
  bindSupportModuleNav(admWorldId, admRouteId, { mode: 'modal' });
  document.getElementById('adm-close-btn')?.addEventListener('click', closeModal);
  document.getElementById('adm-play-btn')?.addEventListener('click', () => playAnimatedDialogue(dialogue));
  document.getElementById('adm-pause-btn')?.addEventListener('click', () => pauseAnimatedDialogue());
  document.getElementById('adm-repeat-btn')?.addEventListener('click', () => repeatAnimatedDialogueLine(dialogue));
  document.getElementById('adm-prev-btn')?.addEventListener('click', () => moveAnimatedDialogueLine(dialogue, -1));
  document.getElementById('adm-next-btn')?.addEventListener('click', () => moveAnimatedDialogueLine(dialogue, 1));
  document.getElementById('adm-speed-btn')?.addEventListener('click', () => {
    animatedDialogueRuntime.voiceSpeed = animatedDialogueRuntime.voiceSpeed === 'slow' ? 'normal' : 'slow';
    localStorage.setItem('dialogueVoiceSpeed', animatedDialogueRuntime.voiceSpeed);
    renderModal();
  });
  document.querySelectorAll('[data-adm-voice]').forEach(btn => btn.addEventListener('click', () => {
    animatedDialogueRuntime.voiceMode = btn.dataset.admVoice || 'en';
    localStorage.setItem('dialogueVoiceMode', animatedDialogueRuntime.voiceMode);
    setDialogueVoiceStatus(animatedDialogueRuntime.voiceMode === 'off' ? 'Sin voz' : 'Listo');
    renderModal();
  }));
  document.querySelectorAll('[data-adm-line]').forEach(item => item.addEventListener('click', () => {
    stopAnimatedDialoguePlayback();
    animatedDialogueRuntime.lineIndex = Number(item.dataset.admLine || 0);
    saveAnimatedDialogueProgress(dialogue.id, { lastLine: animatedDialogueRuntime.lineIndex });
    renderModal();
  }));
  document.querySelectorAll('[data-real-expression-option]').forEach(btn => btn.addEventListener('click', () => {
    const correct = btn.dataset.realExpressionCorrect === 'true';
    document.querySelectorAll('[data-real-expression-option]').forEach(item => {
      item.disabled = true;
      if (item.dataset.realExpressionCorrect === 'true') item.classList.add('correct');
    });
    btn.classList.add(correct ? 'correct' : 'incorrect');
    const feedback = document.getElementById('adm-real-feedback');
    if (feedback && dialogue.realExpression) {
      feedback.className = `adm-real-feedback ${correct ? 'correct' : 'incorrect'}`;
      feedback.textContent = correct ? (dialogue.realExpression.feedbackCorrect || 'Correcto.') : (dialogue.realExpression.feedbackWrong || 'Inténtalo otra vez.');
    }
    showToast(correct ? '💬 Así se dice: correcto.' : '💬 Revisa el sentido real, no literal.', correct ? 'success' : 'neutral');
  }));
}

function openAnimatedDialogueModal(worldId, routeId = state.progress.currentRouteId) {
  const dialogue = getAnimatedDialogue(worldId, routeId);
  if (!dialogue) return showToast('Diálogo no disponible todavía.', 'neutral');
  const saved = getAnimatedDialogueProgress()[dialogue.id] || {};
  animatedDialogueRuntime.worldKey = dialogue.id;
  animatedDialogueRuntime.lineIndex = Math.min(Number(saved.lastLine || 0), Math.max(0, dialogue.lines.length - 1));
  animatedDialogueRuntime.voiceMode = localStorage.getItem('dialogueVoiceMode') || animatedDialogueRuntime.voiceMode || 'en';
  animatedDialogueRuntime.voiceSpeed = localStorage.getItem('dialogueVoiceSpeed') || animatedDialogueRuntime.voiceSpeed || 'normal';
  animatedDialogueRuntime.status = saved.completed ? 'Diálogo completado' : 'Listo';
  openModal({
    customRender: () => renderAnimatedDialogueModalBody(dialogue),
    afterRender: () => {
      attachAnimatedDialogueEvents(dialogue);
      afterDialogueLineRenderScroll();
    }
  });
}


function getRealWorldNumber(worldId) {
  const key = String(worldId || '').match(/(\d+)/);
  const n = key ? Number(key[1]) : 0;
  return Number.isFinite(n) && n >= 1 && n <= 30 ? n : 0;
}

function getA1WorldNumber(worldId) {
  return getRealWorldNumber(worldId);
}

function getRealModuleRouteId(routeId = '') {
  return routeId || ui.payload?.routeId || state.progress.currentRouteId || 'ruta_1';
}

function getRealModuleConfig(routeId = '') {
  const activeRouteId = getRealModuleRouteId(routeId);
  if (activeRouteId === 'ruta_1') return { routeId: 'ruta_1', level: 'A1', dialogues: realEnglishDialoguesA1, listening: realListeningA1 };
  if (activeRouteId === 'ruta_2') return { routeId: 'ruta_2', level: 'A2', dialogues: realEnglishDialoguesA2, listening: realListeningA2 };
  if (activeRouteId === 'ruta_3') return { routeId: 'ruta_3', level: 'B1', dialogues: realEnglishDialoguesB1, listening: realListeningB1 };
  if (activeRouteId === 'ruta_4') return { routeId: 'ruta_4', level: 'B2', dialogues: realEnglishDialoguesB2, listening: realListeningB2 };
  return null;
}

function isRealModuleAvailable(worldId, routeId = '') {
  return Boolean(getRealModuleConfig(routeId)) && Boolean(getRealWorldNumber(worldId));
}

function isA1RealModuleAvailable(worldId) {
  return isRealModuleAvailable(worldId, 'ruta_1');
}

function getRealEnglishDialogue(worldId, routeId = '') {
  const config = getRealModuleConfig(routeId);
  if (!config || !isRealModuleAvailable(worldId, config.routeId)) return null;
  const n = getRealWorldNumber(worldId);
  return config.dialogues.find(item => item.id === `REAL-${config.level}-M${n}`) || config.dialogues.find(item => item.worldId === `world_${n}`) || null;
}

function openRealEnglishModal(worldId, routeId = '') {
  const dialogue = getRealEnglishDialogue(worldId, routeId);
  if (!dialogue) return showToast('🗣️ Inglés real está disponible en A1, A2, B1 y B2.', 'neutral');
  const saved = getAnimatedDialogueProgress()[dialogue.id] || {};
  animatedDialogueRuntime.worldKey = dialogue.id;
  animatedDialogueRuntime.lineIndex = Math.min(Number(saved.lastLine || 0), Math.max(0, dialogue.lines.length - 1));
  animatedDialogueRuntime.voiceMode = localStorage.getItem('dialogueVoiceMode') || animatedDialogueRuntime.voiceMode || 'en';
  animatedDialogueRuntime.voiceSpeed = localStorage.getItem('dialogueVoiceSpeed') || animatedDialogueRuntime.voiceSpeed || 'normal';
  animatedDialogueRuntime.status = saved.completed ? 'Inglés real completado' : 'Listo';
  openModal({
    customRender: () => renderAnimatedDialogueModalBody(dialogue),
    afterRender: () => {
      attachAnimatedDialogueEvents(dialogue);
      afterDialogueLineRenderScroll();
    }
  });
}


const realListeningRuntime = {
  item: null,
  selectedIndex: null,
  checked: false,
  showTranscript: false,
  status: 'Listo'
};

function stopRealListeningPlayback() {
  if ('speechSynthesis' in window) window.speechSynthesis.cancel();
  if (typeof cancelSpeechSequence === 'function') cancelSpeechSequence();
}

const REAL_LISTENING_PROGRESS_KEY = 'realListeningProgressV1';
const REAL_LISTENING_A1_LEGACY_KEY = 'realListeningA1Progress';

function getRealListeningProgress() {
  try {
    const legacy = JSON.parse(localStorage.getItem(REAL_LISTENING_A1_LEGACY_KEY) || '{}') || {};
    const current = JSON.parse(localStorage.getItem(REAL_LISTENING_PROGRESS_KEY) || '{}') || {};
    return { ...legacy, ...current };
  } catch (error) {
    return {};
  }
}

function saveRealListeningProgress(itemId, patch = {}) {
  if (!itemId) return;
  const progress = getRealListeningProgress();
  progress[itemId] = { ...(progress[itemId] || {}), ...patch, updatedAt: new Date().toISOString() };
  localStorage.setItem(REAL_LISTENING_PROGRESS_KEY, JSON.stringify(progress));
}

function getRealListeningItem(worldId, routeId = '') {
  const config = getRealModuleConfig(routeId);
  if (!config || !isRealModuleAvailable(worldId, config.routeId)) return null;
  const n = getRealWorldNumber(worldId);
  return config.listening.find(item => item.id === `LISTEN-${config.level}-M${n}`) || config.listening.find(item => item.worldId === `world_${n}`) || null;
}

function openRealListeningModal(worldId, routeId = '') {
  const item = getRealListeningItem(worldId, routeId);
  if (!item) return showToast('🎧 Escucha real está disponible en A1, A2, B1 y B2.', 'neutral');
  realListeningRuntime.item = item;
  realListeningRuntime.selectedIndex = null;
  realListeningRuntime.checked = false;
  realListeningRuntime.showTranscript = false;
  realListeningRuntime.status = 'Escucha y elige';
  openModal({
    customRender: () => renderRealListeningModalBody(item),
    afterRender: () => attachRealListeningEvents(item)
  });
}

function renderRealListeningModalBody(item) {
  const selected = Number.isInteger(realListeningRuntime.selectedIndex) ? realListeningRuntime.selectedIndex : null;
  const checked = Boolean(realListeningRuntime.checked);
  const progress = getRealListeningProgress()[item.id] || {};
  const isCorrect = checked && selected === item.correctIndex;
  const showTranscript = Boolean(realListeningRuntime.showTranscript);
  const feedbackIcon = checked ? (isCorrect ? '🎉' : '🤔') : '';
  const feedbackTitle = checked ? (isCorrect ? 'Correcto' : 'Inténtalo otra vez') : '';
  const feedbackText = checked ? (isCorrect ? item.feedbackCorrect : item.feedbackWrong) : '';
  return `
    <div class="real-listening-modal adm-modal real-listening-modal-simple">
      ${renderSupportModuleNav(inferModuleWorldId(item), inferModuleRouteId('', item), { mode: 'modal' })}
      <div class="adm-head real-listening-head-simple">
        <div>
          <div class="section-kicker">🎧 Escucha real</div>
          <h2>${escapeHtml(item.world)} · ${escapeHtml(item.title)}</h2>
          <p class="muted" title="Escucha, elige la idea principal y recibe respuesta al instante.">Escucha, elige la idea principal y recibe respuesta al instante.</p>
        </div>
        <button class="btn btn-secondary btn-icon" id="rl-close-btn" aria-label="Cerrar Escucha real" title="Cerrar">✕</button>
      </div>

      <div class="real-listening-simple-card">
        <div class="real-listening-controls-row" aria-label="Controles de escucha">
          <button class="btn btn-primary btn-sm rl-compact-control" id="rl-play-btn" title="Escuchar el audio en inglés" aria-label="Escuchar el audio en inglés">🔊 <span>Escuchar</span></button>
          <button class="btn btn-soft btn-sm rl-compact-control" id="rl-enes-btn" title="Escuchar en inglés y español" aria-label="Escuchar en inglés y español">EN–ES</button>
          <button class="btn btn-secondary btn-sm rl-compact-control" id="rl-transcript-btn" title="${showTranscript ? 'Ocultar texto del audio' : 'Ver texto del audio'}" aria-label="${showTranscript ? 'Ocultar texto del audio' : 'Ver texto del audio'}">📄 <span>Texto</span></button>
        </div>
        ${showTranscript ? `
          <div class="real-listening-transcript real-listening-transcript-simple">
            <strong>Texto del audio</strong>
            <p class="adm-en">${escapeHtml(item.audioText)}</p>
            <p class="adm-es">${escapeHtml(item.audioTextEs || '')}</p>
          </div>` : ''}
      </div>

      <article class="real-listening-question-card real-listening-question-simple">
        <span class="section-kicker">Comprensión</span>
        <h3>¿De qué trata el audio?</h3>
        <div class="real-listening-options">
          ${(item.options || []).map((option, index) => {
            const selectedClass = selected === index ? 'selected' : '';
            const checkedClass = checked ? (index === item.correctIndex ? 'correct' : (selected === index ? 'incorrect' : '')) : '';
            return `<button type="button" class="option-btn real-listening-option ${selectedClass} ${checkedClass}" data-rl-option="${index}" ${checked && isCorrect ? 'disabled' : ''}>
              <span class="option-letter">${String.fromCharCode(65 + index)}.</span>
              <span>${escapeHtml(option)}</span>
            </button>`;
          }).join('')}
        </div>

        ${checked && !isCorrect ? `<div class="rl-feedback-panel wrong">
          <span class="rl-feedback-burst" aria-hidden="true">${feedbackIcon}</span>
          <div>
            <strong>${escapeHtml(feedbackTitle)}</strong>
            <p>${escapeHtml(feedbackText)}</p>
          </div>
        </div>` : ''}

        <div class="rl-result-actions">
          ${checked && !isCorrect ? `<button class="btn btn-primary btn-sm rl-retry-pulse" id="rl-reset-btn">↻ Reintentar</button>` : ''}
        </div>
      </article>
    </div>`;
}

function attachRealListeningEvents(item) {
  const rlWorldId = inferModuleWorldId(item);
  const rlRouteId = inferModuleRouteId('', item);
  bindSupportModuleNav(rlWorldId, rlRouteId, { mode: 'modal' });
  document.getElementById('rl-close-btn')?.addEventListener('click', closeModal);

  document.getElementById('rl-play-btn')?.addEventListener('click', () => {
    realListeningRuntime.status = 'Reproduciendo';
    speakEnglishSequence([{ en: item.audioText, es: item.audioTextEs }]);
  });

  document.getElementById('rl-enes-btn')?.addEventListener('click', () => {
    realListeningRuntime.status = 'EN–ES';
    speakBilingualSequence([{ en: item.audioText, es: item.audioTextEs }]);
  });

  document.getElementById('rl-transcript-btn')?.addEventListener('click', () => {
    realListeningRuntime.showTranscript = !realListeningRuntime.showTranscript;
    renderModal();
  });

  document.querySelectorAll('[data-rl-option]').forEach(btn => btn.addEventListener('click', () => {
    if (realListeningRuntime.checked && realListeningRuntime.selectedIndex === item.correctIndex) return;
    realListeningRuntime.selectedIndex = Number(btn.dataset.rlOption);
    realListeningRuntime.checked = true;
    const correct = realListeningRuntime.selectedIndex === item.correctIndex;
    realListeningRuntime.status = correct ? 'Correcto' : 'Reintentar';
    saveRealListeningProgress(item.id, { completed: correct, correct, selectedIndex: realListeningRuntime.selectedIndex, worldId: item.worldId });
    if (correct) showMicroFeedback('correct');
    else showToast('🤔 Revisa el audio e inténtalo otra vez.', 'neutral');
    renderModal();
  }));

  document.getElementById('rl-reset-btn')?.addEventListener('click', () => {
    realListeningRuntime.selectedIndex = null;
    realListeningRuntime.checked = false;
    realListeningRuntime.status = 'Escucha y elige';
    renderModal();
  });
}

function pauseAnimatedDialogue() {
  stopAnimatedDialoguePlayback();
  setDialogueVoiceStatus('Voz pausada');
  renderModal();
  afterDialogueLineRenderScroll();
}

function moveAnimatedDialogueLine(dialogue, direction) {
  stopAnimatedDialoguePlayback();
  const nextIndex = Math.max(0, Math.min(dialogue.lines.length - 1, animatedDialogueRuntime.lineIndex + direction));
  animatedDialogueRuntime.lineIndex = nextIndex;
  saveAnimatedDialogueProgress(dialogue.id, { lastLine: nextIndex, completed: nextIndex >= dialogue.lines.length - 1 ? true : (getAnimatedDialogueProgress()[dialogue.id]?.completed || false) });
  if (nextIndex >= dialogue.lines.length - 1) setDialogueVoiceStatus('Diálogo completado');
  renderModal();
  afterDialogueLineRenderScroll();
}

async function repeatAnimatedDialogueLine(dialogue) {
  stopAnimatedDialoguePlayback();
  animatedDialogueRuntime.token += 1;
  const token = animatedDialogueRuntime.token;
  const line = getAnimatedDialogueLine(dialogue);
  renderModal();
  afterDialogueLineRenderScroll();
  await speakCurrentAnimatedDialogueLine(line, token);
}

async function playAnimatedDialogue(dialogue) {
  if (!dialogue?.lines?.length) return;
  stopAnimatedDialoguePlayback();
  animatedDialogueRuntime.playing = true;
  animatedDialogueRuntime.token += 1;
  const token = animatedDialogueRuntime.token;
  while (animatedDialogueRuntime.playing && token === animatedDialogueRuntime.token && animatedDialogueRuntime.lineIndex < dialogue.lines.length) {
    const line = getAnimatedDialogueLine(dialogue);
    saveAnimatedDialogueProgress(dialogue.id, { lastLine: animatedDialogueRuntime.lineIndex });
    renderModal();
    afterDialogueLineRenderScroll();
    await speakCurrentAnimatedDialogueLine(line, token);
    if (!animatedDialogueRuntime.playing || token !== animatedDialogueRuntime.token) return;
    if (animatedDialogueRuntime.lineIndex >= dialogue.lines.length - 1) {
      animatedDialogueRuntime.playing = false;
      saveAnimatedDialogueProgress(dialogue.id, { completed: true, lastLine: dialogue.lines.length - 1 });
      setDialogueVoiceStatus('Diálogo completado');
      renderModal();
      afterDialogueLineRenderScroll();
      return;
    }
    animatedDialogueRuntime.lineIndex += 1;
  }
}



/* ── Constancias internas de avance ─────────────────────────── */

const CERTIFICATE_LOGO_DATA_URI = "data:image/png;base64,";
const CERTIFICATE_PARROT_DATA_URI = "data:image/png;base64,";
const CERTIFICATE_SIGNATURE_DATA_URI = "data:image/jpeg;base64,";
const CERTIFICATE_LEVELS = [
  { code: 'A1', routeId: 'ruta_1', assessmentId: FINAL_A1_ASSESSMENT_ID, title: 'A1-base', label: 'Consolidación inicial', unlocks: 'A2', focus: 'frases básicas, interacción inmediata y mundo cotidiano' },
  { code: 'A2', routeId: 'ruta_2', assessmentId: FINAL_A2_ASSESSMENT_ID, title: 'A2-base', label: 'Autonomía comunicativa básica', unlocks: 'B1', focus: 'intercambios simples sobre situaciones conocidas, vida digital, viajes, salud y compras' },
  { code: 'B1', routeId: 'ruta_3', assessmentId: FINAL_B1_ASSESSMENT_ID, title: 'B1-base', label: 'Autonomía funcional intermedia', unlocks: 'B2', focus: 'narrar experiencias, explicar problemas, opinar, decidir y sostener conversaciones funcionales' },
  { code: 'B2', routeId: 'ruta_4', assessmentId: 'final_b2_base', title: 'B2-base', label: 'Consolidación avanzada interna', unlocks: null, focus: 'mayor fluidez, argumentación, comprensión y producción comunicativa autónoma' }
];
function getCertificateLevel(levelCode = '') {
  const code = String(levelCode || '').toUpperCase().replace('-BASE', '').trim();
  return CERTIFICATE_LEVELS.find(level => level.code === code || level.title.toUpperCase() === code || level.assessmentId === levelCode) || CERTIFICATE_LEVELS[0];
}
function getCertificateExamResult(level) {
  const result = state.finalExamResults?.[level.assessmentId];
  if (result && result.passed) return result;
  const record = state.progress?.assessments?.records?.[level.assessmentId];
  if (record?.passed) {
    return { passed: true, score: record.score || record.correct || record.lastCorrect || 0, total: record.total || (level.code === 'A1' ? FINAL_A1_ITEMS : (level.code === 'B2' ? FINAL_B2_ITEMS : FINAL_ROUTE_ITEMS)), percent: record.lastScore || record.percent || 100, attempt: record.attemptsUsed || 1, completedAt: record.completedAt || new Date().toISOString(), unlocked: level.unlocks };
  }
  if (level.code === 'B2' && state.progress?.b2FinalExamPassed) {
    return { passed: true, score: 48, total: 60, percent: 80, attempt: 1, completedAt: new Date().toISOString(), unlocked: null };
  }
  return null;
}
function isCertificateAvailable(levelCode) {
  const level = getCertificateLevel(levelCode);
  return Boolean(getCertificateExamResult(level));
}
function getCertificateStats(level) {
  const expected = { worlds: 30, lessons: 150, exercises: 750, dialogues: 30, checkpoints: 6 };
  const worlds = level.routeId && level.routeId !== 'ruta_4' ? getRouteWorlds(level.routeId) : [];
  if (!worlds.length) {
    const passed = Boolean(getCertificateExamResult(level));
    return {
      worldsCompleted: passed ? expected.worlds : 0,
      worldsTotal: expected.worlds,
      lessonsCompleted: passed ? expected.lessons : 0,
      lessonsTotal: expected.lessons,
      exercisesCompleted: passed ? expected.exercises : 0,
      exercisesTotal: expected.exercises,
      dialoguesCompleted: passed ? expected.dialogues : 0,
      dialoguesTotal: expected.dialogues,
      checkpointsPassed: passed ? expected.checkpoints : 0,
      checkpointsTotal: expected.checkpoints,
      sourceNote: level.routeId === 'ruta_4' ? 'B2 aparece como estado futuro/importado de prueba cuando existe resultado final válido.' : ''
    };
  }
  const lessons = getLessonsForRoute(level.routeId);
  const lessonIds = new Set(lessons.map(lesson => lesson.id));
  const lessonsCompleted = lessons.filter(lesson => isLessonCompleted(lesson)).length;
  const exerciseIds = lessons.flatMap(lesson => lesson.exerciseIds || []);
  const exercisesCompleted = exerciseIds.filter(id => state.progress.completedExercises?.includes(id)).length;
  const dialoguesCompleted = worlds.filter(world => world.conversationCompleted).length;
  const catalog = getAssessmentCatalog(level.routeId).filter(item => item.kind !== 'final' && item.milestone !== 'final');
  const checkpointsPassed = catalog.filter(item => item.passed).length;
  return {
    worldsCompleted: worlds.filter(world => world.isConsolidated).length,
    worldsTotal: worlds.length || expected.worlds,
    lessonsCompleted,
    lessonsTotal: lessons.length || expected.lessons,
    exercisesCompleted,
    exercisesTotal: exerciseIds.length || expected.exercises,
    dialoguesCompleted,
    dialoguesTotal: worlds.length || expected.dialogues,
    checkpointsPassed,
    checkpointsTotal: catalog.length || expected.checkpoints,
    sourceNote: ''
  };
}
function formatCertificateDate(iso) {
  const date = iso ? new Date(iso) : new Date();
  if (Number.isNaN(date.getTime())) return new Date().toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' });
  return date.toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' });
}
function createCertificateCode(level, completedAt) {
  const date = completedAt ? new Date(completedAt) : new Date();
  const y = Number.isNaN(date.getTime()) ? new Date().getFullYear() : date.getFullYear();
  const m = String((Number.isNaN(date.getTime()) ? new Date() : date).getMonth() + 1).padStart(2, '0');
  const d = String((Number.isNaN(date.getTime()) ? new Date() : date).getDate()).padStart(2, '0');
  return `IPD-${level.code}-${y}${m}${d}-${String(getActiveUserName()).replace(/[^A-Za-z0-9]/g, '').slice(0, 4).toUpperCase() || 'USER'}`;
}
function buildCertificateData(levelCode) {
  const level = getCertificateLevel(levelCode);
  const result = getCertificateExamResult(level);
  const stats = getCertificateStats(level);
  return {
    level,
    result,
    stats,
    userName: getActiveUserName(),
    issuedAt: new Date().toISOString(),
    completedAt: result?.completedAt || new Date().toISOString(),
    code: createCertificateCode(level, result?.completedAt),
    available: Boolean(result)
  };
}

function renderCertificateSeal(level = {}, compact = false, standalone = false) {
  const routeLabel = compact ? 'LOGRO' : `${escapeHtml(level.code || 'EEG')} · RUTA COMPLETADA`;
  const parrotSrc = standalone ? CERTIFICATE_PARROT_DATA_URI : 'assets/images/avatar_loro_clean.png';
  return `
    <div class="certificate-app-seal ${compact ? 'compact' : ''}" role="img" aria-label="Sello digital de logro Easy English Go">
      <div class="certificate-app-seal-ring">
        <div class="certificate-app-seal-top">EASY ENGLISH GO</div>
        <div class="certificate-app-seal-core">
          <span class="certificate-app-seal-star">★</span>
          <div class="certificate-app-seal-logo">
            <img src="${parrotSrc}" alt="" onerror="this.style.display='none'; this.nextElementSibling.style.display='grid';">
            <span class="certificate-app-seal-fallback">EN</span>
          </div>
          <span class="certificate-app-seal-star">★</span>
        </div>
        <div class="certificate-app-seal-mid">Learning Achievement</div>
        <div class="certificate-app-seal-bottom">${routeLabel}</div>
      </div>
    </div>`;
}

function renderCertificateDocument(data, standalone = false) {
  const { level, result, stats } = data;
  const scoreLine = result ? `${result.score || 0}/${result.total || (level.code === 'A1' ? FINAL_A1_ITEMS : FINAL_ROUTE_ITEMS)} · ${result.percent || 100}%` : 'Pendiente';
  const brandSrc = standalone ? CERTIFICATE_LOGO_DATA_URI : 'assets/images/logo_easy_english_go.png';
  const html = `
    <section class="certificate-sheet">
      <div class="certificate-corner certificate-corner-left"></div>
      <div class="certificate-corner certificate-corner-right"></div>
      <div class="certificate-border"></div>

      <header class="certificate-header">
        <div class="certificate-header-side left">
          <span class="certificate-header-label">Constancia interna de avance</span>
          <strong class="certificate-header-value">Easy English Go</strong>
        </div>
        <div class="certificate-brand">
          <img class="certificate-brand-logo" src="${brandSrc}" alt="Easy English Go" onerror="this.style.display='none'; this.nextElementSibling.style.display='grid';" />
          <div class="certificate-brand-fallback">
            <strong>Easy English Go</strong>
            <span>Inglés para la vida real</span>
          </div>
          <small class="certificate-brand-tagline">Inglés para la vida real</small>
        </div>
        <div class="certificate-header-side right">
          <span class="certificate-header-label">Código de constancia</span>
          <strong class="certificate-header-value">${escapeHtml(data.code)}</strong>
        </div>
      </header>

      <div class="certificate-main">
        <p class="certificate-kicker">Este logro fue registrado por Easy English Go</p>
        <span class="certificate-presented">Otorgada a</span>
        <h1>${escapeHtml(data.userName)}</h1>
        <div class="certificate-divider"><span></span><i>◆</i><span></span></div>
        <p class="certificate-subtitle">Por completar satisfactoriamente</p>
        <h2>${escapeHtml(level.title)} consolidado</h2>
        <p class="certificate-level-line">${escapeHtml(level.label)} · Ruta de aprendizaje progresivo en inglés</p>
        <p class="certificate-body-text">Se deja constancia de que el usuario completó actividades, microlecciones, ejercicios, diálogos integradores, evaluaciones por hito y evaluación final interna correspondientes a este nivel.</p>
        <p class="certificate-focus"><strong>Énfasis del nivel:</strong> ${escapeHtml(level.focus)}.</p>
        <div class="certificate-stats-grid">
          <div><span>Mundos</span><strong>${stats.worldsCompleted}/${stats.worldsTotal}</strong></div>
          <div><span>Microlecciones</span><strong>${stats.lessonsCompleted}/${stats.lessonsTotal}</strong></div>
          <div><span>Ejercicios</span><strong>${stats.exercisesCompleted}/${stats.exercisesTotal}</strong></div>
          <div><span>Diálogos</span><strong>${stats.dialoguesCompleted}/${stats.dialoguesTotal}</strong></div>
          <div><span>Hitos</span><strong>${stats.checkpointsPassed}/${stats.checkpointsTotal}</strong></div>
          <div><span>Examen final</span><strong>${escapeHtml(scoreLine)}</strong></div>
        </div>
        <div class="certificate-note">Esta constancia corresponde a un registro interno de avance dentro de la aplicación y no equivale a una certificación oficial externa de dominio del idioma.</div>
        ${stats.sourceNote ? `<div class="certificate-note soft">${escapeHtml(stats.sourceNote)}</div>` : ''}
      </div>

      <footer class="certificate-signature-row">
        <div class="certificate-seal-block">
          ${renderCertificateSeal(level, false, standalone)}
          <strong>Validado por Easy English Go</strong>
          <span>Sistema interno de progreso</span>
        </div>
        <div class="certificate-date-block">
          <span>Fecha de emisión</span>
          <strong>${escapeHtml(formatCertificateDate(data.issuedAt))}</strong>
          <small>Nivel completado: ${escapeHtml(formatCertificateDate(data.completedAt))}</small>
          <small>Código: ${escapeHtml(data.code)}</small>
        </div>
      </footer>
    </section>`;
  if (!standalone) return html;
  return `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Constancia ${escapeHtml(level.title)} · Easy English Go</title><style>${getCertificatePrintCss()}</style></head><body>${html}</body></html>`;
}

function getCertificatePrintCss() {
  return `
    :root{color-scheme:light;--ink:#11172f;--muted:#657092;--line:#dfe4ff;--violet:#635cf4;--aqua:#18bfc5;--gold:#f8ad1c;--paper:#ffffff;--soft:#f7f9ff;}
    *{box-sizing:border-box}
    @page{size:A4 landscape;margin:0}
    html,body{margin:0;padding:0;background:#eef2ff;color:var(--ink);font-family:Nunito,Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;}
    body{padding:12px;display:flex;justify-content:center;align-items:flex-start;}
    .certificate-sheet{position:relative;width:min(297mm,1122px);min-height:210mm;margin:0 auto;background:linear-gradient(145deg,#fff 0%,#fbfcff 55%,#f1fffd 100%);border:1px solid var(--line);border-radius:26px;box-shadow:0 20px 70px rgba(15,23,42,.14);padding:20mm 18mm 14mm;overflow:hidden;}
    .certificate-border{position:absolute;inset:10mm;border:2px solid rgba(99,92,244,.18);border-radius:18px;pointer-events:none}
    .certificate-corner{position:absolute;z-index:0;pointer-events:none}.certificate-corner-left{left:0;top:0;width:58mm;height:32mm;background:linear-gradient(135deg,#2cc5c8 0 42%,#5f5ff0 42% 67%,#f4b227 67%)}.certificate-corner-right{right:0;bottom:0;width:46mm;height:24mm;background:linear-gradient(135deg,#f4b227 0 28%,#5f5ff0 28% 55%,#2cc5c8 55%)}
    .certificate-header{position:relative;z-index:1;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:12mm;margin-bottom:10mm}.certificate-header-side{display:grid;gap:3mm}.certificate-header-side.right{text-align:right}.certificate-header-label{font-size:3.4mm;letter-spacing:.08em;text-transform:uppercase;font-weight:900;color:#4e56d8}.certificate-header-value{font-size:5mm;color:#192042;font-weight:900;word-break:break-word}
    .certificate-brand{display:grid;justify-items:center;align-items:center;gap:2mm;min-width:78mm}.certificate-brand-logo{display:block;width:54mm;height:auto;max-height:22mm;object-fit:contain}.certificate-brand-fallback{display:none;text-align:center}.certificate-brand-fallback strong{display:block;font-size:8mm;color:#11172f}.certificate-brand-fallback span{color:#5b21b6;font-weight:900;font-size:4mm}.certificate-brand-tagline{display:block;font-size:3.1mm;color:#6b7280;font-weight:800;letter-spacing:.02em}
    .certificate-main{position:relative;z-index:1;text-align:center;max-width:245mm;margin:0 auto}.certificate-kicker{margin:0 0 3mm;color:#4e56d8;font-weight:900;text-transform:uppercase;letter-spacing:.12em;font-size:3.1mm}.certificate-presented{display:block;margin:0 0 1.5mm;color:#5b6178;font-weight:800;font-size:4.2mm}.certificate-main h1{font-family:Georgia,"Times New Roman",serif;font-size:13.5mm;line-height:1.02;margin:0;color:#11172f}.certificate-divider{display:flex;align-items:center;justify-content:center;gap:3mm;width:min(150mm,88%);margin:3mm auto;color:var(--violet)}.certificate-divider span{height:.3mm;flex:1;background:linear-gradient(90deg,transparent,rgba(99,92,244,.55),transparent)}.certificate-divider i{font-style:normal;font-size:2.6mm}.certificate-subtitle{font-size:4.2mm;color:#3b415c;font-weight:750;margin:3mm 0 1.5mm}.certificate-main h2{margin:0;color:#5b35d5;font-size:8.2mm;font-weight:950}.certificate-level-line{font-size:4mm;color:var(--muted);font-weight:750;margin:2mm 0 0}.certificate-body-text,.certificate-focus{font-size:3.7mm;line-height:1.45;color:#27304f;max-width:220mm;margin:3.2mm auto 0}
    .certificate-stats-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:2.6mm;margin:5mm auto 4mm;max-width:245mm}.certificate-stats-grid div{background:rgba(255,255,255,.92);border:1px solid var(--line);border-radius:4mm;padding:3mm 2.2mm}.certificate-stats-grid span{display:block;color:var(--muted);font-weight:850;font-size:2.9mm}.certificate-stats-grid strong{font-size:4mm}.certificate-note{max-width:225mm;margin:2.4mm auto 0;padding:2.6mm 3.2mm;border-radius:4mm;background:#f6f7ff;border:1px solid var(--line);color:#59617f;font-size:3mm}.certificate-note.soft{background:#eefcf9}
    .certificate-signature-row{display:flex;justify-content:space-between;align-items:flex-end;gap:10mm;position:relative;z-index:1;margin-top:6mm}.certificate-seal-block{width:min(82mm,42%);text-align:center;display:grid;justify-items:center;gap:1.2mm}.certificate-seal-block strong,.certificate-date-block strong{display:block;font-size:4mm}.certificate-seal-block span,.certificate-date-block span,.certificate-date-block small{display:block;color:var(--muted);font-size:3.1mm}.certificate-date-block{text-align:right;background:rgba(255,255,255,.82);border:1px solid var(--line);border-radius:5mm;padding:4mm 4.4mm;min-width:70mm}
    .certificate-app-seal{width:32mm;height:32mm;border-radius:50%;display:grid;place-items:center;background:radial-gradient(circle at 50% 45%,#fff 0 52%,rgba(24,191,197,.10) 53% 70%,rgba(99,92,244,.12) 71%);border:1.1mm solid #6d36df;box-shadow:0 2mm 5mm rgba(99,92,244,.16)}.certificate-app-seal.compact{width:28mm;height:28mm}.certificate-app-seal-ring{width:27.5mm;height:27.5mm;border:.7mm solid #18bfc5;border-radius:50%;position:relative;display:grid;place-items:center;background:rgba(255,255,255,.9)}.certificate-app-seal.compact .certificate-app-seal-ring{width:24mm;height:24mm}.certificate-app-seal-top,.certificate-app-seal-bottom{position:absolute;left:50%;transform:translateX(-50%);font-weight:950;text-align:center;white-space:nowrap}.certificate-app-seal-top{top:2.2mm;color:#0fb5bc;font-size:1.55mm;letter-spacing:.08em}.certificate-app-seal-bottom{bottom:1.9mm;color:#6334d8;font-size:1.25mm;letter-spacing:.04em}.certificate-app-seal-mid{position:absolute;bottom:5.7mm;font-size:1.05mm;font-weight:900;color:#1e2543;white-space:nowrap}.certificate-app-seal-core{display:flex;align-items:center;justify-content:center;gap:1.4mm}.certificate-app-seal-star{color:#f8ad1c;font-size:2.7mm}.certificate-app-seal-logo{width:11mm;height:11mm;border-radius:4mm;display:grid;place-items:center}.certificate-app-seal-logo img{width:12mm;height:12mm;object-fit:contain}.certificate-app-seal-fallback{display:none;width:10mm;height:10mm;border-radius:4mm;place-items:center;background:#eefcff;color:#5b35d5;font-weight:950;font-size:3mm}
    @media (max-width:1100px){body{padding:10px}.certificate-sheet{width:min(100%,1122px);min-height:auto;padding:28px 24px 22px}.certificate-header{grid-template-columns:1fr;gap:14px}.certificate-header-side,.certificate-header-side.right{text-align:center}.certificate-brand-logo{width:min(300px,70vw);max-height:none}.certificate-main h1{font-size:52px}.certificate-main h2{font-size:32px}.certificate-stats-grid{grid-template-columns:repeat(2,1fr)}.certificate-signature-row{flex-direction:column;align-items:center}.certificate-seal-block{width:100%}.certificate-date-block{text-align:center;min-width:0;width:100%}}
    @media print{html,body{background:#fff;height:100%}body{padding:0}.certificate-sheet{width:297mm;min-height:210mm;box-shadow:none;border-radius:0;border:0}.certificate-border{inset:8mm}.no-print{display:none!important}}
  `;
}

function downloadCertificateHtml(levelCode) {
  const data = buildCertificateData(levelCode);
  if (!data.available) return showToast('Constancia aún no disponible.', 'warning');
  const html = renderCertificateDocument(data, true);
  const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = `constancia_${data.level.title.replace(/[^A-Za-z0-9]+/g, '_')}_${data.code}.html`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 250);
  showToast('Constancia HTML descargada.', 'success');
}
function printCertificatePdf(levelCode) {
  const data = buildCertificateData(levelCode);
  if (!data.available) return showToast('Constancia aún no disponible.', 'warning');
  const win = window.open('', '_blank', 'noopener,noreferrer');
  if (!win) return showToast('Permite ventanas emergentes para generar PDF.', 'warning');
  win.document.open();
  win.document.write(renderCertificateDocument(data, true).replace('</body>', '<div class="no-print" style="position:fixed;right:18px;bottom:18px;background:#11172f;color:white;border-radius:999px;padding:10px 14px;font-weight:900;box-shadow:0 10px 30px rgba(0,0,0,.22)">Usa “Guardar como PDF” en la ventana de impresión.</div></body>'));
  win.document.close();
  win.focus();
  setTimeout(() => win.print(), 350);
}
function openCertificateModal(levelCode) {
  const data = buildCertificateData(levelCode);
  if (!data.available) return showToast('Constancia aún no disponible.', 'warning');
  ui.modal = {
    customRender: () => `
      <div class="modal-shell certificate-modal-shell">
        <div class="certificate-modal-card">
          <button class="dialogue-close" id="certificate-close-modal" aria-label="Cerrar">✕</button>
          ${renderCertificateDocument(data, false)}
          <div class="certificate-modal-actions no-print">
            <button class="btn btn-primary" id="certificate-download-html">Descargar HTML</button>
            <button class="btn btn-secondary" id="certificate-download-pdf">Descargar PDF</button>
            <button class="btn btn-soft" id="certificate-modal-back">Cerrar</button>
          </div>
        </div>
      </div>`,
    afterRender: () => {
      document.getElementById('certificate-close-modal')?.addEventListener('click', closeModal);
      document.getElementById('certificate-modal-back')?.addEventListener('click', closeModal);
      document.getElementById('certificate-download-html')?.addEventListener('click', () => downloadCertificateHtml(levelCode));
      document.getElementById('certificate-download-pdf')?.addEventListener('click', () => printCertificatePdf(levelCode));
    }
  };
  renderModal();
}
function renderCertificates() {
  const rows = CERTIFICATE_LEVELS.map(level => {
    const data = buildCertificateData(level.code);
    const result = data.result;
    const stats = data.stats;
    return `
      <article class="certificate-level-card ${data.available ? 'available' : 'locked'}">
        <div>
          <div class="section-kicker">${data.available ? 'Constancia disponible' : 'Pendiente'}</div>
          <h2>${escapeHtml(level.title)}</h2>
          <p class="muted">${escapeHtml(level.label)} · ${escapeHtml(level.focus)}.</p>
          <div class="chip-row spacer-top">
            <span class="chip compact-stat">${data.available ? '✅ Nivel consolidado' : '🔒 Examen final pendiente'}</span>
            <span class="chip compact-stat">${stats.worldsCompleted}/${stats.worldsTotal} mundos</span>
            <span class="chip compact-stat">${result ? `${result.score || 0}/${result.total || 45} · ${result.percent || 100}%` : 'Sin resultado final'}</span>
          </div>
        </div>
        <div class="button-row wrap-row certificate-card-actions">
          <button class="btn btn-primary btn-small" data-cert-preview="${escapeHtml(level.code)}" ${data.available ? '' : 'disabled'}>Ver constancia</button>
          <button class="btn btn-secondary btn-small" data-cert-html="${escapeHtml(level.code)}" ${data.available ? '' : 'disabled'}>HTML</button>
          <button class="btn btn-soft btn-small" data-cert-pdf="${escapeHtml(level.code)}" ${data.available ? '' : 'disabled'}>PDF</button>
        </div>
      </article>`;
  }).join('');
  $main.innerHTML = `
    <section class="view-grid certificate-view">
      <article class="status-card certificate-hero-card">
        <div>
          <span class="section-kicker">🎓 Constancias</span>
          <h1>Constancias internas de avance</h1>
          <p class="muted">Descarga reconocimientos simbólicos por cada etapa consolidada. Son registros internos de la app, no certificaciones oficiales externas.</p>
        </div>
        <div class="certificate-signature-mini certificate-seal-mini">${renderCertificateSeal({ code: 'EEG' }, true)}<span>Sello digital de logro</span></div>
      </article>
      <div class="certificate-level-list">${rows}</div>
    </section>`;
  document.querySelectorAll('[data-cert-preview]').forEach(btn => btn.addEventListener('click', () => openCertificateModal(btn.dataset.certPreview)));
  document.querySelectorAll('[data-cert-html]').forEach(btn => btn.addEventListener('click', () => downloadCertificateHtml(btn.dataset.certHtml)));
  document.querySelectorAll('[data-cert-pdf]').forEach(btn => btn.addEventListener('click', () => printCertificatePdf(btn.dataset.certPdf)));
}
/* ── /Constancias internas de avance ────────────────────────── */


