function renderAmbientBackground() {
  // Determinar tema según vista y mundo activo
  let theme;
  const view = ui.view;
  const worldId = ui.payload?.worldId || ui.payload?.openWorldId;

  if (worldId && AMBIENT_THEMES[worldId]) {
    theme = AMBIENT_THEMES[worldId];
  } else if (AMBIENT_THEMES[view]) {
    theme = AMBIENT_THEMES[view];
  } else {
    theme = AMBIENT_THEMES.route;
  }

  // Contenedor principal
  const $shell = document.getElementById('app-shell') || document.getElementById('app-main');
  if (!$shell) return;

  // Reusar o crear el canvas de fondo
  let $bg = document.getElementById('ipd-ambient-bg');
  if (!$bg) {
    $bg = document.createElement('div');
    $bg.id = 'ipd-ambient-bg';
    $bg.setAttribute('aria-hidden', 'true');
    $bg.style.cssText = `
      position:fixed; inset:0; pointer-events:none; z-index:0;
      overflow:hidden; user-select:none;
    `;
    document.body.insertBefore($bg, document.body.firstChild);
  }

  // Limpiar
  $bg.innerHTML = '';

  const W = window.innerWidth;
  const H = window.innerHeight;

  // Generar entre 6 y 10 símbolos distribuidos aleatoriamente
  // pero con posiciones fijas por tema (seeded) para que no salten en re-renders
  const count = 14;
  const emojis = theme.emojis;

  // Posiciones semideterministas: usamos el índice y el tema como semilla
  const seed = (str) => str.split('').reduce((a, c) => a + c.charCodeAt(0), 0);
  const themeKey = worldId || view || 'route';
  const s = seed(themeKey);

  function pseudo(index, offset) {
    return ((s * (index + 1) * 7919 + offset * 3571) % 1000) / 1000;
  }

  for (let i = 0; i < count; i++) {
    const emoji = emojis[i % emojis.length];
    const x = pseudo(i, 1) * 90 + 5; // 5% … 95%
    const y = pseudo(i, 2) * 85 + 5; // 5% … 90%
    const size = 24 + pseudo(i, 3) * 28; // 24px … 52px
    const opacity = 0.05 + pseudo(i, 4) * 0.07; // 5% … 12%
    const rotate = (pseudo(i, 5) - 0.5) * 40; // -20° … +20°

    const el = document.createElement('span');
    el.textContent = emoji;
    el.style.cssText = `
      position:absolute;
      left:${x}%;
      top:${y}%;
      font-size:${size}px;
      opacity:${opacity.toFixed(3)};
      transform:rotate(${rotate.toFixed(1)}deg);
      transition:opacity 0.8s ease;
      filter:grayscale(15%) blur(0.4px);
      line-height:1;
    `;
    $bg.appendChild(el);
  }
}

