// ── v5.0.51 · Centro de refuerzo / afianzamiento ───────────────────────────
const REINFORCEMENT_WORLD_TOOL_PROGRESS_KEY = 'worldToolProgressV1';

function getReinforcementToolProgress() {
  try { return JSON.parse(localStorage.getItem(REINFORCEMENT_WORLD_TOOL_PROGRESS_KEY) || '{}') || {}; }
  catch (error) { return {}; }
}

function saveReinforcementToolProgress(worldId, toolKey, patch = {}) {
  if (!worldId || !toolKey) return;
  const progress = getReinforcementToolProgress();
  const key = `${worldId}::${toolKey}`;
  progress[key] = { ...(progress[key] || {}), completed: true, worldId, toolKey, updatedAt: new Date().toISOString(), ...patch };
  localStorage.setItem(REINFORCEMENT_WORLD_TOOL_PROGRESS_KEY, JSON.stringify(progress));
}

function isReinforcementToolDone(worldId, toolKey) {
  return Boolean(getReinforcementToolProgress()[`${worldId}::${toolKey}`]?.completed);
}

function markReinforcementToolDone(worldId, toolKey, sourceBtn = null) {
  if (!worldId || !toolKey) return;
  saveReinforcementToolProgress(worldId, toolKey);
  document.querySelectorAll('[data-rc-tool]').forEach(btn => {
    if (btn.dataset.worldId === worldId && btn.dataset.rcTool === toolKey) btn.classList.add('tool-done');
  });
  sourceBtn?.classList?.add('tool-done');
}

function getWorldReinforcementPendingCount(worldId) {
  return getPendingConversationReinforcement(worldId).length;
}

function getRouteReinforcementPendingCount(routeId) {
  return getRouteWorlds(routeId).reduce((total, world) => total + getWorldReinforcementPendingCount(world.id), 0);
}

function getSelectedReinforcementWorld(routeId, worldId = '') {
  const worlds = getRouteWorlds(routeId);
  return worlds.find(world => world.id === worldId)
    || getCurrentWorld(routeId)
    || worlds[0]
    || null;
}

function getReinforcementResourceList(world) {
  if (!world) return [];
  const routeId = world.routeId || state.progress.currentRouteId || 'ruta_1';
  const pending = getWorldReinforcementPendingCount(world.id);
  const gameLessonId = getWorldGameLessonId(world);
  return [
    {
      key: 'reinforcement',
      icon: '🔁',
      title: 'Refuerzo guiado',
      subtitle: pending ? 'Corrige pendientes detectados.' : 'Sin pendientes por ahora.',
      badge: pending,
      enabled: pending > 0,
      className: 'rc-open-reinforcement'
    },
    {
      key: 'animated',
      icon: '💬',
      title: 'Diálogo animado',
      subtitle: 'Repasa la escena del mundo.',
      enabled: Boolean(getAnimatedDialogue(world.id, routeId)),
      className: 'rc-open-animated'
    },
    {
      key: 'realEnglish',
      icon: '🗣️',
      title: 'Inglés real',
      subtitle: 'Expresiones naturales en contexto.',
      enabled: Boolean(getRealEnglishDialogue(world.id, routeId)),
      className: 'rc-open-real-english'
    },
    {
      key: 'realListening',
      icon: '🎧',
      title: 'Escucha real',
      subtitle: 'Entrena comprensión auditiva.',
      enabled: Boolean(getRealListeningItem(world.id, routeId)),
      className: 'rc-open-real-listening'
    },
    {
      key: 'video',
      icon: '🎥',
      title: 'Video de apoyo',
      subtitle: 'Refuerzo audiovisual externo.',
      enabled: Boolean(getVideosByWorld(world.id).length),
      className: 'rc-open-video'
    },
    {
      key: 'music',
      icon: getMusicVideoIcon(),
      title: 'Canción subtitulada',
      subtitle: 'Ritmo, vocabulario y subtítulos.',
      enabled: Boolean(getMusicVideosByWorld(world.id, routeId).length),
      className: 'rc-open-music'
    },
    {
      key: 'translation',
      icon: '📝',
      title: 'Traducción',
      subtitle: 'Conecta sentido entre ES y EN.',
      enabled: true,
      className: 'rc-open-translation'
    },
    {
      key: 'game',
      icon: '🎮',
      title: 'Juegos rápidos',
      subtitle: 'Sopa, parejas, memoria y ruta.',
      enabled: Boolean(gameLessonId),
      className: 'rc-open-game',
      lessonId: gameLessonId || ''
    }
  ];
}

function getReinforcementWorldContextSummary(routeId, world) {
  const level = String(getRouteShortCode(routeId) || '').toUpperCase();
  const byLevel = {
    A1: 'Bases funcionales para hablar, escuchar y responder con seguridad en situaciones cotidianas.',
    A2: 'Rutinas, desplazamientos y vida diaria para ganar más autonomía comunicativa.',
    B1: 'Interacciones funcionales con más claridad, intención y comprensión del contexto.',
    B2: 'Matices, argumentación y fluidez para contextos más complejos y reales.'
  };
  if (!world) return byLevel[level] || 'Refuerza este mundo con recursos breves y directos.';
  return byLevel[level] || `Refuerza ${cleanBusWorldTitle(world.title || 'este mundo')} con recursos breves y directos.`;
}

function renderReinforcementCenter() {
  const requestedRouteId = ui.payload?.routeId || state.progress.currentRouteId || 'ruta_1';
  const routeId = getRouteById(requestedRouteId) ? requestedRouteId : 'ruta_1';
  const route = getRouteById(routeId);
  const worlds = getRouteWorlds(routeId);
  const selectedWorld = getSelectedReinforcementWorld(routeId, ui.payload?.worldId || '');
  const selectedPending = selectedWorld ? getWorldReinforcementPendingCount(selectedWorld.id) : 0;
  const selectedWorldLabel = selectedWorld ? `M${selectedWorld.index + 1} · ${cleanBusWorldTitle(selectedWorld.title)}` : 'Selecciona un mundo';
  const normalizedOpenWorldIds = (() => {
    const raw = ui.payload?.openWorldIds;
    const arr = Array.isArray(raw) ? raw : typeof raw === 'string' ? raw.split(',') : [];
    const ids = arr.map(item => String(item || '').trim()).filter(Boolean).filter(id => worlds.some(world => world.id === id));
    if (ids.length) return Array.from(new Set(ids));
    return selectedWorld?.id ? [selectedWorld.id] : [];
  })();
  const routeCompletedCount = worlds.filter(world => Number(world.consolidatedPercent || 0) >= 100 || world.isConsolidated || world.status === 'completed').length;
  const routePendingCount = getRouteReinforcementPendingCount(routeId);
  const routeProgressLabel = `${routeCompletedCount}/${worlds.length} consolidados`;
  const currentPlaylist = getLevelPlaylist(routeId);
  const openWorldIdSet = new Set(normalizedOpenWorldIds);

  const groupDefinitions = [
    { key: 'fundamentos', label: 'Fundamentos', range: 'M1–M10', worlds: worlds.slice(0, 10) },
    { key: 'desarrollo', label: 'Desarrollo', range: 'M11–M20', worlds: worlds.slice(10, 20) },
    { key: 'dominio', label: 'Dominio', range: 'M21–M30', worlds: worlds.slice(20, 30) }
  ].filter(group => group.worlds.length);

  const routeTabs = ['ruta_1', 'ruta_2', 'ruta_3', 'ruta_4']
    .map(id => {
      const label = getRouteShortCode(id);
      const total = getRouteReinforcementPendingCount(id);
      return `<button type="button" class="rc-route-tab ${id === routeId ? 'active' : ''}" data-rc-route-id="${id}">
        <span>${escapeHtml(label)}</span>${total ? `<b>${total}</b>` : ''}
      </button>`;
    }).join('');

  function renderWorldCard(world) {
    const pending = getWorldReinforcementPendingCount(world.id);
    const active = selectedWorld && world.id === selectedWorld.id;
    const title = cleanBusWorldTitle(world.title || `M${world.index + 1}`);
    const percent = Number(world.consolidatedPercent || 0);
    const statusText = pending
      ? `${pending} pendiente${pending === 1 ? '' : 's'}`
      : percent >= 100
        ? '100% consolidado'
        : `${percent}% consolidado`;
    return `<button type="button" class="rc-world-card ${active ? 'active' : ''} ${pending ? 'pending' : ''} ${world.status || ''}" data-rc-world-id="${world.id}" title="M${world.index + 1} · ${escapeHtml(title)}">
      <span class="rc-world-number">${pending ? `M${world.index + 1}` : '✓'}</span>
      <strong>${escapeHtml(`M${world.index + 1} · ${title}`)}</strong>
      <small>${escapeHtml(statusText)}</small>
      ${pending ? `<em>${pending}</em>` : ''}
    </button>`;
  }

  const worldCards = groupDefinitions.map(group => `
    <div class="rc-world-group rc-world-group-${group.key}">
      <div class="rc-world-group-label"><span>${escapeHtml(group.label)}</span><small>${escapeHtml(group.range)}</small></div>
      ${group.worlds.map(renderWorldCard).join('')}
    </div>`).join('');

  function getResourceMicroLabel(key, title = '') {
    return ({
      reinforcement: 'Refuerzo',
      animated: 'Diálogo',
      realEnglish: 'Inglés',
      realListening: 'Escucha',
      video: 'Video',
      music: 'Canción',
      translation: 'Traducción',
      game: 'Juegos'
    })[key] || title;
  }

  function renderResourceButton(item, world, compact = false) {
    const done = world ? isReinforcementToolDone(world.id, item.key) : false;
    const disabled = !item.enabled;
    const action = item.enabled ? 'Abrir' : 'No disponible';
    const microLabel = getResourceMicroLabel(item.key, item.title);
    const tooltip = `${item.title}. ${item.subtitle}`;
    const modeClass = compact ? 'rc-resource-chip rc-resource-chip-mobile' : 'rc-resource-chip rc-resource-chip-desktop';
    return `<button type="button" class="${modeClass} ${disabled ? 'disabled' : ''} ${done ? 'tool-done' : ''} ${item.className}" 
      data-world-id="${world?.id || ''}" data-route-id="${routeId}" data-rc-tool="${item.key}" data-lesson-id="${item.lessonId || ''}" data-tooltip="${escapeHtml(tooltip)}" title="${escapeHtml(tooltip)}" aria-label="${escapeHtml(tooltip)}" ${item.enabled ? '' : 'disabled'}>
      <span class="rc-resource-chip-icon">${item.icon}${item.badge ? `<b>${item.badge}</b>` : ''}</span>
      <span class="rc-resource-chip-label">${escapeHtml(microLabel)}</span>
      <span class="rc-resource-chip-status">${action}</span>
    </button>`;
  }

  const selectedResources = selectedWorld ? getReinforcementResourceList(selectedWorld) : [];
  const resourceCards = selectedResources.map(item => renderResourceButton(item, selectedWorld, false)).join('');
  const selectedLessonTitles = selectedWorld ? (selectedWorld.lessons || []).map(lesson => cleanBusWorldTitle(lesson.title || '')).filter(Boolean).slice(0, 6) : [];
  const contextualSummary = getReinforcementWorldContextSummary(routeId, selectedWorld);
  const enabledResourceCount = selectedResources.filter(item => item.enabled).length;
  const desktopWorldContext = selectedWorld ? `
    <div class="rc-world-context">
      <div class="rc-world-context-copy">
        <div class="rc-world-context-head">
          <span class="section-kicker">Panorama del mundo</span>
          <h3>${escapeHtml(cleanBusWorldTitle(selectedWorld.title || 'Mundo'))}</h3>
          <p>${escapeHtml(contextualSummary)}</p>
        </div>
        <div class="rc-world-context-stats">
          <span><b>${selectedLessonTitles.length || 0}</b><small>lecciones</small></span>
          <span><b>${enabledResourceCount}</b><small>recursos</small></span>
          <span><b>${selectedPending}</b><small>${selectedPending === 1 ? 'pendiente' : 'pendientes'}</small></span>
        </div>
        <div class="rc-world-context-lessons">${selectedLessonTitles.map((title, idx) => `<span class="rc-world-lesson-chip">${escapeHtml(`L${idx + 1} · ${title}`)}</span>`).join('')}</div>
      </div>
      <div class="rc-world-context-scene">${renderWorldThemeScene(selectedWorld, routeId, 'world')}</div>
    </div>` : '';

  const mobileAccordion = groupDefinitions.map(group => `
    <div class="rc-mobile-group rc-mobile-group-${group.key}">
      <div class="rc-mobile-group-label">${escapeHtml(group.label)} <small>${escapeHtml(group.range)}</small></div>
      ${group.worlds.map(world => {
        const pending = getWorldReinforcementPendingCount(world.id);
        const active = selectedWorld && world.id === selectedWorld.id;
        const open = openWorldIdSet.has(world.id);
        const title = cleanBusWorldTitle(world.title || `M${world.index + 1}`);
        const percent = Number(world.consolidatedPercent || 0);
        const statusText = pending
          ? `${pending} pendiente${pending === 1 ? '' : 's'}`
          : percent >= 100
            ? '100% consolidado'
            : `${percent}% consolidado`;
        const resources = getReinforcementResourceList(world).map(item => renderResourceButton(item, world, true)).join('');
        return `<article class="rc-mobile-acc-item ${active ? 'active' : ''} ${open ? 'open' : ''} ${pending ? 'pending' : ''} ${world.status || ''}" data-rc-world-id="${world.id}">
          <button type="button" class="rc-mobile-acc-head" data-rc-world-id="${world.id}" aria-expanded="${open ? 'true' : 'false'}">
            <span class="rc-mobile-world-badge">${pending ? `M${world.index + 1}` : '✓'}</span>
            <span class="rc-mobile-world-copy"><strong>${escapeHtml(`M${world.index + 1} · ${title}`)}</strong><small>${escapeHtml(statusText)}</small></span>
            <span class="rc-mobile-acc-chevron" aria-hidden="true">⌄</span>
          </button>
          <div class="rc-mobile-acc-body">
            <div class="rc-mobile-acc-inner">
              <p>${pending ? `Tienes ${pending} refuerzo${pending === 1 ? '' : 's'} sugerido${pending === 1 ? '' : 's'} en este bloque.` : 'Sin pendientes: puedes practicar libremente.'}</p>
              <div class="rc-mobile-resource-list">${resources}</div>
            </div>
          </div>
        </article>`;
      }).join('')}
    </div>`).join('');

  $main.innerHTML = `
    <section class="reinforcement-center-screen route-visual-shell route-level-${String(getRouteShortCode(routeId) || 'A1').toLowerCase()}" aria-label="Centro de refuerzo">
      <div class="reinforcement-center-card card panel">
        <div class="rc-header rc-header-compact">
          <button type="button" class="floating-nav-btn rc-back-btn" id="rc-back-to-world" title="Volver a la parada" aria-label="Volver a la parada">←</button>
          <div class="rc-header-main">
            <span class="section-kicker">🔁 Centro de refuerzo</span>
            <h2>Explora recursos del mundo</h2>
            <div class="rc-header-meta" aria-label="Resumen del mundo actual">
              <span>${escapeHtml(route?.title || 'Ruta')}</span>
              <span>${escapeHtml(selectedWorldLabel)}</span>
              <span>${escapeHtml(routeProgressLabel)}</span>
            </div>
          </div>
        </div>

        <div class="rc-route-tabs" aria-label="Rutas disponibles">${routeTabs}</div>

        <article class="rc-level-playlist-card rc-level-playlist-card-compact" aria-label="Playlist de canciones subtituladas del nivel">
          <div class="rc-level-playlist-icon">${getMusicVideoIcon()}</div>
          <div class="rc-level-playlist-copy">
            <strong>${escapeHtml(`Canciones subtituladas · ${currentPlaylist.level}`)}</strong>
            <small>Playlist del nivel</small>
            <div class="rc-level-playlist-actions">
              <button type="button" class="btn btn-primary btn-sm open-level-playlist-btn rc-level-playlist-open" data-route-id="${routeId}" title="Abrir playlist ${escapeHtml(currentPlaylist.level)} en YouTube">▶ Playlist</button>
            </div>
          </div>
        </article>

        <div class="rc-mobile-accordion" id="rc-mobile-accordion" aria-label="Mundos y recursos de refuerzo en móvil">${mobileAccordion}</div>

        <div class="rc-layout">
          <aside class="rc-worlds-panel" aria-label="Mundos de la ruta">
            <div class="rc-panel-head">
              <strong>${escapeHtml(getRouteShortCode(routeId))} · ${worlds.length} mundos</strong>
              <small>${escapeHtml(routeProgressLabel)}${routePendingCount ? ` · ${routePendingCount} pendiente${routePendingCount === 1 ? '' : 's'}` : ''}</small>
            </div>
            <div class="rc-world-grid rc-world-grid-grouped" id="rc-world-grid">${worldCards}</div>
          </aside>

          <section class="rc-resources-panel" aria-label="Recursos del mundo">
            <div class="rc-panel-head">
              <strong>${selectedWorld ? `M${selectedWorld.index + 1} · ${escapeHtml(cleanBusWorldTitle(selectedWorld.title))}` : 'Mundo'}</strong>
              <small>${selectedPending ? `${selectedPending} pendiente${selectedPending === 1 ? '' : 's'} sugerido${selectedPending === 1 ? '' : 's'}` : 'Práctica libre disponible'}</small>
            </div>
            <div class="rc-resource-grid">${resourceCards}</div>
            ${desktopWorldContext}
          </section>
        </div>
      </div>
    </section>`;

  bindReinforcementCenterEvents(routeId, selectedWorld);
}

function bindReinforcementCenterEvents(routeId, selectedWorld) {
  const announceResourceHint = (btn) => {
    const text = btn?.dataset?.tooltip || '';
    if (!text) return;
    const existing = document.querySelector('.rc-floating-hint');
    if (existing) existing.remove();
    const hint = document.createElement('div');
    hint.className = 'rc-floating-hint';
    hint.textContent = text;
    document.body.appendChild(hint);
    window.setTimeout(() => hint.remove(), 1150);
  };
  document.getElementById('rc-back-to-world')?.addEventListener('click', () => {
    setView('route', { routeId, worldId: selectedWorld?.id || null });
  });

  document.querySelectorAll('.open-level-playlist-btn').forEach(btn => btn.addEventListener('click', () => openLevelPlaylist(btn.dataset.routeId || routeId)));

  document.querySelectorAll('.rc-route-tab').forEach(btn => btn.addEventListener('click', () => {
    const nextRouteId = btn.dataset.rcRouteId || routeId;
    const nextWorld = getSelectedReinforcementWorld(nextRouteId, '');
    setView('reinforcement_center', { routeId: nextRouteId, worldId: nextWorld?.id || null, openWorldIds: nextWorld?.id ? [nextWorld.id] : [] });
  }));

  document.querySelectorAll('.rc-world-card').forEach(btn => btn.addEventListener('click', () => {
    const worldId = btn.dataset.rcWorldId;
    if (!worldId) return;
    const rawOpen = ui.payload?.openWorldIds;
    const currentOpen = Array.isArray(rawOpen) ? rawOpen : typeof rawOpen === 'string' ? rawOpen.split(',').filter(Boolean) : [];
    const openWorldIds = Array.from(new Set([...currentOpen, worldId]));
    setView('reinforcement_center', { routeId, worldId, openWorldIds });
  }));

  document.querySelectorAll('.rc-mobile-acc-head').forEach(btn => btn.addEventListener('click', () => {
    const worldId = btn.dataset.rcWorldId;
    if (!worldId) return;
    const raw = ui.payload?.openWorldIds;
    const currentOpen = Array.isArray(raw) ? raw.slice() : typeof raw === 'string' ? raw.split(',').filter(Boolean) : (selectedWorld?.id ? [selectedWorld.id] : []);
    const exists = currentOpen.includes(worldId);
    const nextOpen = exists ? currentOpen.filter(id => id !== worldId) : [...currentOpen, worldId];
    setView('reinforcement_center', { routeId, worldId, openWorldIds: Array.from(new Set(nextOpen)) });
  }));

  document.querySelectorAll('.rc-open-reinforcement').forEach(btn => btn.addEventListener('click', () => {
    announceResourceHint(btn);
    markReinforcementToolDone(btn.dataset.worldId, 'reinforcement', btn);
    startConversationReinforcement(btn.dataset.worldId);
  }));

  document.querySelectorAll('.rc-open-animated').forEach(btn => btn.addEventListener('click', () => {
    announceResourceHint(btn);
    markReinforcementToolDone(btn.dataset.worldId, 'animated', btn);
    openAnimatedDialogueModal(btn.dataset.worldId, btn.dataset.routeId || routeId);
  }));

  document.querySelectorAll('.rc-open-real-english').forEach(btn => btn.addEventListener('click', () => {
    announceResourceHint(btn);
    markReinforcementToolDone(btn.dataset.worldId, 'realEnglish', btn);
    openRealEnglishModal(btn.dataset.worldId, btn.dataset.routeId);
  }));

  document.querySelectorAll('.rc-open-real-listening').forEach(btn => btn.addEventListener('click', () => {
    announceResourceHint(btn);
    markReinforcementToolDone(btn.dataset.worldId, 'realListening', btn);
    openRealListeningModal(btn.dataset.worldId, btn.dataset.routeId);
  }));

  document.querySelectorAll('.rc-open-video').forEach(btn => btn.addEventListener('click', () => {
    announceResourceHint(btn);
    markReinforcementToolDone(btn.dataset.worldId, 'video', btn);
    openWorldVideoModal(btn.dataset.worldId, btn.dataset.routeId || routeId || state.progress.currentRouteId);
  }));

  document.querySelectorAll('.rc-open-music').forEach(btn => btn.addEventListener('click', () => {
    announceResourceHint(btn);
    markReinforcementToolDone(btn.dataset.worldId, 'music', btn);
    openWorldMusicVideoModal(btn.dataset.worldId, btn.dataset.routeId);
  }));

  document.querySelectorAll('.rc-open-translation').forEach(btn => btn.addEventListener('click', () => {
    announceResourceHint(btn);
    markReinforcementToolDone(btn.dataset.worldId, 'translation', btn);
    setView('translation', { routeId, worldId: btn.dataset.worldId, returnTo: { view: 'reinforcement_center', payload: { routeId, worldId: btn.dataset.worldId, openWorldIds: [btn.dataset.worldId] } } });
  }));

  document.querySelectorAll('.rc-open-game').forEach(btn => btn.addEventListener('click', () => {
    announceResourceHint(btn);
    markReinforcementToolDone(btn.dataset.worldId, 'game', btn);
    setView('game', { lessonId: btn.dataset.lessonId, routeId, worldId: btn.dataset.worldId, returnTo: { view: 'reinforcement_center', payload: { routeId, worldId: btn.dataset.worldId, openWorldIds: [btn.dataset.worldId] } } });
  }));
}


function inferModuleWorldId(item = null, fallbackWorldId = '') {
  const raw = String(fallbackWorldId || item?.worldId || item?.world || item?.id || '').trim();
  const m = raw.match(/world_(\d+)/i) || raw.match(/\bM\s*(\d{1,2})\b/i) || raw.match(/-M(\d{1,2})\b/i);
  const n = m ? Number(m[1]) : 0;
  return n >= 1 && n <= 30 ? `world_${n}` : (fallbackWorldId || ui.payload?.worldId || getCurrentWorld()?.id || 'world_1');
}

function inferModuleRouteId(routeId = '', item = null) {
  const candidate = String(routeId || ui.payload?.routeId || '').trim();
  if (['ruta_1','ruta_2','ruta_3','ruta_4'].includes(candidate)) return candidate;
  const raw = `${item?.id || ''} ${item?.level || ''} ${item?.world || ''}`.toUpperCase();
  if (/\bB2\b/.test(raw)) return 'ruta_4';
  if (/\bB1\b/.test(raw)) return 'ruta_3';
  if (/\bA2\b/.test(raw)) return 'ruta_2';
  return state.progress.currentRouteId || 'ruta_1';
}

function renderSupportModuleNav(worldId = '', routeId = '', options = {}) {
  const mode = options.mode || 'modal';
  const activeRouteId = inferModuleRouteId(routeId);
  const activeWorldId = inferModuleWorldId(null, worldId);
  const closeTitle = mode === 'modal' ? 'Cerrar' : 'Cerrar módulo';
  return `
    <div class="support-module-nav ${mode === 'page' ? 'page-nav' : 'modal-nav'}" data-support-route-id="${escapeHtml(activeRouteId)}" data-support-world-id="${escapeHtml(activeWorldId)}">
      <button type="button" class="support-nav-x" data-support-nav="close" title="${closeTitle}" aria-label="${closeTitle}">✕</button>
      <div class="support-nav-actions" aria-label="Navegación del módulo">
        <button type="button" class="btn btn-soft btn-sm support-nav-btn" data-support-nav="reinforcement" title="Volver al Centro de refuerzo">🔁 <span>Centro de refuerzo</span></button>
        <button type="button" class="btn btn-secondary btn-sm support-nav-btn" data-support-nav="world" title="Volver a Parada seleccionada">🚌 <span>Parada seleccionada</span></button>
        <button type="button" class="btn btn-secondary btn-sm support-nav-btn" data-support-nav="road" title="Volver a Carretera principal">🛣️ <span>Carretera principal</span></button>
      </div>
    </div>`;
}

function bindSupportModuleNav(defaultWorldId = '', defaultRouteId = '', options = {}) {
  const mode = options.mode || 'modal';
  document.querySelectorAll('[data-support-nav]').forEach(btn => btn.addEventListener('click', (event) => {
    event.preventDefault();
    event.stopPropagation();
    const wrap = btn.closest('.support-module-nav');
    const routeId = inferModuleRouteId(wrap?.dataset.supportRouteId || defaultRouteId);
    const worldId = inferModuleWorldId(null, wrap?.dataset.supportWorldId || defaultWorldId);
    const action = btn.dataset.supportNav;
    const returnTo = ui.payload?.returnTo;
    const reinforcementPayload = (returnTo && returnTo.view === 'reinforcement_center')
      ? { ...(returnTo.payload || {}) }
      : { routeId, worldId, openWorldIds: worldId ? [worldId] : [] };
    if (mode === 'modal') closeModal();
    if (action === 'close') {
      if (mode === 'page') {
        if (returnTo?.view) setView(returnTo.view, returnTo.payload || {});
        else setView('route', { routeId, worldId });
      }
      return;
    }
    if (action === 'reinforcement') return setView('reinforcement_center', reinforcementPayload);
    if (action === 'world') return setView('route', { routeId, worldId });
    if (action === 'road') return setView('route', { routeId });
  }));
}


function renderApp() {
  if (!state?.profile?.onboarded && !['onboarding', 'welcome'].includes(ui.view)) {
    ui.view = 'onboarding';
    ui.payload = { fromLogout: true, forceUserSelector: true };
  }
  // Cerrar splash en el primer render
  const $splash = document.getElementById('app-splash');
  if ($splash) {
    $splash.classList.add('splash-out');
    setTimeout(() => { if ($splash.parentNode) $splash.parentNode.removeChild($splash); }, 600);
  }
  renderHeader();
  // ── Fondo ambiental temático ──────────────────────────────────────────────
  requestAnimationFrame(() => renderAmbientBackground());
  // ──────────────────────────────────────────────────────────────────────────
  if (ui.view === 'welcome') renderWelcome();
  else if (ui.view === 'onboarding') renderOnboarding();
  else if (ui.view === 'dashboard') {
    ui.view = 'route';
    ui.payload = buildRouteHomePayload(false);
    state.progress.lastSeenView = 'route';
    saveState();
    renderRoute();
  }
  else if (ui.view === 'route') renderRoute();
  else if (ui.view === 'lesson') renderLesson();
  else if (ui.view === 'game') renderGameHub();
  else if (ui.view === 'exercise') renderExercise();
  else if (ui.view === 'conversation') renderConversation();
  else if (ui.view === 'conversation_reinforcement') renderConversationReinforcement();
  else if (ui.view === 'reinforcement_center') renderReinforcementCenter();
  else if (ui.view === 'completion') renderCompletion();
  else if (ui.view === 'settings') renderSettings();
  else if (ui.view === 'review') renderReview();
  else if (ui.view === 'assessment') renderAssessment();
  else if (ui.view === 'assessment_result') renderAssessmentResult();
  else if (ui.view === 'knowledge' || ui.view === 'dictionary' || ui.view === 'library') renderKnowledgeHub();
  else if (ui.view === 'translation') renderTranslationPractice();
  else if (ui.view === 'progress_route') renderProgressRoute();
  else if (ui.view === 'certificates') renderCertificates();
  else renderDashboard();
  renderModal();
  renderToasts();
  renderBottomDock();
  checkTour();
}



function getStudyPresetOptions() { return [5, 10, 15, 20]; }
function getStudyPreset() {
  const options = getStudyPresetOptions();
  const value = Number(state.preferences.sessionPresetMins || 10);
  return options.includes(value) ? value : 10;
}
function setStudyPreset(minutes, rerender = true) {
  const value = Number(minutes);
  if (!getStudyPresetOptions().includes(value)) return;
  state.preferences.sessionPresetMins = value;
  saveState();
  if (rerender) renderApp();
}
function getPromptedAssessmentMilestones() {
  return Array.isArray(state.progress.assessments?.promptedMilestones) ? state.progress.assessments.promptedMilestones : [];
}
function hasAssessmentPrompted(milestone) {
  return getPromptedAssessmentMilestones().includes(Number(milestone));
}
function markAssessmentPrompted(milestone) {
  const m = Number(milestone || 0);
  if (!m) return;
  if (!Array.isArray(state.progress.assessments.promptedMilestones)) state.progress.assessments.promptedMilestones = [];
  if (!state.progress.assessments.promptedMilestones.includes(m)) {
    state.progress.assessments.promptedMilestones.push(m);
    saveState();
  }
}
