function ensureExperienceRatingsState() {
  if (!state.progress.experienceRatings || typeof state.progress.experienceRatings !== 'object') {
    state.progress.experienceRatings = { records: [], promptedWorlds: [], exitPromptCount: 0, lastPromptedAt: null };
  }
  const ratings = state.progress.experienceRatings;
  if (!Array.isArray(ratings.records)) ratings.records = [];
  if (!Array.isArray(ratings.promptedWorlds)) ratings.promptedWorlds = [];
  ratings.exitPromptCount = Number(ratings.exitPromptCount || 0);
  return ratings;
}

function getExperienceRatingMetrics() {
  const ratings = ensureExperienceRatingsState();
  const records = ratings.records || [];
  const total = records.length;
  const sum = records.reduce((acc, item) => acc + Number(item.rating || 0), 0);
  const comments = records.filter(item => String(item.comment || '').trim());
  return {
    total,
    average: total ? Math.round((sum / total) * 10) / 10 : 0,
    lastRating: total ? records[records.length - 1].rating : null,
    lastRatedAt: total ? records[records.length - 1].createdAt : null,
    commentsCount: comments.length,
    records,
    comments
  };
}

function saveExperienceRating({ rating, comment = '', context = 'manual', worldId = '', routeId = '' }) {
  const ratings = ensureExperienceRatingsState();
  const value = Math.max(1, Math.min(5, Number(rating || 0)));
  if (!value) return false;
  ratings.records.push({
    id: `rating_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`,
    rating: value,
    comment: String(comment || '').trim(),
    context,
    worldId: worldId || '',
    routeId: routeId || state.progress.currentRouteId || '',
    createdAt: new Date().toISOString(),
    appVersion: APP_VERSION
  });
  ratings.lastPromptedAt = new Date().toISOString();
  saveState();
  return true;
}

function exportExperienceCommentsTXT() {
  const metrics = getExperienceRatingMetrics();
  const lines = [
    'Easy English Go · Comentarios de experiencia',
    `Exportado: ${new Date().toLocaleString('es-CO')}`,
    `Total de calificaciones: ${metrics.total}`,
    `Promedio: ${metrics.average || '—'}/5`,
    '',
    'Comentarios:',
    ''
  ];
  if (!metrics.comments.length) {
    lines.push('Sin comentarios textuales registrados.');
  } else {
    metrics.comments.forEach((item, index) => {
      lines.push(`${index + 1}. ${item.createdAt || ''}`);
      lines.push(`   Calificación: ${item.rating}/5`);
      lines.push(`   Contexto: ${item.context || 'manual'} · Ruta: ${item.routeId || '—'} · Mundo: ${item.worldId || '—'}`);
      lines.push(`   Comentario: ${item.comment}`);
      lines.push('');
    });
  }
  const blob = new Blob([lines.join('\n')], { type: 'text/plain;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const stamp = new Date().toISOString().slice(0,19).replace(/[:T]/g, '-');
  const link = document.createElement('a');
  link.href = url;
  link.download = `easy_english_go_comentarios_experiencia_${stamp}.txt`;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 300);
  showToast('Comentarios de experiencia exportados en TXT.', 'success');
}

function openExperienceRatingModal(context = 'manual', payload = {}) {
  let selectedRating = Number(payload.defaultRating || 0);
  const contextLabel = context === 'world_complete' ? 'este mundo' : context === 'exit' ? 'tu experiencia de hoy' : 'la experiencia';
  openModal({
    customRender: () => `
      <div class="modal-overlay on" role="dialog" aria-modal="true" aria-labelledby="experience-rating-title">
        <div class="modal experience-rating-modal">
          <div class="modal-h">
            <strong id="experience-rating-title">Califica ${escapeHtml(contextLabel)}</strong>
            <button class="btn btn-soft btn-small" id="experience-rating-later">Ahora no</button>
          </div>
          <div class="modal-b experience-rating-body">
            <p class="muted">Tu opinión queda guardada solo como métrica interna de esta app.</p>
            <div class="rating-stars" role="group" aria-label="Calificación de experiencia">
              ${[1,2,3,4,5].map(value => `<button type="button" class="rating-star" data-rating-value="${value}" aria-label="${value} estrella${value === 1 ? '' : 's'}">☆</button>`).join('')}
            </div>
            <label class="field rating-comment-field">
              <span>Comentario opcional</span>
              <textarea id="experience-rating-comment" class="input rating-comment-input" rows="3" maxlength="280" placeholder="¿Qué te gustó o qué mejorarías?"></textarea>
            </label>
          </div>
          <div class="modal-f">
            <button class="btn btn-secondary" id="experience-rating-skip">Omitir</button>
            <button class="btn btn-primary" id="experience-rating-save" disabled>Guardar calificación</button>
          </div>
        </div>
      </div>`,
    afterRender: () => {
      const syncStars = () => {
        document.querySelectorAll('.rating-star').forEach(btn => {
          const value = Number(btn.dataset.ratingValue || 0);
          btn.textContent = value <= selectedRating ? '★' : '☆';
          btn.classList.toggle('active', value <= selectedRating);
        });
        const saveBtn = document.getElementById('experience-rating-save');
        if (saveBtn) saveBtn.disabled = !selectedRating;
      };
      document.querySelectorAll('.rating-star').forEach(btn => btn.addEventListener('click', () => {
        selectedRating = Number(btn.dataset.ratingValue || 0);
        syncStars();
      }));
      const closeAndMaybeContinue = () => {
        closeModal();
        if (payload.afterClose) payload.afterClose();
      };
      document.getElementById('experience-rating-later')?.addEventListener('click', closeAndMaybeContinue);
      document.getElementById('experience-rating-skip')?.addEventListener('click', closeAndMaybeContinue);
      document.getElementById('experience-rating-save')?.addEventListener('click', () => {
        const comment = document.getElementById('experience-rating-comment')?.value || '';
        saveExperienceRating({
          rating: selectedRating,
          comment,
          context,
          worldId: payload.worldId || '',
          routeId: payload.routeId || state.progress.currentRouteId || ''
        });
        showToast('Gracias. Tu calificación quedó registrada.', 'success');
        closeAndMaybeContinue();
      });
      syncStars();
    }
  });
}

function maybePromptExperienceRating(context = 'manual', payload = {}) {
  const ratings = ensureExperienceRatingsState();
  if (context === 'world_complete') {
    const key = `${payload.routeId || state.progress.currentRouteId || ''}::${payload.worldId || ''}`;
    if (!payload.worldId || ratings.promptedWorlds.includes(key)) return false;
    ratings.promptedWorlds.push(key);
    ratings.lastPromptedAt = new Date().toISOString();
    saveState();
    window.setTimeout(() => openExperienceRatingModal(context, payload), 420);
    return true;
  }
  if (context === 'exit') {
    ratings.exitPromptCount = Number(ratings.exitPromptCount || 0) + 1;
    ratings.lastPromptedAt = new Date().toISOString();
    saveState();
    openExperienceRatingModal(context, payload);
    return true;
  }
  openExperienceRatingModal(context, payload);
  return true;
}

