  document.getElementById('view-route-btn-2').onclick = () => setView('route', { routeId: state.progress.currentRouteId });
  document.getElementById('view-review-btn').onclick = () => setView('review');
  document.getElementById('go-users-btn').onclick = () => setView('welcome');
  document.getElementById('dashboard-open-manual')?.addEventListener('click', openManualModal);
  document.getElementById('dashboard-open-tour')?.addEventListener('click', () => startContextTour({ view: 'dashboard', force: true }));
  document.getElementById('dashboard-savedpoint-help')?.addEventListener('click', () => openInfoModal('savedPoint'));
