function renderReview() {
  const routeId = state.progress.currentRouteId;
  const review = getReviewSummary(routeId);
  const smart = getUnifiedReinforcementSummary(routeId);
  const stats = getAchievementStats(routeId);
  const firstTarget = getUnifiedReinforcementFirstTarget(smart);

  const exerciseCards = review.entries.length ? review.entries.map((entry, idx) => {
    const target = getReviewTarget(entry);
    const title = compactStationTitle(entry.lesson, idx);
    const totalIssues = entry.wrongIds.length + entry.pendingIds.length;
    return `
      <article class="review-focus-card">
        <div class="review-focus-icon">🎯</div>
        <div class="review-focus-copy">
          <strong>${escapeHtml(title)}</strong>
          <span>${entry.wrongIds.length ? `${entry.wrongIds.length} error${entry.wrongIds.length === 1 ? '' : 'es'}` : ''}${entry.wrongIds.length && entry.pendingIds.length ? ' · ' : ''}${entry.pendingIds.length ? `${entry.pendingIds.length} pendiente${entry.pendingIds.length === 1 ? '' : 's'}` : ''}</span>
        </div>
        <button class="btn btn-primary btn-sm review-open-btn" data-review-open="${entry.lesson.id}">${target?.cta || 'Abrir'}</button>
      </article>`;
  }).join('') : '';

  const conversationCards = smart.conversation.length ? smart.conversation.slice(0, 8).map((item) => {
    const lesson = item.lessonId ? getLessonById(item.lessonId) : null;
    const label = lesson ? lesson.title : (item.worldId ? `M${getWorldNumberFromId(item.worldId)}` : 'Diálogo');
    const attempts = Number(item.attempts || item.reinforcementAttempts || 1);
    return `
      <article class="review-focus-card review-focus-conversation">
        <div class="review-focus-icon">💬</div>
        <div class="review-focus-copy">
          <strong>${escapeHtml(label)}</strong>
          <span>Respuesta fallada en diálogo${attempts > 1 ? ` · ${attempts} intentos` : ''}</span>
        </div>
        <button class="btn btn-primary btn-sm review-conversation-btn" data-reinforce-conversation="${escapeHtml(item.queueId)}">Reforzar</button>
      </article>`;
  }).join('') : '';

  const assessmentCards = smart.assessments.length ? smart.assessments.slice(0, 6).map((item) => {
    const label = item.milestone === 'final'
      ? (item.levelCode ? `Final ${item.levelCode}` : 'Evaluación final')
      : `Evaluación M${item.startWorld || ''}–M${item.endWorld || ''}`;
    const focusCount = (item.wrongFocuses || []).length || (item.wrongLessonIds || []).length || 1;
    return `
      <article class="review-focus-card review-focus-assessment">
        <div class="review-focus-icon">🧪</div>
        <div class="review-focus-copy">
          <strong>${escapeHtml(label)}</strong>
          <span>${focusCount} foco${focusCount === 1 ? '' : 's'} por reforzar</span>
        </div>
        <button class="btn btn-secondary btn-sm review-assessment-btn" data-reinforce-assessment="${escapeHtml(item.id)}">Abrir foco</button>
      </article>`;
  }).join('') : '';

  const cards = (exerciseCards + conversationCards + assessmentCards) || `
      <article class="review-clean-state">
        <div class="review-clean-icon">✅</div>
        <div><h3>Refuerzo limpio</h3><p class="muted">No hay errores pendientes. Puedes seguir avanzando o subir la intensidad.</p></div>
        <div class="review-clean-actions">
          <button class="btn btn-primary btn-sm" id="review-go-world-btn">🚌 Seguir mundo</button>
          <button class="btn btn-secondary btn-sm" id="review-intensity-btn">⚙️ Intensidad</button>
        </div>
      </article>`;

  $main.innerHTML = `
    <section class="review-smart-shell">
      <article class="review-hero-action card panel">
        <div class="review-hero-title">
          <span class="review-hero-icon">🔁</span>
          <div>
            <span class="section-kicker">Refuerzo inteligente</span>
            <h2>Vamos solo a lo que fallaste o dejaste pendiente</h2>
          </div>
        </div>
        <div class="review-metric-grid">
          <div class="review-metric"><span>🎯</span><strong>${smart.exerciseWrong}</strong><small>errores de ejercicios</small></div>
          <div class="review-metric"><span>💬</span><strong>${smart.conversationCount}</strong><small>respuestas de diálogo</small></div>
          <div class="review-metric"><span>🧪</span><strong>${smart.assessmentCount}</strong><small>focos de evaluación</small></div>
        </div>
        <div class="review-action-row">
          <button class="btn btn-primary" id="review-next-btn">🔁 Retomar foco</button>
          <button class="btn btn-secondary icon-action" id="review-route-btn" title="Ver carretera" aria-label="Ver carretera">🏠</button>
          <button class="btn btn-secondary icon-action" id="review-world-btn" title="Volver al mundo" aria-label="Volver al mundo">🚌</button>
          <button class="btn btn-secondary icon-action" id="review-listen-btn" title="Escuchar y repasar" aria-label="Escuchar y repasar">🎧</button>
          <button class="btn btn-secondary icon-action" id="review-words-btn" title="Ver palabras débiles" aria-label="Ver palabras débiles">Aa</button>
        </div>
      </article>
      <article class="review-signal-strip card panel">
        <span>🔁 ${smart.totalItems} pendiente${smart.totalItems === 1 ? '' : 's'} reales</span>
        <span>✅ ${stats.totalCorrect} aciertos</span>
        <span>🌟 ${stats.masteryLessons} dominio alto</span>
      </article>
      <section class="review-focus-list">${cards}</section>
    </section>`;

  document.getElementById('review-next-btn')?.addEventListener('click', () => openUnifiedReinforcementTarget(firstTarget));
  document.getElementById('review-route-btn')?.addEventListener('click', () => goToRoadHome());
  document.getElementById('review-world-btn')?.addEventListener('click', () => goToCurrentWorldMissions());
  document.getElementById('review-listen-btn')?.addEventListener('click', () => openAudioReviewPanel());
  document.getElementById('review-words-btn')?.addEventListener('click', () => setView('knowledge'));
  document.getElementById('review-go-world-btn')?.addEventListener('click', () => goToCurrentWorldMissions());
  document.getElementById('review-intensity-btn')?.addEventListener('click', () => setView('settings', { section: 'intensity' }));

  document.querySelectorAll('.review-open-btn').forEach(btn => btn.addEventListener('click', () => {
    const entry = review.entries.find(item => item.lesson.id === btn.dataset.reviewOpen);
    const target = getReviewTarget(entry);
    if (target) setView(target.view, target.payload);
  }));
  document.querySelectorAll('.review-conversation-btn').forEach(btn => btn.addEventListener('click', () => {
    const item = smart.conversation.find(entry => entry.queueId === btn.dataset.reinforceConversation);
    if (!item) return;
    startConversationReinforcement(item.worldId || item.lessonId || null, item.conversationId || null);
  }));
  document.querySelectorAll('.review-assessment-btn').forEach(btn => btn.addEventListener('click', () => {
    const record = smart.assessments.find(item => item.id === btn.dataset.reinforceAssessment);
    if (!record) return;
    if (record.wrongLessonIds?.[0]) setView('lesson', { lessonId: record.wrongLessonIds[0] });
    else openAssessmentReinforcementModal(record.id, record.wrongFocuses || [], record.wrongLessonIds || []);
  }));
}

// ══════════════════════════════════════════════════════════════════════════════
// A2 — FRANJA DE RACHA VISIBLE
// ══════════════════════════════════════════════════════════════════════════════
function renderStreakBar() {
  const streak = getXPStreakDays ? getXPStreakDays() : (state.progress?.xp?.streakDays || 0);
  const xp     = getTotalXP     ? getTotalXP()      : (state.progress?.xp?.total || 0);
  if (streak < 1) return '';
  return `
    <div class="streak-bar" id="streak-bar" aria-label="Racha activa">
      <span class="streak-badge">🔥 ${streak} día${streak !== 1 ? 's' : ''}</span>
      <span class="streak-bar-text">Racha activa · <strong>${xp.toLocaleString('es')}</strong> XP total</span>
    </div>`;
}

// ══════════════════════════════════════════════════════════════════════════════
// B2 — CARD MOTIVADORA CONTEXTUAL (Opción C aprobada)
// Aparece máximo 1 vez por sesión. Solo si racha > 0.
// Contextual: mañana=energizante, noche=reflexivo, racha alta=celebratorio.
// ══════════════════════════════════════════════════════════════════════════════
function renderMotiveCard() {
  const streak = getXPStreakDays ? getXPStreakDays() : (state.progress?.xp?.streakDays || 0);
  if (streak < 1) return '';

  // Solo una vez por sesión
  if (sessionStorage.getItem('ipd_motive_shown')) return '';
  sessionStorage.setItem('ipd_motive_shown', '1');

  const hour  = new Date().getHours();
  const name  = (state.profile?.name || '').trim();
  const hello = name ? `, ${name}` : '';

  // Banco de frases por contexto
  const frases = {
    madrugada: [
      { emoji: '🌙', text: `Madrugando a aprender${hello}. Eso dice mucho de ti.` },
      { emoji: '✨', text: `Pocas personas estudian a esta hora. Tú sí.` },
    ],
    mañana: [
      { emoji: '🌅', text: `Buenos días${hello}. El inglés empieza donde empieza el día.` },
      { emoji: '☕', text: `La mejor forma de comenzar${hello ? ` tu día, ${name}` : ' el día'}: una lección.` },
    ],
    tarde: [
      { emoji: '💡', text: `Buenas tardes${hello}. Cada lección es una conversación que ya puedes tener.` },
      { emoji: '🎯', text: `Tarde productiva${hello}. El inglés no se aprende solo, pero tú lo estás logrando.` },
    ],
    noche: [
      { emoji: '🌆', text: `Al final del día${hello}, lo que practicaste hoy ya es tuyo.` },
      { emoji: '📖', text: `Buenas noches${hello}. Una lección antes de dormir consolida más de lo que crees.` },
    ],
    celebratorio: [
      { emoji: '🏆', text: `${streak} días seguidos${hello}. Eso no es suerte — es decisión.` },
      { emoji: '🔥', text: `${streak} días de racha${hello}. Estás construyendo algo real.` },
    ],
  };

  let pool;
  if (streak >= 7)          pool = frases.celebratorio;
  else if (hour < 6)        pool = frases.madrugada;
  else if (hour < 12)       pool = frases.mañana;
  else if (hour < 19)       pool = frases.tarde;
  else                      pool = frases.noche;

  const frase = pool[Math.floor(Math.random() * pool.length)];

  return `
    <div class="motive-card" id="motive-card" role="status" aria-live="polite">
      <span class="motive-emoji" aria-hidden="true">${frase.emoji}</span>
      <span class="motive-text">${escapeHtml(frase.text)}</span>
      <button class="motive-close" id="motive-close-btn" type="button" aria-label="Cerrar mensaje motivador">Cerrar</button>
    </div>`;
}

