function getCuratedWorldThemeKey(world, routeCode = '') {
  const key = String(routeCode || '').toUpperCase();
  const index = Number.isFinite(world?.index) ? world.index : null;
  if (index == null) return null;
  return CURATED_WORLD_THEME_KEYS[key]?.[index] || null;
}

function getCuratedWorldSceneKey(world, routeCode = '') {
  const key = String(routeCode || '').toUpperCase();
  const index = Number.isFinite(world?.index) ? world.index : null;
  if (index == null) return null;
  return CURATED_WORLD_SCENE_KEYS[key]?.[index] || null;
}

function getWorldThemeProfile(world, routeCode = '') {
  const title = normalizeText((world?.title || '') + ' ' + (world?.subtitle || '') + ' ' + (world?.scene || ''));
  const checks = [
    { key: 'digital', words: ['digital','tecnolog','online','chat','mensaje','creacion digital','computer','comunicacion diaria'] },
    { key: 'home', words: ['familia','casa','hogar','convivencia','home','house','family','persona cercana'] },
    { key: 'travel', words: ['transporte','viaje','direcciones','reserva','reservas','hotel','aeropuerto','ruta','moverse','trav','budapest'] },
    { key: 'food', words: ['comida','compras','shopping','restaurant','restaurante','caf','pedidos','delivery','pan','banana','price','servicios y gestion'] },
    { key: 'study', words: ['aula','aprendiz','estudio','investigacion','lectura','school','book','learning','clase'] },
    { key: 'work', words: ['trabajo','tramites','proyecto','reunion','oficina','labor','empleo','job','negoci','entrevista','argumentar'] },
    { key: 'health', words: ['salud','cuerpo','bienestar','mente','health','body','mind'] },
    { key: 'nature', words: ['comunidad','ciudad','parque','social','hobbies','arte','entretenimiento','eventos','life','world','outdoor'] }
  ];
  const found = checks.find(item => item.words.some(word => title.includes(word)));
  const defaults = { A1: 'social', A2: 'city', B1: 'travel', B2: 'work' };
  const curatedKey = getCuratedWorldThemeKey(world, routeCode);
  const key = curatedKey || found?.key || defaults[routeCode] || 'city';
  const profiles = {
    social: { key:'social', label:'social', skyline:'people', accent:'chat' },
    home: { key:'home', label:'home', skyline:'homes', accent:'home' },
    city: { key:'city', label:'city', skyline:'city', accent:'city' },
    travel: { key:'travel', label:'travel', skyline:'travel', accent:'travel' },
    food: { key:'food', label:'food', skyline:'market', accent:'food' },
    study: { key:'study', label:'study', skyline:'study', accent:'study' },
    work: { key:'work', label:'work', skyline:'office', accent:'work' },
    health: { key:'health', label:'health', skyline:'health', accent:'health' },
    digital: { key:'digital', label:'digital', skyline:'tech', accent:'digital' },
    nature: { key:'nature', label:'nature', skyline:'park', accent:'nature' }
  };
  return profiles[key] || profiles.city;
}

