function splitReadableParts(text) {
  return String(text || '')
    .split(/(?<=[.!?])\s+/)
    .map(part => part.trim())
    .filter(Boolean);
}

function buildMandatoryGuidedPrompt(exercise) {
  return '';
}


function splitGuidedSentences(text = '') {
  return String(text || '')
    .replace(/\s+/g, ' ')
    .split(/(?<=[.!?])\s+/)
    .map(part => part.trim())
    .filter(Boolean);
}

function stripGuidedLead(text = '', lessonTitle = '') {
  let value = String(text || '').replace(/\s+/g, ' ').trim();
  const title = String(lessonTitle || '').trim();
  if (!value) return '';
  if (title) {
    const safeTitle = title.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    value = value.replace(new RegExp(`^In\\s+${safeTitle},?\\s*`, 'i'), '');
    value = value.replace(new RegExp(`^In\\s+${safeTitle}\\s+\\d+,?\\s*`, 'i'), '');
    value = value.replace(new RegExp(`^Because\\s+${safeTitle}\\s+involved\\s+`, 'i'), 'Because ');
  }
  value = sanitizeSpeakerReference(value);
  value = value.replace(/^i\s+/i, 'I ');
  value = value.replace(/^because\s+/i, 'Because ');
  return value.charAt(0).toUpperCase() + value.slice(1);
}

function trimGuidedLine(text = '', maxLen = 132) {
  const clean = String(text || '').replace(/\s+/g, ' ').trim();
  if (!clean) return '';
  if (clean.length <= maxLen) return clean;
  const cut = clean.slice(0, maxLen - 1);
  const lastSpace = cut.lastIndexOf(' ');
  const safe = lastSpace > 40 ? cut.slice(0, lastSpace) : cut;
  return `${safe.trim()}…`;
}

function buildGuidedSituationLines(exercise, lesson) {
  const lessonTitle = lesson?.title || '';
  const scenario = trimGuidedLine(exercise.scenario || exercise.scene || '', 150);
  if (exercise.type === 'listen_choice') {
    const source = stripGuidedLead(exercise.audioText || exercise.supportText || exercise.prompt || '', lessonTitle);
    const parts = splitGuidedSentences(source);
    const second = trimGuidedLine(parts[0] || source || 'Listen for the main idea before choosing.', 150);
    return [scenario || 'Escucha la situación y sigue la idea principal del hablante.', second]
      .filter(Boolean)
      .filter((line, index, arr) => arr.findIndex(value => value.toLowerCase() === line.toLowerCase()) === index)
      .slice(0, 2);
  }
  if (exercise.type === 'reading_choice') {
    const source = stripGuidedLead(exercise.prompt || exercise.supportText || '', lessonTitle);
    const parts = splitGuidedSentences(source).filter(part => !/^(Which|What)\b/i.test(part));
    const first = scenario || trimGuidedLine(parts[0] || 'Lee el texto guía y ubica la idea principal.', 150);
    const fallbackSecond = exercise.question || 'Elige la opción que mejor interpreta el texto.';
    const second = trimGuidedLine(parts[1] || (parts[0] && parts[0] !== first ? parts[0] : fallbackSecond), 150);
    return [first, second]
      .filter(Boolean)
      .filter((line, index, arr) => arr.findIndex(value => value.toLowerCase() === line.toLowerCase()) === index)
      .slice(0, 2);
  }
  return [];
}

