  const queueIds = getExerciseQueueForView(lesson, ui.payload);
  const rescueMode = Boolean(ui.payload.rescueMode && queueIds.length);
  const queueIndex = getExerciseQueueIndex(queueIds, ui.payload);
  const exerciseId = queueIds[queueIndex];
  let exercise = getExerciseById(exerciseId);
