function getExpectedCacheName() {
  return `easy-english-go-${APP_VERSION}`;
}

function getStorageSizeSafe(key) {
  try {
    const value = localStorage.getItem(key);
    return value ? new Blob([value]).size : 0;
  } catch (error) {
    return 0;
  }
}

async function clearOldAppShellCaches({ includeCurrent = false } = {}) {
  if (typeof caches === 'undefined') return [];
  const expected = getExpectedCacheName();
  const keys = await caches.keys();
  const targets = keys.filter(key => {
    const related = /easy-english-go|ingles-dummies|ingles-dummies/i.test(key);
    if (!related) return false;
    return includeCurrent || key !== expected;
  });
  await Promise.all(targets.map(key => caches.delete(key)));
  return targets;
}

function hideUpdateBanner() {
  document.querySelector('.app-update-banner')?.remove();
}

function showUpdateBanner(message = 'Nueva versión disponible. Actualizar ahora.') {
  if (typeof document === 'undefined') return;
  const dismissed = localStorage.getItem(APP_UPDATE_DISMISSED_KEY);
  if (dismissed === APP_VERSION && !/instalada|disponible/i.test(message)) return;
  hideUpdateBanner();
  const banner = document.createElement('div');
  banner.className = 'app-update-banner';
  banner.innerHTML = `
    <div class="app-update-copy">
      <strong>✨ ${escapeHtml(message)}</strong>
      <small>Versión activa: ${escapeHtml(APP_VERSION)}. Sirve para evitar caché vieja del navegador o la PWA.</small>
    </div>
    <div class="app-update-actions">
      <button type="button" class="btn btn-primary btn-small" id="app-update-now-btn">Actualizar ahora</button>
      <button type="button" class="btn btn-soft btn-small" id="app-update-later-btn" aria-label="Cerrar aviso">Luego</button>
    </div>`;
  document.body.appendChild(banner);
  document.getElementById('app-update-later-btn')?.addEventListener('click', () => {
    localStorage.setItem(APP_UPDATE_DISMISSED_KEY, APP_VERSION);
    hideUpdateBanner();
  });
  document.getElementById('app-update-now-btn')?.addEventListener('click', async () => {
    try {
      localStorage.setItem(APP_VERSION_SEEN_KEY, APP_VERSION);
      localStorage.removeItem(APP_UPDATE_DISMISSED_KEY);
      await clearOldAppShellCaches({ includeCurrent: false });
      if ('serviceWorker' in navigator) {
        const registration = await navigator.serviceWorker.getRegistration();
        if (registration?.waiting) registration.waiting.postMessage({ type: 'SKIP_WAITING' });
        if (registration?.update) await registration.update().catch(() => null);
      }
    } catch (error) {
      console.warn('No se pudo limpiar caché antes de actualizar.', error);
    }
    location.reload();
  });
}

function maybeShowVersionUpdateBanner() {
  try {
    const seen = localStorage.getItem(APP_VERSION_SEEN_KEY);
    if (seen !== APP_VERSION) {
      showUpdateBanner(seen ? 'Nueva versión disponible. Actualizar ahora.' : 'Versión instalada. Actualizar ahora.');
    }
  } catch (error) {
    console.warn('No se pudo comprobar versión vista.', error);
  }
}

function enhanceServiceWorkerRegistration(registration) {
  if (!registration || typeof window === 'undefined') return;
  try {
    if (registration.waiting && navigator.serviceWorker.controller) {
      showUpdateBanner('Nueva versión disponible. Actualizar ahora.');
    }
    registration.addEventListener('updatefound', () => {
      const worker = registration.installing;
      if (!worker) return;
      worker.addEventListener('statechange', () => {
        if (worker.state === 'installed' && navigator.serviceWorker.controller) {
          showUpdateBanner('Nueva versión disponible. Actualizar ahora.');
        }
      });
    });
    if (!window.__EEG_CONTROLLER_CHANGE_BOUND) {
      window.__EEG_CONTROLLER_CHANGE_BOUND = true;
      navigator.serviceWorker.addEventListener('controllerchange', () => {
        showUpdateBanner('Nueva versión instalada. Actualizar ahora.');
      });
    }
    registration.update?.().catch(() => null);
  } catch (error) {
    console.warn('No se pudo activar watcher de actualización.', error);
  }
}

function collectDiagnosticsSnapshot() {
  const c = CONTENT || FALLBACK_CONTENT || {};
  const activeUser = storageEnvelope?.users?.[storageEnvelope?.activeUserId];
  let validationIssues = [];
  try { validationIssues = validateContent(c) || []; } catch (error) { validationIssues = [`No se pudo validar contenido: ${error.message}`]; }
  const localStorageKeys = [];
  try {
    for (let i = 0; i < localStorage.length; i += 1) {
      const key = localStorage.key(i);
      if (!key) continue;
      if (/easy|english|ingles|dialogue|audio|deepIntegrator/i.test(key)) {
        localStorageKeys.push({ key, sizeBytes: getStorageSizeSafe(key) });
      }
    }
  } catch (error) {}
  return {
    version: APP_VERSION,
    expectedCache: getExpectedCacheName(),
    appTitle: c.appMeta?.title || 'Easy English Go',
    url: location.href,
    protocol: location.protocol,
    userAgent: navigator.userAgent,
    online: navigator.onLine,
    contentCounts: {
      routes: c.routes?.length || 0,
      lessons: c.lessons?.length || 0,
      exercises: c.exercises?.length || 0,
      conversations: c.conversations?.length || 0,
      dictionary: c.dictionary?.length || 0,
      reviewLibrary: c.reviewLibrary?.length || 0
    },
    activeUser: {
      id: storageEnvelope?.activeUserId || null,
      name: state?.profile?.name || activeUser?.state?.profile?.name || 'Sin nombre',
      onboarded: Boolean(state?.profile?.onboarded),
      currentRouteId: state?.progress?.currentRouteId,
      currentWorldId: state?.progress?.currentWorldId,
      currentLessonId: state?.progress?.currentLessonId,
      percent: state?.progress?.percent,
      completedLessons: getCompletedLessonsCountForState(state),
      completedWorlds: getCompletedWorldCountForState(state),
      createdAt: state?.meta?.createdAt,
      updatedAt: state?.meta?.updatedAt
    },
    storage: {
      envelopeKey: STORAGE_ENVELOPE_KEY,
      activeUsers: Object.keys(storageEnvelope?.users || {}).length,
      localStorageKeys
    },
    validation: {
      issues: validationIssues.slice(0, 20),
      issueCount: validationIssues.length
    },
    serviceWorker: {
      supported: 'serviceWorker' in navigator,
      controller: navigator.serviceWorker?.controller?.scriptURL || null
    }
  };
}

async function enrichDiagnosticsAsync(snapshot) {
  const enriched = structuredCloneSafe(snapshot);
  try {
    if ('serviceWorker' in navigator) {
      const registration = await navigator.serviceWorker.getRegistration();
      enriched.serviceWorker.registration = registration ? {
        scope: registration.scope,
        active: registration.active?.state || null,
        waiting: registration.waiting?.state || null,
        installing: registration.installing?.state || null
      } : null;
    }
  } catch (error) {
    enriched.serviceWorker.error = error.message;
  }
  try {
    enriched.caches = typeof caches !== 'undefined' ? await caches.keys() : [];
  } catch (error) {
    enriched.caches = [`Error leyendo cachés: ${error.message}`];
  }
  return enriched;
}

function renderDiagnosticsHtml(snapshot, loading = true) {
  const counts = snapshot.contentCounts || {};
  const user = snapshot.activeUser || {};
  const validation = snapshot.validation || {};
  return `
    <div class="modal diagnostic-modal">
      <div class="diagnostic-head">
        <div>
          <div class="section-kicker">Diagnóstico interno</div>
          <h2>Easy English Go</h2>
          <p class="muted">Versión activa: <strong>${escapeHtml(snapshot.version)}</strong></p>
        </div>
        <button type="button" class="icon-btn" id="diagnostic-close-btn" aria-label="Cerrar">✕</button>
      </div>
      <div class="diagnostic-grid">
        <article class="diagnostic-card"><strong>Contenido</strong><span>${counts.routes} rutas</span><span>${counts.lessons} lecciones</span><span>${counts.exercises} ejercicios</span><span>${counts.conversations} conversaciones</span><span>${counts.dictionary} diccionario</span></article>
        <article class="diagnostic-card"><strong>Usuario activo</strong><span>${escapeHtml(user.name || 'Sin nombre')}</span><span>Ruta: ${escapeHtml(user.currentRouteId || '—')}</span><span>Mundo: ${escapeHtml(user.currentWorldId || '—')}</span><span>Lección: ${escapeHtml(user.currentLessonId || '—')}</span><span>Avance: ${Number(user.percent || 0)}%</span></article>
        <article class="diagnostic-card"><strong>PWA / caché</strong><span>SW: ${snapshot.serviceWorker?.supported ? 'soportado' : 'no soportado'}</span><span>Controlador: ${snapshot.serviceWorker?.controller ? 'activo' : 'sin controlador'}</span><span>Cache esperado: ${escapeHtml(snapshot.expectedCache)}</span><span id="diagnostic-cache-list">${loading ? 'Leyendo cachés…' : 'Cachés cargados'}</span></article>
        <article class="diagnostic-card"><strong>Validación</strong><span>${validation.issueCount ? `⚠️ ${validation.issueCount} observación(es)` : '✅ Sin observaciones críticas'}</span><span>Usuarios locales: ${snapshot.storage?.activeUsers ?? 0}</span><span>Conexión: ${snapshot.online ? 'en línea' : 'sin conexión'}</span></article>
      </div>
      ${validation.issueCount ? `<div class="diagnostic-issues"><strong>Primeras observaciones:</strong><pre>${escapeHtml((validation.issues || []).join('\n'))}</pre></div>` : ''}
      <pre class="diagnostic-json" id="diagnostic-json">${escapeHtml(JSON.stringify(snapshot, null, 2))}</pre>
      <div class="button-row wrap-row spacer-top">
        <button type="button" class="btn btn-primary btn-small" id="diagnostic-copy-btn">Copiar diagnóstico</button>
        <button type="button" class="btn btn-secondary btn-small" id="diagnostic-refresh-btn">Actualizar diagnóstico</button>
        <button type="button" class="btn btn-soft btn-small" id="diagnostic-clear-cache-btn">Limpiar caché vieja</button>
        <button type="button" class="btn btn-soft btn-small" id="diagnostic-reload-btn">Recargar app</button>
      </div>
    </div>`;
}

function bindDiagnosticsModal(snapshot) {
  document.getElementById('diagnostic-close-btn')?.addEventListener('click', closeModal);
  document.getElementById('diagnostic-copy-btn')?.addEventListener('click', async () => {
    const text = document.getElementById('diagnostic-json')?.textContent || JSON.stringify(snapshot, null, 2);
    try { await navigator.clipboard.writeText(text); showToast('Diagnóstico copiado.'); }
    catch (error) { showToast('No se pudo copiar automáticamente.'); }
  });
  document.getElementById('diagnostic-refresh-btn')?.addEventListener('click', openDiagnosticsModal);
  document.getElementById('diagnostic-clear-cache-btn')?.addEventListener('click', async () => {
    const removed = await clearOldAppShellCaches({ includeCurrent: false }).catch(() => []);
    showToast(removed.length ? `Caché vieja eliminada: ${removed.length}` : 'No había caché vieja para eliminar.');
    openDiagnosticsModal();
  });
  document.getElementById('diagnostic-reload-btn')?.addEventListener('click', () => location.reload());
}

function openDiagnosticsModal() {
  const snapshot = collectDiagnosticsSnapshot();
  openModal({
    customRender: () => renderDiagnosticsHtml(snapshot, true),
    afterRender: async () => {
      bindDiagnosticsModal(snapshot);
      const enriched = await enrichDiagnosticsAsync(snapshot);
      const jsonEl = document.getElementById('diagnostic-json');
      const cacheEl = document.getElementById('diagnostic-cache-list');
      if (jsonEl) jsonEl.textContent = JSON.stringify(enriched, null, 2);
      if (cacheEl) cacheEl.textContent = Array.isArray(enriched.caches) && enriched.caches.length ? enriched.caches.join(' · ') : 'Sin cachés registradas';
    }
  });
}

if (typeof window !== 'undefined') {
  window.EasyEnglishGoDiagnostics = {
    version: () => APP_VERSION,
    snapshot: collectDiagnosticsSnapshot,
    open: openDiagnosticsModal,
    clearOldCaches: clearOldAppShellCaches,
    showUpdateBanner
  };
}

async function init() {
  // ── BLINDAJE ANTI-SPLASH-COLGADO ─────────────────────────────────────────
  // Si init() falla por cualquier razón, el splash se cierra igual después
  // de un máximo de 6 segundos. Sin esto el usuario ve el logo eternamente.
  const SPLASH_HARD_DEADLINE = 6000; // ms máximo absoluto
  const splashGuard = setTimeout(() => {
    const s = document.getElementById('app-splash');
    if (s) { s.classList.add('splash-out'); setTimeout(() => s.remove(), 600); }
    if (typeof renderApp === 'function') { try { renderApp(); } catch(e) { console.error('renderApp en fallback:', e); } }
  }, SPLASH_HARD_DEADLINE);
  // ──────────────────────────────────────────────────────────────────────────

  try {
    CONTENT = normalizeContentForExperience(await loadContent());
    validateContent(CONTENT);
    storageEnvelope = loadStorageEnvelope();
    state = loadState();
    applyPreferences();
    // registerAppShellCache puede bloquear en algunos entornos — lo envolvemos
    await Promise.race([
      registerAppShellCache(),
      new Promise(res => setTimeout(res, 2000)) // timeout de 2 s
    ]);
    ensureReminderWatcher();
    ui.view = state.profile.onboarded ? 'welcome' : 'onboarding';
  } catch (err) {
    // Si algo falla en la cadena de inicialización, intentamos con estado limpio
    console.error('[IPD] Error en init(), usando estado de emergencia:', err);
    try {
      if (!CONTENT || !CONTENT.routes) CONTENT = normalizeContentForExperience(null);
    } catch(e2) { console.error('[IPD] CONTENT fallback fallido:', e2); }
    try {
      if (!state || !state.profile) state = createFreshState();
      ui.view = 'onboarding';
    } catch(e3) { console.error('[IPD] State fallback fallido:', e3); }
  }

  // El splash dura exactamente 3 s desde que init() resolvió (éxito o error)
  // El splashGuard de 6 s garantiza que nunca se cuelgue.
  clearTimeout(splashGuard);
  setTimeout(() => {
    try { renderApp(); maybeShowVersionUpdateBanner(); } catch(e) { console.error('[IPD] renderApp falló:', e); }
  }, 3000);
}

init();


