function auditB1B2CriticalVariety() {
  const routeIds = ['ruta_3', 'ruta_4'];
  const result = {};
  routeIds.forEach(routeId => {
    const route = getRouteById(routeId);
    const lessonIds = route?.lessonIds || [];
    const exIds = new Set();
    lessonIds.forEach(id => {
      const lesson = getLessonById(id);
      (lesson?.exerciseIds || []).forEach(exId => exIds.add(exId));
      Object.values(lesson?.exerciseSets || {}).flat().forEach(exId => exIds.add(exId));
    });
    const exs = [...exIds].map(id => getExerciseById(id)).filter(Boolean);
    ['reading_choice', 'listen_choice'].forEach(type => {
      const items = exs.filter(ex => ex.type === type);
      const corrects = items.map(ex => {
        const opts = Array.isArray(ex.options) ? ex.options : [];
        return opts[ex.correctIndex] || '';
      });
      const optionSets = items.map(ex => JSON.stringify((ex.options || []).slice().sort()));
      result[`${routeId}_${type}`] = {
        items: items.length,
        uniqueCorrect: new Set(corrects).size,
        maxCorrectRepetition: Math.max(0, ...Object.values(corrects.reduce((acc, value) => {
          acc[value] = (acc[value] || 0) + 1;
          return acc;
        }, {}))),
        uniqueOptionSets: new Set(optionSets).size
      };
    });
  });
  return result;
}
if (typeof window !== 'undefined') {
  window.IPD_QA = window.IPD_QA || {};
  window.IPD_QA.b1b2CriticalVariety = auditB1B2CriticalVariety;
}


function auditDialogueVarietyB1B2() {
  const result = {};
  ['ruta_3', 'ruta_4'].forEach(routeId => {
    const convs = (CONTENT.conversations || []).filter(conv => conv.routeId === routeId);
    const prompts = [];
    const options = [];
    const corrects = [];
    convs.forEach(conv => (conv.turns || []).forEach(turn => {
      prompts.push(turn.prompt || turn.left || '');
      (turn.options || []).forEach(option => {
        const text = option.text || option.en || '';
        options.push(text);
        if (option.correct) corrects.push(text);
      });
    }));
    result[routeId] = {
      conversations: convs.length,
      turnPrompts: prompts.length,
      uniqueTurnPrompts: new Set(prompts).size,
      options: options.length,
      uniqueOptions: new Set(options).size,
      uniqueCorrectOptions: new Set(corrects).size
    };
  });
  const b2Deep = deepIntegratorDialogues.filter(dialogue => dialogue.routeId === 'ruta_4' && /^B2-M\d+/.test(dialogue.id));
  const deepPrompts = [];
  const deepOptions = [];
  b2Deep.forEach(dialogue => (dialogue.steps || []).forEach(step => {
    deepPrompts.push(step.prompt?.en || '');
    (step.options || []).forEach(option => deepOptions.push(option.en || ''));
  }));
  result.b2Deep = {
    dialogues: b2Deep.length,
    prompts: deepPrompts.length,
    uniquePrompts: new Set(deepPrompts).size,
    options: deepOptions.length,
    uniqueOptions: new Set(deepOptions).size
  };
  return result;
}
if (typeof window !== 'undefined') {
  window.IPD_QA = window.IPD_QA || {};
  window.IPD_QA.dialogueVarietyB1B2 = auditDialogueVarietyB1B2;
}


function auditB2ContentDrift506525() {
  const checks = [
    {from:506, to:510, must:'problemas laborales', avoid:['línea de tiempo de proyecto','linea de tiempo de proyecto','project timeline']},
    {from:511, to:515, must:'proponer soluciones', avoid:['proceso técnico','technical process']},
    {from:516, to:520, must:'negociar tiempos', avoid:['avance y riesgos','progress and risks']},
    {from:521, to:525, must:'defender una propuesta', avoid:['recomendar una opción','recommend an option']}
  ];
  const issues = [];
  checks.forEach(rule => {
    for (let n = rule.from; n <= rule.to; n += 1) {
      const lesson = getLessonById(`lesson_${n}`);
      if (!lesson) {
        issues.push({lesson:`lesson_${n}`, issue:'missing lesson'});
        continue;
      }
      const text = `${lesson.title || ''} ${lesson.goal || ''} ${(lesson.blocks || []).map(b => `${b.en || ''} ${b.es || ''} ${b.text || ''}`).join(' ')}`.toLowerCase();
      if (!text.includes(rule.must)) issues.push({lesson:lesson.id, issue:`missing expected focus: ${rule.must}`});
      rule.avoid.forEach(term => {
        if (text.includes(term)) issues.push({lesson:lesson.id, issue:`drift term still present: ${term}`});
      });
      (lesson.exerciseIds || []).forEach(exId => {
        const ex = getExerciseById(exId);
        const exText = `${ex?.prompt || ''} ${ex?.scenario || ''} ${ex?.audioText || ''} ${ex?.feedbackCorrect || ''} ${ex?.feedbackWrong || ''}`.toLowerCase();
        rule.avoid.forEach(term => {
          if (exText.includes(term)) issues.push({lesson:lesson.id, exercise:exId, issue:`exercise drift term still present: ${term}`});
        });
      });
    }
  });
  return {issues, ok: issues.length === 0};
}
if (typeof window !== 'undefined') {
  window.IPD_QA = window.IPD_QA || {};
  window.IPD_QA.b2ContentDrift506525 = auditB2ContentDrift506525;
}


