function auditA2NaturalAnswers() {
  const route = getRouteById('ruta_2');
  const lessonIds = route?.lessonIds || [];
  const issues = [];
  lessonIds.forEach(lessonId => {
    const lesson = getLessonById(lessonId);
    (lesson?.exerciseIds || []).forEach(exId => {
      const ex = getExerciseById(exId);
      if (!ex || ex.type !== 'multiple_choice') return;
      const opts = Array.isArray(ex.options) ? ex.options : [];
      const correct = opts[ex.correctIndex] || '';
      const scenario = String(ex.scenario || '').toLowerCase();
      if (opts.some(opt => /That answer does not match|I do not know what to say/i.test(opt))) {
        issues.push({ exId, issue: 'meta/non-answer option still present' });
      }
      if (scenario.includes('usually') && /today|need to/i.test(correct)) {
        issues.push({ exId, issue: 'usually question with today/need correct answer', correct });
      }
      if (scenario.includes('did you') && /^I usually/i.test(correct)) {
        issues.push({ exId, issue: 'past question with usually correct answer', correct });
      }
    });
  });
  return { ok: issues.length === 0, checked: lessonIds.length, issues };
}
if (typeof window !== 'undefined') {
  window.IPD_QA = window.IPD_QA || {};
  window.IPD_QA.a2NaturalAnswers = auditA2NaturalAnswers;
}


function auditV500B1B2Rebuild() {
  const routes = ['ruta_3', 'ruta_4'];
  const issues = [];
  routes.forEach(routeId => {
    const route = getRouteById(routeId);
    const lessonIds = route?.lessonIds || [];
    if (lessonIds.length !== 150) issues.push({ routeId, issue: 'route must have 150 lessons', count: lessonIds.length });
    lessonIds.forEach(lessonId => {
      const lesson = getLessonById(lessonId);
      if (!lesson) return issues.push({ lessonId, issue: 'missing lesson' });
      if (!Array.isArray(lesson.exerciseIds) || lesson.exerciseIds.length !== 5) issues.push({ lessonId, issue: 'lesson must have 5 exercises' });
      if (/\d+$/.test(lesson.title || '')) issues.push({ lessonId, issue: 'numeric title remains', title: lesson.title });
      (lesson.exerciseIds || []).forEach(exId => {
        const ex = getExerciseById(exId);
        if (!ex) issues.push({ lessonId, exId, issue: 'missing exercise' });
        if (ex && /talks about lesson|narrar experiencias \d|escucha guiada/i.test(JSON.stringify(ex))) {
          issues.push({ lessonId, exId, issue: 'legacy abstract/redundant text' });
        }
      });
    });
  });
  return { ok: issues.length === 0, routes, issues };
}
if (typeof window !== 'undefined') {
  window.IPD_QA = window.IPD_QA || {};
  window.IPD_QA.v500B1B2Rebuild = auditV500B1B2Rebuild;
}
